#[derive(Debug)]
pub(crate) enum NativeV1SnapshotPublicationError {
    Preflight(VmmActionError),
    StoragePreflight(HvfArm64BootStorageCaptureError),
    BalloonPreflight(HvfArm64BootBalloonCaptureError),
    MemoryHotplugPreflight(HvfArm64BootMemoryHotplugCaptureError),
    EntropyPreflight(HvfArm64BootEntropyCaptureError),
    SerialPreflight(HvfArm64BootSerialCaptureError),
    NetworkPreflight(ProcessCaptureReadyNetworkError),
    VsockPreflight(HvfArm64BootVsockCaptureError),
    Resource(GrantClaimError),
    SessionUnavailable,
    ConfigurationUnavailable,
    Transaction(Box<NativeV1SnapshotPublicationTransactionError>),
}

impl fmt::Display for NativeV1SnapshotPublicationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Preflight(source) => {
                write!(f, "native-v1 publication preflight failed: {source}")
            }
            Self::StoragePreflight(source) => {
                write!(f, "native-v1 storage preflight failed: {source}")
            }
            Self::BalloonPreflight(source) => {
                write!(f, "native-v1 balloon preflight failed: {source}")
            }
            Self::MemoryHotplugPreflight(source) => {
                write!(f, "native-v1 memory-hotplug preflight failed: {source}")
            }
            Self::EntropyPreflight(source) => {
                write!(f, "native-v1 entropy preflight failed: {source}")
            }
            Self::SerialPreflight(source) => {
                write!(f, "native-v1 serial preflight failed: {source}")
            }
            Self::NetworkPreflight(source) => {
                write!(f, "native-v1 network preflight failed: {source}")
            }
            Self::VsockPreflight(source) => {
                write!(f, "native-v1 vsock preflight failed: {source}")
            }
            Self::Resource(source) => {
                write!(
                    f,
                    "native-v1 publication resource adoption failed: {source}"
                )
            }
            Self::SessionUnavailable => f.write_str("native-v1 publication session is unavailable"),
            Self::ConfigurationUnavailable => {
                f.write_str("native-v1 publication configuration is unavailable")
            }
            Self::Transaction(source) => write!(f, "native-v1 publication failed: {source}"),
        }
    }
}

impl std::error::Error for NativeV1SnapshotPublicationError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Preflight(source) => Some(source),
            Self::StoragePreflight(source) => Some(source),
            Self::BalloonPreflight(source) => Some(source),
            Self::MemoryHotplugPreflight(source) => Some(source),
            Self::EntropyPreflight(source) => Some(source),
            Self::SerialPreflight(source) => Some(source),
            Self::NetworkPreflight(source) => Some(source),
            Self::VsockPreflight(source) => Some(source),
            Self::Resource(source) => Some(source),
            Self::Transaction(source) => Some(source),
            Self::SessionUnavailable | Self::ConfigurationUnavailable => None,
        }
    }
}

