#[cfg(all(not(test), target_os = "macos"))]
impl ProcessSnapshotV2RootLoadCompletion {
    const fn new(
        root_completion: PreparedSnapshotRootRestoreCompletion,
        serial_output: SharedSerialOutput,
    ) -> Self {
        Self {
            root_completion,
            serial_output,
        }
    }

    fn abort(self) -> Result<(), ProcessSnapshotV2RootLoadCompletionError> {
        let Self {
            root_completion,
            serial_output,
        } = self;
        drop(serial_output);
        root_completion.abort().map_err(Into::into)
    }
}

#[cfg(all(test, target_os = "macos"))]
impl ProcessSnapshotV2RootLoadCompletion {
    fn new(
        root_completion: PreparedSnapshotRootRestoreCompletion,
        serial_output: SharedSerialOutput,
    ) -> Self {
        Self::Prepared(Box::new(ProcessSnapshotV2RootLoadCompletionResources {
            root_completion,
            serial_output,
        }))
    }

    fn abort(self) -> Result<(), ProcessSnapshotV2RootLoadCompletionError> {
        match self {
            Self::Prepared(resources) => {
                let ProcessSnapshotV2RootLoadCompletionResources {
                    root_completion,
                    serial_output,
                } = *resources;
                drop(serial_output);
                root_completion.abort().map_err(Into::into)
            }
            Self::Empty => Ok(()),
        }
    }
}

