#[allow(
    dead_code,
    reason = "native-v2 process restore is target-gated and exercised by signed integration coverage"
)]
impl NativeV2SnapshotLoadError {
    fn is_terminal(&self) -> bool {
        match self {
            Self::ProcessTerminal
            | Self::AfterResourceAdoption { .. }
            | Self::RunReady { .. }
            | Self::WorkerStart { .. }
            | Self::Resume(_) => true,
            #[cfg(target_os = "macos")]
            Self::RootResourceCleanup { .. } => true,
            Self::RootResourceCommit(_) => true,
            #[cfg(target_os = "macos")]
            Self::MultiBlockBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::MultiBlockPlatformPlan { cleanup_failed, .. } => *cleanup_failed,
            #[cfg(target_os = "macos")]
            Self::MultiBlockDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::StorageBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::StorageMmioPlatformPlan { cleanup_failed, .. }
            | Self::StoragePciPlatformPlan { cleanup_failed, .. } => *cleanup_failed,
            #[cfg(target_os = "macos")]
            Self::StorageDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::SerialBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::SerialDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::EntropyBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::EntropyDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::BalloonBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::BalloonDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::MemoryHotplugBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::MemoryHotplugDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::NetworkBundle(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::NetworkDestination(source) => source.is_terminal(),
            #[cfg(target_os = "macos")]
            Self::VsockRestoreResources(source) => {
                source.disposition() == ProcessSnapshotV2NetworkRestoreResourceDisposition::Terminal
            }
            #[cfg(target_os = "macos")]
            Self::VsockDestination(source) => source.is_terminal(),
            Self::Restore(source) => source.is_committed() || !source.cleanup_failures().is_empty(),
            Self::RootRestore(source) => source.is_terminal(),
            Self::Preflight(_)
            | Self::Resource(_)
            | Self::Cancelled
            | Self::Artifact(_)
            | Self::ArtifactState(_)
            | Self::UnexpectedFamily(_)
            | Self::State(_)
            | Self::CandidateFormat(_)
            | Self::CandidateMismatch
            | Self::MemoryHotplugPreparation(_)
            | Self::NetworkPreparation(_)
            | Self::VsockPreparation(_)
            | Self::Decode(_)
            | Self::RootPlan(_)
            | Self::RootConfiguration(_)
            | Self::RootBundle(_)
            | Self::BootMetadata(_)
            | Self::Allocation(_)
            | Self::ProcessPreparation(_)
            | Self::ControllerCommit(_) => false,
            #[cfg(target_os = "macos")]
            Self::RootBacking(_) => false,
            #[cfg(target_os = "macos")]
            Self::EntropyPlan(_) | Self::BalloonPlan(_) | Self::NetworkRestorePlan => false,
            #[cfg(target_os = "macos")]
            Self::RestoreResources(source) => {
                source.disposition() == SnapshotRestoreResourceDisposition::Terminal
            }
        }
    }
}

