#[cfg(target_os = "macos")]
fn native_v2_error_after_root_resource_abort(
    source: NativeV2SnapshotLoadError,
    completion: PreparedSnapshotRootRestoreCompletion,
) -> NativeV2SnapshotLoadError {
    match completion.abort() {
        Ok(()) => source,
        Err(cleanup) => NativeV2SnapshotLoadError::RootResourceCleanup {
            source: Box::new(source),
            cleanup: cleanup.into(),
        },
    }
}

#[derive(Debug)]
pub(crate) enum NativeV1SnapshotLoadError {
    Preflight(VmmActionError),
    ProcessTerminal,
    Resource(GrantClaimError),
    State(NativeSnapshotArtifactStateError),
    #[cfg(target_os = "macos")]
    VsockResource(VsockRestoreError),
    Artifact(SnapshotArtifactLoadError),
    Prepare(PrepareHvfSnapshotV1LoadError),
    PagerConnect(DirectSnapshotPagerConnectError),
    PagerSession(DirectSnapshotPagerConnectError),
    LazyPrepare(PrepareHvfSnapshotV1LoadError),
    AfterPagerAdoption {
        source: Box<NativeV1SnapshotLoadError>,
    },
    ProcessPreparation(BackendError),
    ControllerCommitAllocation(TryReserveError),
    Restore(HvfSnapshotV1RestoreError),
    WorkerStart {
        source: BackendError,
        cleanup: HvfSnapshotV1RestoreCleanup,
    },
}

impl NativeV1SnapshotLoadError {
    const fn disposition(&self) -> HvfSnapshotV1RestoreDisposition {
        match self {
            Self::Restore(source) => source.disposition(),
            Self::ProcessTerminal => HvfSnapshotV1RestoreDisposition::Terminal,
            Self::PagerSession(_) => HvfSnapshotV1RestoreDisposition::Terminal,
            Self::LazyPrepare(_) => HvfSnapshotV1RestoreDisposition::Terminal,
            Self::AfterPagerAdoption { .. } => HvfSnapshotV1RestoreDisposition::Terminal,
            #[cfg(target_os = "macos")]
            Self::VsockResource(source) => match source.disposition() {
                VsockRestoreDisposition::Retryable => HvfSnapshotV1RestoreDisposition::Retryable,
                VsockRestoreDisposition::Terminal => HvfSnapshotV1RestoreDisposition::Terminal,
            },
            Self::WorkerStart { cleanup, .. } if !cleanup.is_complete() => {
                HvfSnapshotV1RestoreDisposition::Terminal
            }
            Self::Preflight(_)
            | Self::Resource(_)
            | Self::State(_)
            | Self::Artifact(_)
            | Self::Prepare(_)
            | Self::PagerConnect(_)
            | Self::ProcessPreparation(_)
            | Self::ControllerCommitAllocation(_)
            | Self::WorkerStart { .. } => HvfSnapshotV1RestoreDisposition::Retryable,
        }
    }
}

impl fmt::Display for NativeV1SnapshotLoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Preflight(source) => write!(f, "native-v1 load preflight failed: {source}"),
            Self::ProcessTerminal => f.write_str("native-v1 load process is terminal"),
            Self::Resource(source) => write!(f, "native-v1 resource adoption failed: {source}"),
            Self::State(source) => write!(f, "native-v1 state adaptation failed: {source}"),
            #[cfg(target_os = "macos")]
            Self::VsockResource(source) => {
                write!(f, "native-v1 vsock resource preparation failed: {source}")
            }
            Self::Artifact(source) => write!(f, "native-v1 artifact load failed: {source}"),
            Self::Prepare(source) => write!(f, "native-v1 preparation failed: {source}"),
            Self::PagerConnect(source) => {
                write!(f, "native-v1 snapshot pager connection failed: {source}")
            }
            Self::PagerSession(source) => {
                write!(f, "native-v1 snapshot pager session failed: {source}")
            }
            Self::LazyPrepare(source) => {
                write!(f, "native-v1 lazy preparation failed: {source}")
            }
            Self::AfterPagerAdoption { source } => {
                write!(
                    f,
                    "native-v1 load failed after snapshot pager adoption: {source}"
                )
            }
            Self::ProcessPreparation(source) => {
                write!(f, "native-v1 process preparation failed: {source}")
            }
            Self::ControllerCommitAllocation(_) => {
                f.write_str("native-v1 controller commit allocation failed")
            }
            Self::Restore(source) => write!(f, "native-v1 HVF restore failed: {source}"),
            Self::WorkerStart { source, .. } => {
                write!(f, "native-v1 paused worker startup failed: {source}")
            }
        }
    }
}

impl std::error::Error for NativeV1SnapshotLoadError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Preflight(source) => Some(source),
            Self::Resource(source) => Some(source),
            Self::State(source) => Some(source),
            #[cfg(target_os = "macos")]
            Self::VsockResource(source) => Some(source),
            Self::Artifact(source) => Some(source),
            Self::Prepare(source) => Some(source),
            Self::PagerConnect(source) => Some(source),
            Self::PagerSession(source) => Some(source),
            Self::LazyPrepare(source) => Some(source),
            Self::AfterPagerAdoption { source } => Some(source.as_ref()),
            Self::ProcessPreparation(source) => Some(source),
            Self::ControllerCommitAllocation(source) => Some(source),
            Self::Restore(source) => Some(source),
            Self::WorkerStart { source, .. } => Some(source),
            Self::ProcessTerminal => None,
        }
    }
}

#[derive(Debug)]
enum NativeSnapshotLoadError {
    Preflight(VmmActionError),
    ProcessTerminal,
    Resource(GrantClaimError),
    Artifact(SnapshotArtifactLoadError),
    NativeV1(NativeV1SnapshotLoadError),
    NativeV2(NativeV2SnapshotLoadError),
}

fn native_v2_snapshot_load_is_cancelled(error: &NativeV2SnapshotLoadError) -> bool {
    match error {
        NativeV2SnapshotLoadError::Cancelled => true,
        NativeV2SnapshotLoadError::AfterResourceAdoption { source } => {
            native_v2_snapshot_load_is_cancelled(source)
        }
        _ => false,
    }
}

fn native_snapshot_load_logger_outcome(error: &NativeSnapshotLoadError) -> LoggerSnapshotOutcome {
    match error {
        NativeSnapshotLoadError::NativeV2(source)
            if native_v2_snapshot_load_is_cancelled(source) =>
        {
            LoggerSnapshotOutcome::LoadCancelled
        }
        NativeSnapshotLoadError::Preflight(_)
        | NativeSnapshotLoadError::ProcessTerminal
        | NativeSnapshotLoadError::Resource(_)
        | NativeSnapshotLoadError::NativeV1(NativeV1SnapshotLoadError::Preflight(_))
        | NativeSnapshotLoadError::NativeV1(NativeV1SnapshotLoadError::ProcessTerminal)
        | NativeSnapshotLoadError::NativeV1(NativeV1SnapshotLoadError::Resource(_))
        | NativeSnapshotLoadError::NativeV2(NativeV2SnapshotLoadError::Preflight(_))
        | NativeSnapshotLoadError::NativeV2(NativeV2SnapshotLoadError::ProcessTerminal)
        | NativeSnapshotLoadError::NativeV2(NativeV2SnapshotLoadError::Resource(_)) => {
            LoggerSnapshotOutcome::LoadRejected
        }
        NativeSnapshotLoadError::Artifact(_)
        | NativeSnapshotLoadError::NativeV1(_)
        | NativeSnapshotLoadError::NativeV2(_) => LoggerSnapshotOutcome::LoadFailed,
    }
}

impl fmt::Display for NativeSnapshotLoadError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Preflight(source) => {
                write!(formatter, "snapshot load preflight failed: {source}")
            }
            Self::ProcessTerminal => formatter.write_str("snapshot load process is terminal"),
            Self::Resource(source) => {
                write!(
                    formatter,
                    "snapshot load resource preparation failed: {source}"
                )
            }
            Self::Artifact(source) => {
                write!(formatter, "snapshot state preparation failed: {source}")
            }
            Self::NativeV1(source) => source.fmt(formatter),
            Self::NativeV2(source) => source.fmt(formatter),
        }
    }
}

impl std::error::Error for NativeSnapshotLoadError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Preflight(source) => Some(source),
            Self::Resource(source) => Some(source),
            Self::Artifact(source) => Some(source),
            Self::NativeV1(source) => Some(source),
            Self::NativeV2(source) => Some(source),
            Self::ProcessTerminal => None,
        }
    }
}

fn native_snapshot_load_action_error(error: NativeSnapshotLoadError) -> VmmActionError {
    match error {
        NativeSnapshotLoadError::Preflight(source)
        | NativeSnapshotLoadError::NativeV1(NativeV1SnapshotLoadError::Preflight(source))
        | NativeSnapshotLoadError::NativeV2(NativeV2SnapshotLoadError::Preflight(source)) => source,
        error => VmmActionError::SnapshotLoad(BackendError::Hypervisor(error.to_string())),
    }
}

struct PreparedNativeSnapshotLoad {
    state: PreparedNativeSnapshotState,
    state_id: Option<GrantId>,
    memory_id: Option<GrantId>,
}

impl PreparedNativeSnapshotLoad {
    const fn family(&self) -> NativeSnapshotArtifactFamily {
        self.state.family()
    }

    fn into_parts(
        self,
    ) -> (
        PreparedNativeSnapshotState,
        Option<GrantId>,
        Option<GrantId>,
    ) {
        (self.state, self.state_id, self.memory_id)
    }
}

impl fmt::Debug for PreparedNativeSnapshotLoad {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("PreparedNativeSnapshotLoad")
            .field("family", &self.family())
            .field("state", &"<redacted>")
            .field("authority", &"<redacted>")
            .finish()
    }
}

fn native_v1_snapshot_resume_action_error(error: VmmActionError) -> VmmActionError {
    let source = match error {
        VmmActionError::Lifecycle(source) => source,
        _ => BackendError::InvalidState("restored snapshot resume failed before state commit"),
    };
    VmmActionError::SnapshotLoad(source)
}

