pub(crate) trait VmmRequestHandler {
    fn handle_action(&mut self, action: VmmAction) -> Result<VmmData, VmmActionError>;

    fn handle_get_request(&mut self, request: GetApiRequest) -> Result<VmmData, VmmActionError>;

    fn handle_patch_request(&mut self, request: PatchApiRequest)
    -> Result<VmmData, VmmActionError>;

    fn handle_put_request(&mut self, request: PutApiRequest) -> Result<VmmData, VmmActionError>;

    fn record_api_request_parse_failure(&mut self, request: ApiRequestMetricParseFailure);

    fn record_put_actions_request(&mut self);

    fn handle_put_action_request(&mut self, action: VmmAction) -> Result<VmmData, VmmActionError>;

    fn record_deprecated_api_call(&mut self);

    #[track_caller]
    fn log_api_request(&mut self, method: LoggerHttpMethod, route: LoggerApiRoute) -> bool;

    #[track_caller]
    fn log_api_control(&mut self, outcome: LoggerApiControlOutcome) -> bool;

    #[track_caller]
    fn log_api_result(&mut self, outcome: LoggerApiResultOutcome) -> bool;

    #[track_caller]
    fn log_process_startup(&mut self, outcome: ProcessStartupOutcome) -> bool;

    fn record_pause_vm_latency_us(&mut self, duration_us: u64);

    fn record_resume_vm_latency_us(&mut self, duration_us: u64);

    fn record_full_create_snapshot_latency_us(&mut self, duration_us: u64);

    fn record_diff_create_snapshot_latency_us(&mut self, duration_us: u64);

    fn record_load_snapshot_latency_us(&mut self, duration_us: u64);

    fn metrics_session_epoch(&self) -> Option<Instant> {
        None
    }

    fn handle_initial_metrics_flush(&mut self) {}

    fn handle_periodic_metrics_flush(&mut self) {}

    fn balloon_statistics_update_interval(&self) -> Option<Duration> {
        None
    }

    fn handle_periodic_balloon_statistics_update(&mut self) -> Result<bool, VmmActionError> {
        Ok(false)
    }

    fn process_exit_wakeup_fd(&self) -> Option<RawFd> {
        None
    }

    fn drain_process_exit_wakeup(&mut self) -> Result<(), std::io::ErrorKind> {
        Ok(())
    }

    fn process_exit_status(&self) -> ProcessSessionExitStatus {
        ProcessSessionExitStatus::Running
    }

    fn record_shutdown_wakeup(&mut self) {}
}

#[derive(Debug)]
enum BootGrantState {
    PathBased,
    Prepared(BootSourceFiles),
    Consumed,
}

enum BackingGrantState<T> {
    Prepared(T),
    Consumed,
}

impl<T> fmt::Debug for BackingGrantState<T> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Prepared(_) => formatter.write_str("Prepared(<owned>)"),
            Self::Consumed => formatter.write_str("Consumed"),
        }
    }
}

enum SerialGrantState {
    PathBased,
    Prepared(SerialOutputFile),
    Consumed,
}

impl fmt::Debug for SerialGrantState {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PathBased => formatter.write_str("PathBased"),
            Self::Prepared(_) => formatter.write_str("Prepared(<owned>)"),
            Self::Consumed => formatter.write_str("Consumed"),
        }
    }
}

#[cfg(target_os = "macos")]
enum VsockGrantState {
    PathBased,
    Prepared(ClaimedSocketDirectory),
    Consumed,
    Active(AnchoredSocketGuard),
}

#[cfg(target_os = "macos")]
impl fmt::Debug for VsockGrantState {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PathBased => formatter.write_str("PathBased"),
            Self::Prepared(_) => formatter.write_str("Prepared(<owned>)"),
            Self::Consumed => formatter.write_str("Consumed"),
            Self::Active(guard) => formatter.debug_tuple("Active").field(guard).finish(),
        }
    }
}

const fn grant_access_for_read_only(read_only: bool) -> GrantAccess {
    if read_only {
        GrantAccess::ReadOnly
    } else {
        GrantAccess::ReadWrite
    }
}

/// Process origin used to distinguish direct operator policy from contained authority.
#[derive(Clone, Copy, PartialEq, Eq, Default)]
pub(crate) enum ProcessVmnetAuthority {
    /// Direct execution retains the existing process vmnet behavior.
    #[default]
    Direct,
    /// Contained execution is bounded by authenticated launcher policy.
    Contained {
        session_id: SessionId,
        authority: VmnetAuthority,
    },
}

impl ProcessVmnetAuthority {
    pub(crate) fn contained(session_id: SessionId, authority: VmnetAuthority) -> Option<Self> {
        (!session_id.is_pre_session()).then_some(Self::Contained {
            session_id,
            authority,
        })
    }

    const fn contained_authority(self) -> Option<VmnetAuthority> {
        match self {
            Self::Direct => None,
            Self::Contained { authority, .. } => Some(authority),
        }
    }
}

impl fmt::Debug for ProcessVmnetAuthority {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Direct => formatter.write_str("Direct"),
            Self::Contained { .. } => formatter.write_str("Contained(<redacted>)"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LiveDeviceLifecycleOperation {
    Attach,
    Update,
    Detach,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LiveDeviceLifecycleAction {
    kind: LoggerDeviceKind,
    operation: LiveDeviceLifecycleOperation,
}

impl LiveDeviceLifecycleAction {
    const fn succeeded(self) -> LoggerLifecycleOutcome {
        match self.operation {
            LiveDeviceLifecycleOperation::Attach => {
                LoggerLifecycleOutcome::DeviceAttachSucceeded(self.kind)
            }
            LiveDeviceLifecycleOperation::Update => {
                LoggerLifecycleOutcome::DeviceUpdateSucceeded(self.kind)
            }
            LiveDeviceLifecycleOperation::Detach => {
                LoggerLifecycleOutcome::DeviceDetachSucceeded(self.kind)
            }
        }
    }

    const fn rejected(self) -> LoggerLifecycleOutcome {
        match self.operation {
            LiveDeviceLifecycleOperation::Attach => {
                LoggerLifecycleOutcome::DeviceAttachRejected(self.kind)
            }
            LiveDeviceLifecycleOperation::Update => {
                LoggerLifecycleOutcome::DeviceUpdateRejected(self.kind)
            }
            LiveDeviceLifecycleOperation::Detach => {
                LoggerLifecycleOutcome::DeviceDetachRejected(self.kind)
            }
        }
    }

    const fn failed(self) -> LoggerLifecycleOutcome {
        match self.operation {
            LiveDeviceLifecycleOperation::Attach => {
                LoggerLifecycleOutcome::DeviceAttachFailed(self.kind)
            }
            LiveDeviceLifecycleOperation::Update => {
                LoggerLifecycleOutcome::DeviceUpdateFailed(self.kind)
            }
            LiveDeviceLifecycleOperation::Detach => {
                LoggerLifecycleOutcome::DeviceDetachFailed(self.kind)
            }
        }
    }
}

