#[derive(Debug, Clone, Default)]
pub(crate) struct HvfInstanceStartExecutor {
    boot_timer_enabled: bool,
    pci_enabled: bool,
    process_serial_stdio: bool,
    serial_output: SharedSerialOutputBuffer,
    active_serial_output: Option<SharedSerialOutput>,
}

impl HvfInstanceStartExecutor {
    #[cfg(test)]
    fn boot_session_config(&self) -> HvfArm64BootSessionConfig {
        default_hvf_boot_session_config(SharedSerialOutput::from(self.serial_output.clone()))
    }

    #[cfg(target_os = "macos")]
    fn preflight_snapshot_v2_root_process(&self, pci_enabled: bool) -> Result<(), VmmActionError> {
        if self.boot_timer_enabled || self.pci_enabled != pci_enabled {
            Err(VmmActionError::SnapshotUnsupported)
        } else {
            Ok(())
        }
    }

    fn validate_snapshot_v2_artifact_profile(
        &self,
        state: &PreparedNativeSnapshotState,
        profile: NativeV2SnapshotArtifactProfile,
    ) -> Result<(), NativeV2SnapshotLoadError> {
        let bytes = state
            .state()
            .v2_bytes()
            .ok_or(NativeV2SnapshotLoadError::UnexpectedFamily(
                NativeSnapshotArtifactFamily::V1,
            ))?;
        let version = match profile {
            NativeV2SnapshotArtifactProfile::LegacyPlatformV2_3 => {
                NATIVE_V2_LEGACY_PLATFORM_VERSION
            }
            NativeV2SnapshotArtifactProfile::DeviceGraphV2_4 => {
                NATIVE_V2_DEVICE_GRAPH_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::MultiBlockDeviceGraphV2_5 => {
                NATIVE_V2_MULTI_BLOCK_DEVICE_GRAPH_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::StorageDeviceGraphV2_6 => {
                NATIVE_V2_STORAGE_DEVICE_GRAPH_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::SerialStateV2_7 => {
                NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::EntropyStateV2_8 => {
                NATIVE_V2_ENTROPY_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::BalloonStateV2_9 => {
                NATIVE_V2_BALLOON_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::MemoryHotplugStateV2_10 => {
                NATIVE_V2_MEMORY_HOTPLUG_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::NetworkStateV2_11 => {
                NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::VsockStateV2_12 => {
                NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION
            }
            NativeV2SnapshotArtifactProfile::DiffStateV2_13 => {
                NATIVE_V2_DIFF_STATE_COMPATIBILITY_VERSION
            }
        };
        let structural = decode_snapshot_v2_state_with_compatibility_version(bytes, version)
            .map_err(NativeV2SnapshotLoadError::CandidateFormat)?;
        match profile {
            NativeV2SnapshotArtifactProfile::LegacyPlatformV2_3 => {
                decode_hvf_snapshot_v2_platform_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::DeviceGraphV2_4 => {
                decode_hvf_snapshot_v2_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::MultiBlockDeviceGraphV2_5 => {
                decode_hvf_snapshot_v2_multi_block_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::StorageDeviceGraphV2_6 => {
                decode_hvf_snapshot_v2_storage_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::SerialStateV2_7 => {
                decode_hvf_snapshot_v2_serial_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::EntropyStateV2_8 => {
                decode_hvf_snapshot_v2_entropy_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::BalloonStateV2_9 => {
                decode_hvf_snapshot_v2_balloon_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::MemoryHotplugStateV2_10 => {
                decode_hvf_snapshot_v2_memory_hotplug_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::NetworkStateV2_11 => {
                decode_hvf_snapshot_v2_network_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::VsockStateV2_12 => {
                decode_hvf_snapshot_v2_vsock_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
            NativeV2SnapshotArtifactProfile::DiffStateV2_13 => {
                decode_hvf_snapshot_v2_diff_state(&structural)
                    .map_err(NativeV2SnapshotLoadError::Decode)?;
            }
        }
        Ok(())
    }

    fn serial_output_for_controller(
        &self,
        controller: &VmmController,
        provided_output: Option<SerialOutputFile>,
    ) -> Result<SharedSerialOutput, SerialConfigError> {
        match (
            controller.serial_config().serial_out_path(),
            provided_output,
        ) {
            (Some(_), Some(output)) => Ok(SharedSerialOutput::with_rate_limiter(
                output,
                controller.serial_config().rate_limiter(),
            )),
            (Some(path), None) => Ok(SharedSerialOutput::with_rate_limiter(
                SerialOutputFile::open(path)?,
                controller.serial_config().rate_limiter(),
            )),
            (None, None) => Ok(SharedSerialOutput::with_rate_limiter(
                self.serial_output.clone(),
                controller.serial_config().rate_limiter(),
            )),
            (None, Some(_)) => Err(SerialConfigError::ProvidedOutputWithoutPath),
        }
    }

    #[cfg(test)]
    fn boot_session_config_for_controller(
        &self,
        controller: &VmmController,
    ) -> Result<HvfArm64BootSessionConfig, SerialConfigError> {
        let serial_output = self.serial_output_for_controller(controller, None)?;
        Ok(self.boot_session_config_for_controller_with_serial_output(controller, serial_output))
    }

    fn boot_session_config_for_controller_with_serial_output(
        &self,
        controller: &VmmController,
        serial_output: SharedSerialOutput,
    ) -> HvfArm64BootSessionConfig {
        let mut config = default_hvf_boot_session_config(serial_output);
        if controller.entropy_config().is_some() {
            config = config.with_entropy_device(HvfArm64BootEntropyDeviceConfig::new(
                EntropyMmioLayout::new(DEFAULT_ENTROPY_MMIO_BASE, DEFAULT_ENTROPY_MMIO_REGION_ID),
            ));
        }
        if controller.balloon_config().is_some() {
            config = config.with_balloon_device(HvfArm64BootBalloonDeviceConfig::new(
                BalloonMmioLayout::new(DEFAULT_BALLOON_MMIO_BASE, DEFAULT_BALLOON_MMIO_REGION_ID),
            ));
        }
        if controller.memory_hotplug_config().is_some() {
            config = config.with_memory_hotplug_device(HvfArm64BootMemoryHotplugDeviceConfig::new(
                VirtioMemMmioLayout::new(
                    DEFAULT_MEMORY_HOTPLUG_MMIO_BASE,
                    DEFAULT_MEMORY_HOTPLUG_MMIO_REGION_ID,
                ),
            ));
        }
        if self.boot_timer_enabled {
            config = config.with_boot_timer_device(HvfArm64BootTimerDeviceConfig::new(
                BootTimerMmioLayout::new(
                    DEFAULT_BOOT_TIMER_MMIO_BASE,
                    DEFAULT_BOOT_TIMER_MMIO_REGION_ID,
                ),
            ));
        }
        if self.pci_enabled {
            config = config.with_pci_enabled();
        }

        config
    }
}

