enum HvfSnapshotV2SerialConstructionError {
    TransportPolicy {
        storage_cleanup: Option<SnapshotV2StorageCleanupError>,
    },
    StorageAdoption(SnapshotV2SerialStorageAdoptionError),
    StorageMmioPlan {
        source: PrepareHvfSnapshotV2StorageMmioPlatformPlanError,
        storage_cleanup: Option<SnapshotV2StorageCleanupError>,
    },
    StoragePciPlan {
        source: PrepareHvfSnapshotV2StoragePciPlatformPlanError,
        storage_cleanup: Option<SnapshotV2StorageCleanupError>,
    },
    EntropyPciPlan {
        source: PrepareHvfSnapshotV2EntropyPciPlatformPlanError,
        storage_cleanup: Option<SnapshotV2StorageCleanupError>,
    },
    BalloonPlan(PrepareHvfSnapshotV2BalloonPlatformPlanError),
    MemoryHotplugPlan(PrepareHvfSnapshotV2MemoryHotplugPlatformPlanError),
    NetworkPlan(PrepareHvfSnapshotV2NetworkPlatformPlanError),
    NetworkMmio(ProcessSnapshotV2NetworkMmioRestoreError),
    NetworkPci(ProcessSnapshotV2NetworkPciRestoreError),
    InvalidOwners {
        storage_cleanup: Option<SnapshotV2StorageCleanupError>,
    },
    Process(HvfSnapshotV2ProcessConstructionError<HvfSnapshotV2SerialOwnerRestoreError>),
}

#[cfg(target_os = "macos")]
impl HvfSnapshotV2SerialConstructionError {
    fn is_terminal(&self) -> bool {
        match self {
            Self::StorageAdoption(source) => source.is_terminal(),
            Self::StorageMmioPlan {
                source: PrepareHvfSnapshotV2StorageMmioPlatformPlanError::Allocation,
                storage_cleanup: None,
            }
            | Self::StoragePciPlan {
                source: PrepareHvfSnapshotV2StoragePciPlatformPlanError::Allocation,
                storage_cleanup: None,
            }
            | Self::EntropyPciPlan {
                source: PrepareHvfSnapshotV2EntropyPciPlatformPlanError::Allocation,
                storage_cleanup: None,
            }
            | Self::BalloonPlan(PrepareHvfSnapshotV2BalloonPlatformPlanError::Allocation) => false,
            Self::MemoryHotplugPlan(
                PrepareHvfSnapshotV2MemoryHotplugPlatformPlanError::Allocation,
            ) => false,
            Self::NetworkPlan(_) => false,
            Self::NetworkMmio(source) => source.is_terminal(),
            Self::NetworkPci(source) => source.is_terminal(),
            Self::Process(source) => source.is_terminal(),
            Self::TransportPolicy { .. }
            | Self::StorageMmioPlan { .. }
            | Self::StoragePciPlan { .. }
            | Self::EntropyPciPlan { .. }
            | Self::BalloonPlan(_)
            | Self::MemoryHotplugPlan(_)
            | Self::InvalidOwners { .. } => true,
        }
    }
}

#[cfg(target_os = "macos")]
impl fmt::Debug for HvfSnapshotV2SerialConstructionError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("HvfSnapshotV2SerialConstructionError")
            .field(
                "stage",
                &match self {
                    Self::TransportPolicy { .. } => "transport-policy",
                    Self::StorageAdoption(_) => "storage-adoption",
                    Self::StorageMmioPlan { .. } => "storage-mmio-plan",
                    Self::StoragePciPlan { .. } => "storage-pci-plan",
                    Self::EntropyPciPlan { .. } => "entropy-pci-plan",
                    Self::BalloonPlan(_) => "balloon-plan",
                    Self::MemoryHotplugPlan(_) => "memory-hotplug-plan",
                    Self::NetworkPlan(_) => "network-plan",
                    Self::NetworkMmio(_) => "network-mmio",
                    Self::NetworkPci(_) => "network-pci",
                    Self::InvalidOwners { .. } => "owners",
                    Self::Process(_) => "process",
                },
            )
            .field("terminal", &self.is_terminal())
            .field("state", &"<redacted>")
            .finish()
    }
}

#[cfg(target_os = "macos")]
impl fmt::Display for HvfSnapshotV2SerialConstructionError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "native-v2 serial-bearing destination construction failed ({})",
            if self.is_terminal() {
                "terminal"
            } else {
                "retryable"
            }
        )
    }
}

#[cfg(target_os = "macos")]
impl std::error::Error for HvfSnapshotV2SerialConstructionError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::TransportPolicy { storage_cleanup } | Self::InvalidOwners { storage_cleanup } => {
                storage_cleanup
                    .as_ref()
                    .map(|source| source as &(dyn std::error::Error + 'static))
            }
            Self::StorageAdoption(source) => Some(source),
            Self::StorageMmioPlan { source, .. } => Some(source),
            Self::StoragePciPlan { source, .. } => Some(source),
            Self::EntropyPciPlan { source, .. } => Some(source),
            Self::BalloonPlan(source) => Some(source),
            Self::MemoryHotplugPlan(source) => Some(source),
            Self::NetworkPlan(source) => Some(source),
            Self::NetworkMmio(source) => Some(source),
            Self::NetworkPci(source) => Some(source),
            Self::Process(source) => Some(source),
        }
    }
}

#[cfg(target_os = "macos")]
#[derive(Debug)]
struct HvfSnapshotV2SerialDestinationCleanupError {
    session: Option<BackendError>,
    vsock: bool,
    restoration: Option<SerialStdioRestorationError>,
}

#[cfg(target_os = "macos")]
impl fmt::Display for HvfSnapshotV2SerialDestinationCleanupError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("native-v2 serial-bearing destination cleanup failed")?;
        if self.vsock {
            formatter.write_str("; vsock publication cleanup is uncertain")?;
        }
        Ok(())
    }
}

#[cfg(target_os = "macos")]
impl std::error::Error for HvfSnapshotV2SerialDestinationCleanupError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.session
            .as_ref()
            .map(|source| source as &(dyn std::error::Error + 'static))
            .or_else(|| {
                self.restoration
                    .as_ref()
                    .map(|source| source as &(dyn std::error::Error + 'static))
            })
    }
}

#[cfg(target_os = "macos")]
enum HvfSnapshotV2SerialControllerProfile {
    RetainedV2_7,
    RetainedV2_8 {
        entropy_config: Option<EntropyConfig>,
    },
    CurrentV2_9 {
        entropy_config: Option<EntropyConfig>,
        balloon_config: Option<BalloonConfig>,
    },
    CurrentV2_10 {
        entropy_config: Option<EntropyConfig>,
        balloon_config: Option<BalloonConfig>,
        memory_hotplug: Option<SnapshotV2MemoryHotplugControllerProjection>,
    },
    RetainedV2_11 {
        entropy_config: Option<EntropyConfig>,
        balloon_config: Option<BalloonConfig>,
        memory_hotplug: Option<SnapshotV2MemoryHotplugControllerProjection>,
        network_configs: NetworkInterfaceConfigs,
        mmds_state: Option<MmdsStateHandle>,
    },
    CurrentV2_12 {
        entropy_config: Option<EntropyConfig>,
        balloon_config: Option<BalloonConfig>,
        memory_hotplug: Option<SnapshotV2MemoryHotplugControllerProjection>,
        network_configs: NetworkInterfaceConfigs,
        mmds_state: Option<MmdsStateHandle>,
        vsock_config: Option<VsockConfig>,
    },
}

#[cfg(target_os = "macos")]
