impl SnapshotCaptureCancellation {
    fn begin_operation(&self) -> bool {
        if self.state.shutdown_requested.load(Ordering::Acquire) {
            self.cancel_active_operation();
            return false;
        }

        match self.state.operation.compare_exchange(
            SNAPSHOT_OPERATION_COMMIT_SEALED,
            SNAPSHOT_OPERATION_ACTIVE,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) | Err(SNAPSHOT_OPERATION_ACTIVE) => {}
            Err(SNAPSHOT_OPERATION_CANCELLED) => return false,
            Err(_) => return false,
        }

        if self.state.shutdown_requested.load(Ordering::Acquire) {
            self.cancel_active_operation();
        }
        !self.is_cancelled()
    }

    pub(crate) fn cancel(&self) {
        self.state.shutdown_requested.store(true, Ordering::Release);
        self.cancel_active_operation();
    }

    fn cancel_active_operation(&self) {
        let _ = self.state.operation.compare_exchange(
            SNAPSHOT_OPERATION_ACTIVE,
            SNAPSHOT_OPERATION_CANCELLED,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
    }

    pub(crate) fn is_cancelled(&self) -> bool {
        self.state.operation.load(Ordering::Acquire) == SNAPSHOT_OPERATION_CANCELLED
    }

    pub(crate) fn try_seal_commit(&self) -> bool {
        self.state
            .operation
            .compare_exchange(
                SNAPSHOT_OPERATION_ACTIVE,
                SNAPSHOT_OPERATION_COMMIT_SEALED,
                Ordering::AcqRel,
                Ordering::Acquire,
            )
            .is_ok()
    }

    fn is_commit_sealed(&self) -> bool {
        self.state.operation.load(Ordering::Acquire) == SNAPSHOT_OPERATION_COMMIT_SEALED
    }

    fn same_operation(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.state, &other.state)
    }
}

impl fmt::Debug for SnapshotCaptureCancellation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("SnapshotCaptureCancellation")
            .field("cancelled", &self.is_cancelled())
            .field("commit_sealed", &self.is_commit_sealed())
            .field(
                "shutdown_requested",
                &self.state.shutdown_requested.load(Ordering::Acquire),
            )
            .finish()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum NativeV1SnapshotCaptureStage {
    State(HvfArm64BootSnapshotV1CaptureStage),
    Memory(SnapshotMemoryIoStage),
    Bundle,
    CommitSeal,
}

impl fmt::Display for NativeV1SnapshotCaptureStage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::State(stage) => write!(f, "state/{stage}"),
            Self::Memory(stage) => write!(f, "memory/{stage}"),
            Self::Bundle => f.write_str("bundle"),
            Self::CommitSeal => f.write_str("commit seal"),
        }
    }
}

#[derive(Debug)]
pub(crate) enum NativeV1SnapshotCaptureError {
    Supervisor {
        source: BackendError,
    },
    Auxiliary {
        source: BackendError,
    },
    State {
        source: HvfArm64BootSnapshotV1StateCaptureError,
    },
    MemoryAccess {
        source: BackendError,
    },
    MemoryWrite {
        source: SnapshotMemoryWriteError,
    },
    Cancelled {
        stage: NativeV1SnapshotCaptureStage,
    },
    Bundle {
        source: HvfSnapshotV1BundleError,
    },
}

impl fmt::Display for NativeV1SnapshotCaptureError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Supervisor { source } => {
                write!(f, "native-v1 supervisor capture failed: {source}")
            }
            Self::Auxiliary { source } => {
                write!(f, "native-v1 auxiliary quiescence failed: {source}")
            }
            Self::State { source } => write!(f, "native-v1 state capture failed: {source}"),
            Self::MemoryAccess { source } => {
                write!(f, "native-v1 guest memory is unavailable: {source}")
            }
            Self::MemoryWrite { source } => {
                write!(f, "native-v1 guest-memory capture failed: {source}")
            }
            Self::Cancelled { stage } => {
                write!(f, "native-v1 capture was cancelled before {stage}")
            }
            Self::Bundle { source } => {
                write!(f, "native-v1 composite bundle validation failed: {source}")
            }
        }
    }
}

impl std::error::Error for NativeV1SnapshotCaptureError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Supervisor { source }
            | Self::Auxiliary { source }
            | Self::MemoryAccess { source } => Some(source),
            Self::State { source } => Some(source),
            Self::MemoryWrite { source } => Some(source),
            Self::Bundle { source } => Some(source),
            Self::Cancelled { .. } => None,
        }
    }
}

