    fn native_v2_vsock_pre_access_product_candidate(
        network: Option<SnapshotV2NetworkState>,
        vsock: Option<SnapshotV2VsockState>,
        device_graph: Option<SnapshotV2StorageDeviceGraph>,
        serial_config: SerialConfig,
    ) -> (NativeV2VsockSnapshotCandidateState, GuestMemory) {
        let range = GuestMemoryRange::new(GuestAddress::new(0), 0x0040_0000)
            .expect("exact-2.12 pre-access memory range should validate");
        let layout = GuestMemoryLayout::new(vec![range])
            .expect("exact-2.12 pre-access memory layout should validate");
        let mut memory =
            GuestMemory::allocate(&layout).expect("exact-2.12 pre-access memory should allocate");
        if let Some(vsock) = vsock.as_ref()
            && let Some(active) = vsock.active_queues()
        {
            for (queue, cursor) in
                vsock
                    .virtio()
                    .queues()
                    .iter()
                    .zip([active.rx(), active.tx(), active.event()])
            {
                memory
                    .write_slice(
                        &cursor.next_available().to_le_bytes(),
                        queue
                            .driver_ring()
                            .checked_add(2)
                            .expect("available index should not overflow"),
                    )
                    .expect("available queue index should write");
                memory
                    .write_slice(
                        &cursor.next_used().to_le_bytes(),
                        queue
                            .device_ring()
                            .checked_add(2)
                            .expect("used index should not overflow"),
                    )
                    .expect("used queue index should write");
            }
        }

        let mut image = Cursor::new(Vec::new());
        let binding = write_snapshot_v2_memory_image_with_compatibility_version_and_cancel(
            &memory,
            &mut image,
            NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION,
            |_| false,
        )
        .expect("exact-2.12 pre-access memory should encode")
        .encode()
        .expect("exact-2.12 pre-access binding should encode");
        let device_graph = device_graph.as_ref().map(|graph| {
            graph
                .encode(NATIVE_V2_STORAGE_DEVICE_GRAPH_COMPATIBILITY_VERSION)
                .expect("exact-2.12 pre-access storage graph should encode")
        });
        let serial_device = SerialMmioDevice::discarding()
            .capture_state()
            .expect("exact-2.12 pre-access serial device should capture");
        let serial = SnapshotV2SerialState::try_from_capture_ready(CaptureReadySerialState::new(
            serial_config,
            serial_device,
        ))
        .expect("exact-2.12 pre-access serial should validate")
        .encode(NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION)
        .expect("exact-2.12 pre-access serial should encode");
        let network = network.as_ref().map(|state| {
            state
                .encode(NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION)
                .expect("exact-2.12 pre-access network should encode")
        });
        let vsock = vsock.as_ref().map(|state| {
            state
                .encode(NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION)
                .expect("exact-2.12 pre-access vsock should encode")
        });
        let mut components = vec![SnapshotV2Component::new(
            NATIVE_V2_MEMORY_COMPONENT_KEY,
            SnapshotV2ComponentDisposition::Semantic,
            &binding,
        )];
        if let Some(device_graph) = device_graph.as_deref() {
            components.push(SnapshotV2Component::new(
                NATIVE_V2_DEVICE_GRAPH_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                device_graph,
            ));
        }
        components.push(SnapshotV2Component::new(
            NATIVE_V2_SERIAL_COMPONENT_KEY,
            SnapshotV2ComponentDisposition::Semantic,
            &serial,
        ));
        if let Some(network) = network.as_deref() {
            components.push(SnapshotV2Component::new(
                NATIVE_V2_NETWORK_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                network,
            ));
        }
        if let Some(vsock) = vsock.as_deref() {
            components.push(SnapshotV2Component::new(
                NATIVE_V2_VSOCK_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                vsock,
            ));
        }
        let encoded = encode_snapshot_v2_state_with_compatibility_version(
            NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION,
            &[],
            &components,
        )
        .expect("exact-2.12 pre-access candidate should encode");
        let candidate = NativeV2VsockSnapshotCandidateState::from_vsock_state_v2_12(encoded)
            .expect("exact-2.12 pre-access candidate should close");
        (candidate, memory)
    }

    fn native_v2_vsock_pre_access_candidate(
        network: Option<SnapshotV2NetworkState>,
        vsock: Option<SnapshotV2VsockState>,
    ) -> (NativeV2VsockSnapshotCandidateState, GuestMemory) {
        native_v2_vsock_pre_access_product_candidate(network, vsock, None, SerialConfig::default())
    }

    #[cfg(target_os = "macos")]
    fn prepared_native_v2_vsock_resource_plan(
        destination: &Path,
        with_network: bool,
    ) -> (
        super::PreparedProcessSnapshotV2VsockResourcePlan,
        Option<GuestMacAddress>,
    ) {
        prepared_native_v2_vsock_resource_plan_with_serial(
            destination,
            with_network,
            SerialConfig::default(),
        )
    }

    #[cfg(target_os = "macos")]
    fn prepared_native_v2_vsock_resource_plan_with_serial(
        destination: &Path,
        with_network: bool,
        serial_config: SerialConfig,
    ) -> (
        super::PreparedProcessSnapshotV2VsockResourcePlan,
        Option<GuestMacAddress>,
    ) {
        let network =
            with_network.then(|| fake_native_v2_network_state(SnapshotV2DeviceTransportKind::Mmio));
        let expected_mac = network.as_ref().and_then(|state| {
            state
                .interfaces()
                .first()
                .and_then(|interface| interface.profile().guest_mac())
        });
        let network_overrides = network
            .as_ref()
            .map(|state| {
                state
                    .interfaces()
                    .iter()
                    .map(|interface| {
                        SnapshotNetworkOverride::new(interface.iface_id(), "vmnet:shared")
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let vsock = fake_native_v2_vsock_state(SnapshotV2DeviceTransportKind::Mmio);
        let (candidate, memory) =
            native_v2_vsock_pre_access_product_candidate(network, Some(vsock), None, serial_config);
        let vsock_override = SnapshotVsockOverride::new(destination);
        let candidate = prepare_process_snapshot_v2_vsock_candidate(
            candidate,
            &memory,
            SnapshotV2DeviceTransportKind::Mmio,
            &network_overrides,
            Some(&vsock_override),
        )
        .expect("canonical exact-2.12 candidate should prepare");
        let plan = super::prepare_process_snapshot_v2_vsock_resource_plan(
            candidate,
            ProcessVmnetAuthority::Direct,
        )
        .expect("canonical exact-2.12 resource plan should prepare");
        (plan, expected_mac)
    }

    #[derive(Default)]
    struct NativeV2VsockPreAccessHostSpies {
        filesystem: Cell<u32>,
        grant: Cell<u32>,
        broker: Cell<u32>,
        listener: Cell<u32>,
        connector: Cell<u32>,
        vm: Cell<u32>,
        vcpu: Cell<u32>,
        hvf: Cell<u32>,
    }

    impl NativeV2VsockPreAccessHostSpies {
        fn record_post_preflight_access(&self) {
            for counter in [
                &self.filesystem,
                &self.grant,
                &self.broker,
                &self.listener,
                &self.connector,
                &self.vm,
                &self.vcpu,
                &self.hvf,
            ] {
                counter.set(counter.get() + 1);
            }
        }

        fn counts(&self) -> [u32; 8] {
            [
                self.filesystem.get(),
                self.grant.get(),
                self.broker.get(),
                self.listener.get(),
                self.connector.get(),
                self.vm.get(),
                self.vcpu.get(),
                self.hvf.get(),
            ]
        }
    }

    fn rejected_native_v2_vsock_pre_access(
        result: Result<
            PreparedNativeV2VsockSnapshotCandidateState,
            NativeV2VsockSnapshotPreparationError,
        >,
    ) -> NativeV2VsockSnapshotPreparationError {
        let spies = NativeV2VsockPreAccessHostSpies::default();
        let result = result.inspect(|_| {
            spies.record_post_preflight_access();
        });
        let error = result.expect_err("malformed exact-2.12 state must fail pre-access");
        assert_eq!(spies.counts(), [0; 8]);
        error
    }

    #[cfg(target_os = "macos")]
    fn copied_inactive_mmio_network_interface(
        source: &SnapshotV2NetworkInterfaceState,
        index: usize,
        backend: SnapshotV2NetworkBackendClass,
    ) -> SnapshotV2NetworkInterfaceState {
        let SnapshotV2DeviceTransport::Mmio(mmio) = source.transport() else {
            panic!("partial-MMDS fixture source must use MMIO");
        };
        let offset = u64::try_from(index).expect("fixture interface index should fit")
            * VIRTIO_MMIO_DEVICE_WINDOW_SIZE;
        let region = MmioRegion::new(
            MmioRegionId::new(
                mmio.region()
                    .id()
                    .raw_value()
                    .checked_add(u64::try_from(index).unwrap())
                    .expect("fixture region ID should fit"),
            ),
            GuestAddress::new(
                mmio.region()
                    .range()
                    .start()
                    .raw_value()
                    .checked_add(offset)
                    .expect("fixture MMIO placement should fit"),
            ),
            VIRTIO_MMIO_DEVICE_WINDOW_SIZE,
        )
        .expect("fixture MMIO region should validate");
        let transport = SnapshotV2DeviceTransport::Mmio(SnapshotV2MmioDeviceState::from_parts(
            mmio.device_feature_select(),
            mmio.driver_feature_select(),
            mmio.queue_select(),
            region,
            GuestInterruptLine::new(
                mmio.interrupt_line()
                    .raw_value()
                    .checked_add(u32::try_from(index).unwrap())
                    .expect("fixture interrupt should fit"),
            )
            .expect("fixture interrupt should validate"),
        ));
        let guest_mac = GuestMacAddress::from_bytes([
            0x02,
            0,
            0,
            0,
            0x40,
            u8::try_from(index).expect("fixture MAC index should fit"),
        ]);
        let profile = NetworkDeviceProfile::new(Some(guest_mac), source.requested_mtu());

        SnapshotV2NetworkInterfaceState::try_from_parts(SnapshotV2NetworkInterfaceStateParts {
            iface_id: format!("eth{index}"),
            captured_selector: format!("captured{index}"),
            requested_guest_mac: Some(guest_mac),
            requested_mtu: source.requested_mtu(),
            profile,
            backend,
            local: source.local().clone(),
            virtio: source.virtio().clone(),
            rx_limiter: source.rx_limiter(),
            tx_limiter: source.tx_limiter(),
            transport,
        })
        .expect("copied network interface should validate")
    }

