    #[cfg(target_os = "macos")]
    fn prepared_native_v2_network_restore_candidate(
        state: SnapshotV2NetworkState,
        selectors: &[&str],
    ) -> PreparedNativeV2NetworkSnapshotCandidateState {
        assert_eq!(selectors.len(), state.interfaces().len());
        let range = GuestMemoryRange::new(GuestAddress::new(0x8000_0000), 16 * 1024)
            .expect("exact-2.11 fixture memory range should validate");
        let layout = GuestMemoryLayout::new(vec![range])
            .expect("exact-2.11 fixture memory layout should validate");
        let memory =
            GuestMemory::allocate(&layout).expect("exact-2.11 fixture memory should allocate");
        let mut image = Cursor::new(Vec::new());
        let binding = write_snapshot_v2_memory_image_with_compatibility_version_and_cancel(
            &memory,
            &mut image,
            NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION,
            |_| false,
        )
        .expect("exact-2.11 fixture memory should encode")
        .encode()
        .expect("exact-2.11 fixture binding should encode");
        let serial_device = SerialMmioDevice::discarding()
            .capture_state()
            .expect("exact-2.11 fixture serial device should capture");
        let serial = SnapshotV2SerialState::try_from_capture_ready(CaptureReadySerialState::new(
            SerialConfig::default(),
            serial_device,
        ))
        .expect("exact-2.11 fixture serial state should validate")
        .encode(NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION)
        .expect("exact-2.11 fixture serial state should encode");
        let network = state
            .encode(NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION)
            .expect("exact-2.11 fixture network state should encode");
        let components = [
            SnapshotV2Component::new(
                NATIVE_V2_MEMORY_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                &binding,
            ),
            SnapshotV2Component::new(
                NATIVE_V2_SERIAL_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                &serial,
            ),
            SnapshotV2Component::new(
                NATIVE_V2_NETWORK_COMPONENT_KEY,
                SnapshotV2ComponentDisposition::Semantic,
                &network,
            ),
        ];
        let encoded = encode_snapshot_v2_state_with_compatibility_version(
            NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION,
            &[],
            &components,
        )
        .expect("exact-2.11 fixture candidate should encode");
        let candidate = NativeV2NetworkSnapshotCandidateState::from_network_state_v2_11(encoded)
            .expect("exact-2.11 fixture candidate should validate");
        let overrides = state
            .interfaces()
            .iter()
            .zip(selectors)
            .map(|(interface, selector)| {
                SnapshotNetworkOverride::new(interface.iface_id(), *selector)
            })
            .collect::<Vec<_>>();

        match candidate
            .prepare(&overrides)
            .expect("exact-2.11 fixture candidate should prepare")
        {
            NativeV2NetworkSnapshotPreparation::Prepared(candidate) => candidate,
            NativeV2NetworkSnapshotPreparation::Compatible(_) => {
                panic!("network-bearing fixture must not remain compatible")
            }
        }
    }

    #[cfg(target_os = "macos")]
    fn fake_native_v2_network_capture_profile(
        transport: SnapshotV2DeviceTransportKind,
    ) -> (
        SnapshotV2NetworkState,
        Vec<NetworkInterfaceConfig>,
        Option<MmdsConfig>,
        MmdsStateHandle,
    ) {
        let state = fake_native_v2_network_state(transport);
        let configs = state
            .interfaces()
            .iter()
            .map(|interface| {
                let mut input = NetworkInterfaceConfigInput::new(
                    interface.iface_id(),
                    interface.iface_id(),
                    interface.captured_selector(),
                );
                if let Some(mac) = interface.requested_guest_mac() {
                    input = input.with_guest_mac(mac.to_string());
                }
                if let Some(mtu) = interface.requested_mtu() {
                    input = input.with_mtu(mtu);
                }
                input
                    .validate()
                    .expect("fake native-v2 network config should validate")
            })
            .collect::<Vec<_>>();
        let mmds_input = state.mmds().map(|mmds| {
            let selected = mmds
                .interfaces()
                .iter()
                .map(|selected| {
                    state.interfaces()[usize::from(selected.interface_index())]
                        .iface_id()
                        .to_owned()
                })
                .collect::<Vec<_>>();
            let mut input = MmdsConfigInput::new(selected)
                .with_version(mmds.version())
                .with_imds_compat(mmds.imds_compat());
            if let Some(ipv4_address) = mmds.ipv4_address() {
                input = input.with_ipv4_address(ipv4_address);
            }
            input
        });
        let mmds_config = mmds_input.clone().map(|input| {
            input
                .validate(&configs)
                .expect("fake native-v2 MMDS config should validate")
        });
        let mmds_state = MmdsStateHandle::default();
        if let Some(input) = mmds_input {
            mmds_state
                .with_mut(|state| state.put_config(input, &configs))
                .expect("fake native-v2 MMDS state should lock")
                .expect("fake native-v2 MMDS state should configure");
        }
        (state, configs, mmds_config, mmds_state)
    }

    fn fake_native_v2_memory_hotplug_state_for_request(
        transport: SnapshotV2DeviceTransportKind,
        config: MemoryHotplugConfig,
        requested_size_mib: u64,
    ) -> SnapshotV2MemoryHotplugState {
        const MIB: u64 = 1024 * 1024;

        let fixture = fake_native_v2_memory_hotplug_state(transport);
        assert_eq!(
            fixture.config(),
            config,
            "fake publication fixture must match the requested virtio-mem configuration"
        );
        let requested_size = requested_size_mib
            .checked_mul(MIB)
            .expect("fake requested virtio-mem size should fit bytes");
        SnapshotV2MemoryHotplugState::try_new(
            config,
            fixture.config_space().with_requested_size(requested_size),
            fixture.active_queue(),
            fixture.plugged_bitmap().to_vec(),
            fixture.virtio().clone(),
            fixture.transport().clone(),
        )
        .expect("fake request-specific virtio-mem state should validate")
    }

    fn fake_native_v2_publication_memory(
        memory_hotplug: Option<&SnapshotV2MemoryHotplugState>,
    ) -> GuestMemory {
        const BASE_START: u64 = 0x8000_0000;
        const BASE_SIZE: u64 = 16 * 1024;
        const BASE_ALIGNMENT: u64 = 16 * 1024;

        let mut base_start = BASE_START;
        let mut base_end = BASE_START + BASE_SIZE;
        if let Some(state) = memory_hotplug {
            for queue in state.virtio().queues() {
                if queue.size() == 0 {
                    continue;
                }
                let descriptor_size = u64::from(queue.size()) * 16;
                let available_size = u64::from(queue.size()) * 2 + 6;
                let used_size = u64::from(queue.size()) * 8 + 6;
                for (start, size) in [
                    (queue.descriptor_table().raw_value(), descriptor_size),
                    (queue.driver_ring().raw_value(), available_size),
                    (queue.device_ring().raw_value(), used_size),
                ] {
                    base_start = base_start.min(start & !(BASE_ALIGNMENT - 1));
                    base_end = base_end.max(
                        start
                            .checked_add(size)
                            .and_then(|end| end.checked_add(BASE_ALIGNMENT - 1))
                            .expect("fake queue range should fit")
                            & !(BASE_ALIGNMENT - 1),
                    );
                }
            }
        }

        let mut ranges = vec![
            GuestMemoryRange::new(GuestAddress::new(base_start), base_end - base_start)
                .expect("fake base-memory range should validate"),
        ];
        if let Some(state) = memory_hotplug {
            let config_space = state.config_space();
            for plugged in state.plugged_ranges() {
                let start = plugged
                    .start_block()
                    .checked_mul(config_space.block_size())
                    .and_then(|offset| config_space.addr().checked_add(offset))
                    .expect("fake plugged-memory start should fit");
                let size = plugged
                    .block_count()
                    .checked_mul(config_space.block_size())
                    .expect("fake plugged-memory size should fit");
                ranges.push(
                    GuestMemoryRange::new(GuestAddress::new(start), size)
                        .expect("fake plugged-memory range should validate"),
                );
            }
        }
        ranges.sort_by_key(|range| range.start());
        let layout =
            GuestMemoryLayout::new(ranges).expect("fake v2 publication memory should validate");
        GuestMemory::allocate(&layout).expect("fake v2 publication memory should allocate")
    }

    fn fixture_hex_bytes(hex: &str) -> Vec<u8> {
        let hex = hex.split_ascii_whitespace().collect::<String>();
        assert!(hex.len().is_multiple_of(2));
        hex.as_bytes()
            .chunks_exact(2)
            .map(|pair| {
                let pair = std::str::from_utf8(pair).expect("fixture hex should be UTF-8");
                u8::from_str_radix(pair, 16).expect("fixture hex should decode")
            })
            .collect()
    }

