        let config = executor
            .boot_session_config_for_controller(&controller)
            .expect("configured serial output should open");

        let mut output = config
            .serial_device
            .expect("default HVF boot config should include serial MMIO")
            .output
            .clone();
        output
            .write_byte(b'S')
