    #[test]
    fn boot_run_loop_supervisor_handles_concurrent_command_callers() {
        let control = FakeRunLoopControl::default();
        let drop_count = Arc::new(AtomicU64::new(0));
        let (max_steps_sender, max_steps_receiver) = mpsc::channel();
        let session =
            FakeRunLoopSession::new(control.clone(), Arc::clone(&drop_count), max_steps_sender)
                .with_outcomes([
                    Ok(FakeRunLoopOutcome::StepLimitReached),
                    Ok(FakeRunLoopOutcome::Terminal),
                ]);

        let supervisor =
            BootRunLoopSupervisor::start(session, NonZeroUsize::new(41).expect("non-zero limit"))
                .expect("supervisor should start");
        let command_handle = supervisor.command_handle();

        assert_eq!(
            max_steps_receiver
                .recv()
                .expect("worker should enter run loop"),
            41
        );

        let mut results = std::thread::scope(|scope| {
            let mut handles = Vec::new();
            for index in 0..4 {
                let handle = command_handle.clone();
                handles.push(scope.spawn(move || {
                    handle.run(move |session| {
                        Ok::<_, FakeRunLoopCommandError>((
                            index,
                            session.run_count.load(Ordering::SeqCst),
                        ))
                    })
                }));
            }

            control.wait_for_request_wakeup_count(4);
            control
                .request_stop()
                .expect("fake stop should release fake run loop");

            handles
                .into_iter()
                .map(|handle| {
                    handle
                        .join()
                        .expect("command caller should not panic")
                        .expect("command should succeed")
                })
                .collect::<Vec<_>>()
        });
        results.sort_unstable();

        assert_eq!(
            results.iter().map(|(index, _)| *index).collect::<Vec<_>>(),
            [0, 1, 2, 3]
        );
        assert!(results.iter().all(|(_, run_count)| *run_count > 0));
        assert_eq!(control.request_wakeup_count(), 4);

        drop(supervisor);

        assert_eq!(control.request_stop_count(), 2);
        assert_eq!(drop_count.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn boot_run_loop_supervisor_serializes_concurrent_mixed_runtime_mutations() {
        let control = FakeRunLoopControl::default();
        let drop_count = Arc::new(AtomicU64::new(0));
        let (max_steps_sender, max_steps_receiver) = mpsc::channel();
        let session =
            FakeRunLoopSession::new(control.clone(), Arc::clone(&drop_count), max_steps_sender)
                .with_wait_for_stop(false)
                .with_wait_for_wakeup(true)
                .with_outcomes([
                    Ok(FakeRunLoopOutcome::Wakeup),
                    Ok(FakeRunLoopOutcome::Terminal),
                ]);
        let events = session.runtime_device_events();
        let supervisor =
            BootRunLoopSupervisor::start(session, NonZeroUsize::new(42).expect("non-zero limit"))
                .expect("supervisor should start");
        assert_eq!(
            max_steps_receiver
                .recv()
                .expect("worker should enter run loop"),
            42
        );
        supervisor.pause().expect("worker should pause");
        let command_handle = supervisor.command_handle();

        let block_path = TempFilePath::create("concurrent-mixed-runtime-block");
        let block_config = DriveConfigInput::new("shared", "shared", block_path.path(), false)
            .validate()
            .expect("runtime block config should validate");
        let prepared_block = PreparedBlockDevice::from_config_with_backing(&block_config, None)
            .expect("runtime block backing should prepare");
        let (pmem_config, pmem_backing) =
            runtime_pmem_fixture("concurrent-mixed-runtime-pmem", "shared");
        let network_config = network_configs([("shared", "vmnet:shared")]).remove(0);

        std::thread::scope(|scope| {
            let block_handle = command_handle.clone();
            let block = scope.spawn(move || {
                block_handle.run(move |session| {
                    session.insert_runtime_block_device(RuntimeBlockDeviceResource::prepared(
                        prepared_block,
                    ))
                })
            });
            let pmem_handle = command_handle.clone();
            let pmem = scope.spawn(move || {
                pmem_handle.run(move |session| {
                    session.insert_runtime_pmem_device(pmem_config, pmem_backing)
                })
            });
            let network_handle = command_handle.clone();
            let network = scope.spawn(move || {
                network_handle.run(move |session| {
                    session.insert_runtime_network_device(
                        network_config,
                        ProcessVmnetAuthority::Direct,
                    )
                })
            });

            block
                .join()
                .expect("block caller should not panic")
                .expect("block command should succeed");
            pmem.join()
                .expect("pmem caller should not panic")
                .expect("pmem command should succeed");
            network
                .join()
                .expect("network caller should not panic")
                .expect("network command should succeed");
        });

        let mut events = events
            .lock()
            .expect("mixed runtime events should lock")
            .clone();
        events.sort_unstable();
        assert_eq!(
            events,
            [
                "block:insert:shared".to_string(),
                "network:insert:shared".to_string(),
                "pmem:insert:shared".to_string(),
            ]
        );
        assert_eq!(
            supervisor
                .run_command(|session| {
                    Ok::<_, FakeRunLoopCommandError>(session.run_count.load(Ordering::SeqCst))
                })
                .expect("mixed commands should leave the owner usable"),
            1
        );
        assert_eq!(supervisor.status(), BootRunLoopWorkerStatus::Paused);

        drop(supervisor);

        assert_eq!(control.request_stop_count(), 1);
        assert_eq!(drop_count.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn boot_run_loop_supervisor_records_successful_vhost_config_change_latency() {
        let control = FakeRunLoopControl::default();
        let drop_count = Arc::new(AtomicU64::new(0));
        let metrics = SharedBlockDeviceMetricsRegistry::from_drive_ids(["vhost"]);
        let (max_steps_sender, max_steps_receiver) = mpsc::channel();
        let session =
            FakeRunLoopSession::new(control.clone(), Arc::clone(&drop_count), max_steps_sender)
                .with_block_device_update_result(Ok(()))
                .with_block_device_metrics(metrics)
                .with_wait_for_stop(false)
                .with_wait_for_wakeup(true)
                .with_outcomes([
                    Ok(FakeRunLoopOutcome::Wakeup),
                    Ok(FakeRunLoopOutcome::Terminal),
                ]);
        let mut supervisor =
            BootRunLoopSupervisor::start(session, NonZeroUsize::new(41).expect("non-zero limit"))
                .expect("supervisor should start");
        assert_eq!(
            max_steps_receiver
                .recv()
                .expect("worker should enter run loop"),
            41
        );
        let config = DriveConfigInput::new_without_path_on_host("vhost", "vhost", false)
            .with_socket("/private/vhost.sock")
            .validate()
            .expect("vhost-user drive should validate");

        supervisor
            .update_block_device(
                &config,
                BlockBackingUpdate::Unchanged,
                None,
                DriveLiveUpdateMode::Patch,
            )
            .expect("vhost-user config refresh should run on worker");

        let diagnostics = supervisor.metrics_diagnostics();
        let aggregate = diagnostics
            .block_device_metrics()
            .expect("aggregate block metrics should be present");
        assert_eq!(aggregate.update_count(), 1);
        assert_eq!(aggregate.update_fails(), 0);
        assert!(aggregate.config_change_time_us().is_some());
        let per_drive = diagnostics
            .block_device_metrics_by_drive()
            .expect("per-drive block metrics should be present")
            .iter()
            .find_map(|(drive_id, metrics)| (drive_id == "vhost").then_some(metrics))
            .expect("vhost metrics should be present");
        assert_eq!(per_drive.update_count(), 1);
        assert_eq!(
            per_drive.config_change_time_us(),
            aggregate.config_change_time_us()
        );

        drop(supervisor);
        assert_eq!(drop_count.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn boot_run_loop_supervisor_terminalizes_ambiguous_vhost_config_change() {
        let control = FakeRunLoopControl::default();
        let drop_count = Arc::new(AtomicU64::new(0));
        let metrics = SharedBlockDeviceMetricsRegistry::from_drive_ids(["vhost"]);
        let (max_steps_sender, max_steps_receiver) = mpsc::channel();
        let session =
            FakeRunLoopSession::new(control.clone(), Arc::clone(&drop_count), max_steps_sender)
                .with_block_device_update_result(Err(
                    DriveUpdateError::TerminalActiveSessionCommand {
                        message: "injected ambiguous configuration interrupt".to_string(),
                    },
                ))
                .with_block_device_metrics(metrics)
                .with_wait_for_stop(false)
                .with_wait_for_wakeup(true)
                .with_outcomes([
                    Ok(FakeRunLoopOutcome::Wakeup),
                    Ok(FakeRunLoopOutcome::Terminal),
                ]);
        let mut supervisor =
            BootRunLoopSupervisor::start(session, NonZeroUsize::new(42).expect("non-zero limit"))
                .expect("supervisor should start");
        assert_eq!(
            max_steps_receiver
                .recv()
                .expect("worker should enter run loop"),
            42
        );
        let config = DriveConfigInput::new_without_path_on_host("vhost", "vhost", false)
            .with_socket("/private/vhost.sock")
            .validate()
            .expect("vhost-user drive should validate");

        let error = supervisor
            .update_block_device(
                &config,
                BlockBackingUpdate::Unchanged,
                None,
                DriveLiveUpdateMode::Patch,
            )
            .expect_err("ambiguous vhost config delivery should fail terminally");

        assert!(matches!(
            error,
            DriveUpdateError::TerminalActiveSessionCommand { message }
                if message == "injected ambiguous configuration interrupt"
        ));
        assert!(matches!(
            supervisor.status(),
            BootRunLoopWorkerStatus::Failed(message)
                if message.contains("injected ambiguous configuration interrupt")
        ));
        assert_eq!(
            supervisor.admission_state(),
            BootRunLoopCommandAdmissionState::Shutdown
        );
        assert_eq!(control.request_stop_count(), 1);
        let aggregate = supervisor
            .metrics_diagnostics()
            .block_device_metrics()
            .expect("aggregate block metrics should be present");
        assert_eq!(aggregate.update_count(), 0);
        assert_eq!(aggregate.update_fails(), 1);
        assert_eq!(aggregate.config_change_time_us(), None);

        drop(supervisor);
        assert_eq!(drop_count.load(Ordering::SeqCst), 1);
    }

