    #[cfg(target_os = "macos")]
    #[test]
    fn snapshot_create_logger_closes_success_rejection_failure_and_cancellation() {
        let success_directory = TempSnapshotDirectory::new("snapshot-log-success");
        let success_paths = success_directory.paths();
        let success_log = TempFilePath::create("private-snapshot-success-log");
        let mut success = snapshot_profile_vmm(FakeStarter::success(127));
        success
            .handle_action(VmmAction::PutLogger(
                LoggerConfigInput::new().with_log_path(success_log.path()),
            ))
            .expect("success logger should configure");
        success
            .handle_action(VmmAction::InstanceStart)
            .expect("success source should start");
        success
            .handle_action(VmmAction::Pause)
            .expect("success source should pause");
        success
            .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                SnapshotType::Full,
                success_paths.state(),
                success_paths.memory(),
            )))
            .expect("snapshot should succeed");
        let output = fs::read_to_string(success_log.path()).expect("success log should read");
        assert!(output.contains("operation=snapshot-create outcome=succeeded\n"));
        assert!(
            !output.contains(
                success_paths
                    .state()
                    .to_str()
                    .expect("success state path should be UTF-8")
            )
        );
        assert!(
            !output.contains(
                success_paths
                    .memory()
                    .to_str()
                    .expect("success memory path should be UTF-8")
            )
        );

        let rejected_log = TempFilePath::create("private-snapshot-rejected-log");
        let mut rejected = configured_vmm(FakeStarter::success(128));
        rejected
            .handle_action(VmmAction::PutLogger(
                LoggerConfigInput::new().with_log_path(rejected_log.path()),
            ))
            .expect("rejection logger should configure");
        assert!(
            rejected
                .handle_action(snapshot_create_action(SnapshotType::Full))
                .is_err()
        );
        assert_eq!(
            fs::read_to_string(rejected_log.path()).expect("rejection log should read"),
            "operation=snapshot-create outcome=rejected\n"
        );

        let failed_directory = TempSnapshotDirectory::new("snapshot-log-failed");
        let failed_paths = failed_directory.paths();
        fs::write(failed_paths.state(), b"private-existing-snapshot-state")
            .expect("existing snapshot state should create a publication collision");
        let failed_log = TempFilePath::create("private-snapshot-failed-log");
        let mut failed = snapshot_profile_vmm(FakeStarter::success(129));
        failed
            .handle_action(VmmAction::PutLogger(
                LoggerConfigInput::new().with_log_path(failed_log.path()),
            ))
            .expect("failure logger should configure");
        failed
            .handle_action(VmmAction::InstanceStart)
            .expect("failure source should start");
        failed
            .handle_action(VmmAction::Pause)
            .expect("failure source should pause");
        assert!(
            failed
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Full,
                    failed_paths.state(),
                    failed_paths.memory(),
                )))
                .is_err()
        );
        let output = fs::read_to_string(failed_log.path()).expect("failure log should read");
        assert!(output.contains("operation=snapshot-create outcome=failed\n"));
        assert!(
            !output.contains(
                failed_paths
                    .state()
                    .to_str()
                    .expect("failed state path should be UTF-8")
            )
        );
        assert!(
            !output.contains(
                failed_paths
                    .memory()
                    .to_str()
                    .expect("failed memory path should be UTF-8")
            )
        );

        let cancellation = NativeV2SnapshotCaptureCancellation::default();
        let cancelled_directory = TempSnapshotDirectory::new("snapshot-log-cancelled");
        let cancelled_paths = cancelled_directory.paths();
        let cancelled_log = TempFilePath::create("private-snapshot-cancelled-log");
        let mut cancelled = snapshot_profile_vmm(FakeStarter::success(130))
            .with_snapshot_capture_cancellation(cancellation.clone());
        cancelled
            .handle_action(VmmAction::PutLogger(
                LoggerConfigInput::new().with_log_path(cancelled_log.path()),
            ))
            .expect("cancellation logger should configure");
        cancelled
            .handle_action(VmmAction::InstanceStart)
            .expect("cancelled source should start");
        cancelled
            .handle_action(VmmAction::Pause)
            .expect("cancelled source should pause");
        cancellation.cancel();
        assert!(
            cancelled
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Full,
                    cancelled_paths.state(),
                    cancelled_paths.memory(),
                )))
                .is_err()
        );
        let output = fs::read_to_string(cancelled_log.path()).expect("cancelled log should read");
        assert!(output.contains("operation=snapshot-create outcome=cancelled\n"));
        assert!(
            !output.contains(
                cancelled_paths
                    .state()
                    .to_str()
                    .expect("cancelled state path should be UTF-8")
            )
        );
        assert!(
            !output.contains(
                cancelled_paths
                    .memory()
                    .to_str()
                    .expect("cancelled memory path should be UTF-8")
            )
        );

        let preflight_directory = TempSnapshotDirectory::new("snapshot-log-preflight-cancelled");
        let preflight_paths = preflight_directory.paths();
        let preflight_log = TempFilePath::create("private-snapshot-preflight-cancelled-log");
        let mut preflight_cancelled = snapshot_profile_vmm(
            FakeStarter::success(131).with_snapshot_storage_preflight_failure(
                HvfArm64BootStorageCaptureError::cancelled(),
            ),
        );
        preflight_cancelled
            .handle_action(VmmAction::PutLogger(
                LoggerConfigInput::new().with_log_path(preflight_log.path()),
            ))
            .expect("preflight cancellation logger should configure");
        preflight_cancelled
            .handle_action(VmmAction::InstanceStart)
            .expect("preflight cancellation source should start");
        preflight_cancelled
            .handle_action(VmmAction::Pause)
            .expect("preflight cancellation source should pause");
        assert!(
            preflight_cancelled
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Full,
                    preflight_paths.state(),
                    preflight_paths.memory(),
                )))
                .is_err()
        );
        let output = fs::read_to_string(preflight_log.path())
            .expect("preflight cancellation log should read");
        assert!(output.contains("operation=snapshot-create outcome=cancelled\n"));
        assert!(!output.contains("operation=snapshot-create outcome=rejected\n"));
        assert!(
            !output.contains(
                preflight_paths
                    .state()
                    .to_str()
                    .expect("preflight cancellation state path should be UTF-8")
            )
        );
        assert!(
            !output.contains(
                preflight_paths
                    .memory()
                    .to_str()
                    .expect("preflight cancellation memory path should be UTF-8")
            )
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn public_native_v2_process_publication_is_loadable_and_repeatable() {
        let public_directory = TempSnapshotDirectory::new("native-v2-public-gate");
        let public_paths = public_directory.paths();
        let public_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            public_paths.state(),
            public_paths.memory(),
        );
        let mut vmm = paused_native_v2_profile_vmm(FakeStarter::success(171));
        let machine_before = vmm.machine_config();

        assert_eq!(
            vmm.handle_action(VmmAction::CreateSnapshot(public_input)),
            Ok(VmmData::Empty)
        );
        let session = vmm
            .started_session
            .as_ref()
            .expect("public publication should retain the paused source");
        assert_eq!(session.native_snapshot_publication_count, 1);
        assert_eq!(session.native_snapshot_producer_count, 1);
        assert_eq!(
            load_native_snapshot_artifacts(&public_paths)
                .expect("public native-v2 pair should load")
                .family(),
            NativeSnapshotArtifactFamily::V2
        );
        public_directory.assert_no_staging();

        let first_directory = TempSnapshotDirectory::new("native-v2-process-first");
        let first_paths = first_directory.paths();
        let first_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            first_paths.state(),
            first_paths.memory(),
        );
        assert_eq!(
            vmm.publish_native_v2_snapshot(&first_input)
                .expect("internal native-v2 publication should succeed"),
            SnapshotCommitDurability::Durable
        );
        let first = load_native_snapshot_artifacts(&first_paths)
            .expect("internal native-v2 pair should load");
        assert_eq!(first.family(), NativeSnapshotArtifactFamily::V2);
        assert_eq!(first.memory().total_size(), 16 * 1024);
        assert_eq!(vmm.machine_config(), machine_before);
        assert_eq!(vmm.instance_info().state, InstanceState::Paused);
        first_directory.assert_no_staging();

        let second_directory = TempSnapshotDirectory::new("native-v2-process-second");
        let second_paths = second_directory.paths();
        let second_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            second_paths.state(),
            second_paths.memory(),
        );
        assert_eq!(
            vmm.publish_native_v2_snapshot(&second_input)
                .expect("same paused source should publish to fresh paths"),
            SnapshotCommitDurability::Durable
        );
        assert_eq!(
            load_native_snapshot_artifacts(&second_paths)
                .expect("second internal native-v2 pair should load")
                .family(),
            NativeSnapshotArtifactFamily::V2
        );
        let session = vmm
            .started_session
            .as_ref()
            .expect("successful publications should retain the source");
        assert_eq!(session.native_snapshot_publication_count, 3);
        assert_eq!(session.native_snapshot_producer_count, 3);
        assert_eq!(session.snapshot_create_barrier_count, 0);
        second_directory.assert_no_staging();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn public_native_v2_create_and_load_routes_all_products_over_mmio_and_pci() {
        for (case, has_block, has_pmem) in [
            ("serial", false, false),
            ("block", true, false),
            ("pmem", false, true),
            ("mixed", true, true),
        ] {
            for has_entropy in [false, true] {
                for has_balloon in [false, true] {
                    for has_memory_hotplug in [false, true] {
                        for (transport, pci_enabled) in [
                            (SnapshotV2DeviceTransportKind::Mmio, false),
                            (SnapshotV2DeviceTransportKind::Pci, true),
                        ] {
                            let mut product = match (has_entropy, has_balloon) {
                                (false, false) => case.to_owned(),
                                (true, false) => format!("{case}-entropy"),
                                (false, true) => format!("{case}-balloon"),
                                (true, true) => format!("{case}-entropy-balloon"),
                            };
                            if has_memory_hotplug {
                                product.push_str("-memory-hotplug");
                            }
                            let directory = TempSnapshotDirectory::new(&format!(
                                "native-v2-{product}-{transport:?}"
                            ));
                            let paths = directory.paths();
                            let mut source = configured_vmm(FakeStarter::success(190));
                            source.pci_enabled = pci_enabled;
                            let block_is_root = has_block && !pci_enabled;
                            let pmem_is_root =
                                has_pmem && (has_block || !pci_enabled) && !block_is_root;
                            if has_block {
                                source
                                    .handle_action(VmmAction::PutDrive(
                                        DriveConfigInput::new(
                                            "rootfs",
                                            "rootfs",
                                            "/private/rootfs.ext4",
                                            block_is_root,
                                        )
                                        .with_is_read_only(true)
                                        .with_io_engine(DriveIoEngine::Sync),
                                    ))
                                    .expect("public storage block should configure");
                            }
                            if has_pmem {
                                source
                                    .handle_action(VmmAction::PutPmem(
                                        PmemConfigInput::new("pmem0", "/private/pmem0.img")
                                            .with_root_device(pmem_is_root),
                                    ))
                                    .expect("public storage pmem should configure");
                            }
                            if has_entropy {
                                source
                                    .handle_action(VmmAction::PutEntropy(EntropyConfigInput::new()))
                                    .expect("public entropy should configure");
                            }
                            if has_balloon {
                                source
                                    .handle_action(VmmAction::PutBalloon(BalloonConfigInput::new(
                                        64, false,
                                    )))
                                    .expect("public balloon should configure");
                            }
                            if has_memory_hotplug {
                                source
                                    .handle_action(VmmAction::PutMemoryHotplug(
                                        memory_hotplug_config_input(),
                                    ))
                                    .expect("public virtio-mem should configure");
                            }
                            source
                                .handle_action(VmmAction::InstanceStart)
                                .expect("public exact-2.12 source should start");
                            if has_memory_hotplug {
                                source
                                    .handle_action(VmmAction::PatchMemoryHotplug(
                                        memory_hotplug_size_update_input(128),
                                    ))
                                    .expect("public virtio-mem requested size should update");
                            }
                            source
                                .handle_action(VmmAction::Pause)
                                .expect("public exact-2.12 source should pause");
                            source
                            .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                                SnapshotType::Full,
                                paths.state(),
                                paths.memory(),
                            )))
                            .unwrap_or_else(|error| {
                                panic!(
                                    "{product} {transport:?} public create should succeed: {error}"
                                )
                            });

                            let loaded = load_native_snapshot_artifacts(&paths)
                                .expect("public exact-2.12 pair should load");
                            let (candidate, _) = loaded
                                .into_current_v2_candidate()
                                .expect("public pair should retain the exact current candidate");
                            assert_eq!(
                                candidate.version(),
                                NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION
                            );
                            assert_eq!(candidate.entropy().is_some(), has_entropy);
                            if let Some(entropy) = candidate.entropy() {
                                assert_eq!(entropy.transport().kind(), transport);
                            }
                            assert_eq!(candidate.balloon().is_some(), has_balloon);
                            if let Some(balloon) = candidate.balloon() {
                                assert_eq!(balloon.transport().kind(), transport);
                            }
                            assert_eq!(candidate.memory_hotplug().is_some(), has_memory_hotplug);
                            if let Some(memory_hotplug) = candidate.memory_hotplug() {
                                assert_eq!(memory_hotplug.transport().kind(), transport);
                                assert_eq!(memory_hotplug.config(), memory_hotplug_config());
                                assert_eq!(
                                    memory_hotplug.config_space().requested_size(),
                                    128 * 1024 * 1024
                                );
                                PreparedSnapshotV2MemoryHotplugTopology::prepare_for_compatibility_version(
                                    memory_hotplug.clone(),
                                    candidate.memory_binding().clone(),
                                    NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION,
                                )
                                .expect("public exact-2.12 virtio-mem memory binding should close");
                            }
                            match candidate.device_graph() {
                                Some(graph) => {
                                    assert_eq!(graph.transport_kind(), transport);
                                    assert_eq!(graph.block_records().len(), usize::from(has_block));
                                    assert_eq!(graph.pmem_records().len(), usize::from(has_pmem));
                                }
                                None => assert!(!has_block && !has_pmem),
                            }

                            let starter =
                                FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
                            let calls = starter.calls();
                            let mut destination = ProcessVmm::with_starter(
                                format!("native-v2-{product}-{transport:?}-destination"),
                                "0.1.0",
                                "bangbang",
                                starter,
                            );
                            destination.pci_enabled = pci_enabled;
                            destination
                            .handle_action(VmmAction::LoadSnapshot(SnapshotLoadInput::new(
                                paths.state(),
                                SnapshotMemoryBackend::new(
                                    paths.memory(),
                                    SnapshotMemoryBackendType::File,
                                ),
                            )))
                            .unwrap_or_else(|error| {
                                panic!(
                                    "{product} {transport:?} public load should succeed: {error}"
                                )
                            });
                            assert_eq!(calls.load(Ordering::SeqCst), 1);
                            assert_eq!(destination.instance_info().state, InstanceState::Paused);
                            assert_eq!(destination.drive_configs().len(), usize::from(has_block));
                            assert_eq!(
                                destination.controller.pmem_configs().len(),
                                usize::from(has_pmem)
                            );
                            assert_eq!(
                                destination.controller.entropy_config().is_some(),
                                has_entropy
                            );
                            assert_eq!(
                                destination.controller.balloon_config().is_some(),
                                has_balloon
                            );
                            assert_eq!(
                                destination.controller.memory_hotplug_config().is_some(),
                                has_memory_hotplug
                            );
                            assert_eq!(
                                destination
                                    .controller
                                    .memory_hotplug_status()
                                    .map(|status| status.requested_size_mib()),
                                has_memory_hotplug.then_some(128)
                            );
                            if has_entropy || has_balloon || has_memory_hotplug {
                                let peer_starter =
                                    FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
                                let peer_calls = peer_starter.calls();
                                let mut peer = ProcessVmm::with_starter(
                                    format!("native-v2-{product}-{transport:?}-same-process-peer"),
                                    "0.1.0",
                                    "bangbang",
                                    peer_starter,
                                );
                                peer.pci_enabled = pci_enabled;
                                peer.handle_action(VmmAction::LoadSnapshot(
                            SnapshotLoadInput::new(
                                paths.state(),
                                SnapshotMemoryBackend::new(
                                    paths.memory(),
                                    SnapshotMemoryBackendType::File,
                                ),
                            )
                            .with_resume_vm(true),
                        ))
                        .unwrap_or_else(|error| {
                            panic!(
                                "{product} {transport:?} same-process peer load should succeed: {error}"
                            )
                        });
                                assert_eq!(peer_calls.load(Ordering::SeqCst), 1);
                                assert_eq!(calls.load(Ordering::SeqCst), 1);
                                assert_eq!(peer.instance_info().state, InstanceState::Running);
                                assert_eq!(
                                    destination.instance_info().state,
                                    InstanceState::Paused,
                                    "peer load must not change the first destination"
                                );
                                assert_eq!(peer.drive_configs(), destination.drive_configs());
                                assert_eq!(
                                    peer.controller.pmem_configs(),
                                    destination.controller.pmem_configs()
                                );
                                assert_eq!(
                                    peer.controller.entropy_config(),
                                    destination.controller.entropy_config()
                                );
                                assert_eq!(
                                    peer.controller.balloon_config(),
                                    destination.controller.balloon_config()
                                );
                                assert_eq!(
                                    peer.controller.memory_hotplug_config(),
                                    destination.controller.memory_hotplug_config()
                                );
                                assert_eq!(
                                    peer.controller.memory_hotplug_status(),
                                    destination.controller.memory_hotplug_status()
                                );
                            }
                            directory.assert_no_staging();
                        }
                    }
                }
            }
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn public_native_v2_network_create_and_load_requires_exact_overrides_over_mmio_and_pci() {
        for (transport, pci_enabled) in [
            (SnapshotV2DeviceTransportKind::Mmio, false),
            (SnapshotV2DeviceTransportKind::Pci, true),
        ] {
            let directory = TempSnapshotDirectory::new(&format!("native-v2-network-{transport:?}"));
            let paths = directory.paths();
            let mut source = configured_vmm(FakeStarter::success(191));
            source.pci_enabled = pci_enabled;
            source
                .handle_action(VmmAction::PutNetworkInterface(
                    NetworkInterfaceConfigInput::new("eth0", "eth0", "source-private-selector")
                        .with_guest_mac("02:00:00:00:00:01")
                        .with_mtu(1400),
                ))
                .expect("public network source should configure");
            source
                .handle_action(VmmAction::InstanceStart)
                .expect("public network source should start");
            source
                .handle_action(VmmAction::Pause)
                .expect("public network source should pause");
            source
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Full,
                    paths.state(),
                    paths.memory(),
                )))
                .unwrap_or_else(|error| {
                    panic!("{transport:?} public network create should succeed: {error}")
                });
            drop(source);

            let state_before =
                fs::read(paths.state()).expect("public network state bytes should read");
            let memory_before =
                fs::read(paths.memory()).expect("public network memory bytes should read");
            let loaded = load_native_snapshot_artifacts(&paths)
                .expect("public network artifact pair should load");
            let (candidate, _) = loaded
                .into_current_v2_candidate()
                .expect("public network pair should retain the current candidate");
            let network = candidate
                .network()
                .expect("public network pair should contain kind-12 state");
            assert_eq!(network.interfaces().len(), 1);
            assert_eq!(network.interfaces()[0].transport().kind(), transport);
            assert!(network.mmds().is_none());
            let iface_id = network.interfaces()[0].iface_id().to_owned();

            let missing_starter = FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
            let missing_calls = missing_starter.calls();
            let mut missing = ProcessVmm::with_starter(
                format!("native-v2-network-{transport:?}-missing"),
                "0.1.0",
                "bangbang",
                missing_starter,
            );
            missing.pci_enabled = pci_enabled;
            let missing_error = missing
                .handle_action(VmmAction::LoadSnapshot(SnapshotLoadInput::new(
                    paths.state(),
                    SnapshotMemoryBackend::new(paths.memory(), SnapshotMemoryBackendType::File),
                )))
                .expect_err("network-bearing load must reject missing overrides");
            assert_eq!(missing_calls.load(Ordering::SeqCst), 0);
            assert_eq!(missing.instance_info().state, InstanceState::NotStarted);
            assert!(!missing.has_started_session());

            let wrong_starter = FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
            let wrong_calls = wrong_starter.calls();
            let mut wrong = ProcessVmm::with_starter(
                format!("native-v2-network-{transport:?}-wrong"),
                "0.1.0",
                "bangbang",
                wrong_starter,
            );
            wrong.pci_enabled = pci_enabled;
            let wrong_error = wrong
                .handle_action(VmmAction::LoadSnapshot(
                    SnapshotLoadInput::new(
                        paths.state(),
                        SnapshotMemoryBackend::new(paths.memory(), SnapshotMemoryBackendType::File),
                    )
                    .with_network_overrides(vec![
                        SnapshotNetworkOverride::new("unknown-interface", "wrong-private-selector"),
                    ]),
                ))
                .expect_err("network-bearing load must reject a non-exact override set");
            assert_eq!(wrong_calls.load(Ordering::SeqCst), 0);
            assert_eq!(wrong.instance_info().state, InstanceState::NotStarted);
            assert!(!wrong.has_started_session());
            let diagnostics =
                format!("{missing_error:?} {missing_error} {wrong_error:?} {wrong_error}");
            assert!(!diagnostics.contains("wrong-private-selector"));
            assert!(!diagnostics.contains(paths.state().to_string_lossy().as_ref()));
            assert!(!diagnostics.contains(paths.memory().to_string_lossy().as_ref()));

            let paused_starter = FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
            let paused_calls = paused_starter.calls();
            let mut paused = ProcessVmm::with_starter(
                format!("native-v2-network-{transport:?}-paused"),
                "0.1.0",
                "bangbang",
                paused_starter,
            );
            paused.pci_enabled = pci_enabled;
            paused
                .handle_action(VmmAction::LoadSnapshot(
                    SnapshotLoadInput::new(
                        paths.state(),
                        SnapshotMemoryBackend::new(paths.memory(), SnapshotMemoryBackendType::File),
                    )
                    .with_network_overrides(vec![
                        SnapshotNetworkOverride::new(iface_id.clone(), "paused-private-selector"),
                    ]),
                ))
                .unwrap_or_else(|error| {
                    panic!("{transport:?} paused network load should succeed: {error}")
                });
            assert_eq!(paused_calls.load(Ordering::SeqCst), 1);
            assert_eq!(paused.instance_info().state, InstanceState::Paused);
            assert_eq!(paused.controller.network_interface_configs().len(), 1);
            assert_eq!(
                paused.controller.network_interface_configs()[0].iface_id(),
                iface_id
            );
            assert_eq!(
                paused.controller.network_interface_configs()[0].host_dev_name(),
                "paused-private-selector"
            );
            assert_eq!(
                paused
                    .controller
                    .mmds_config()
                    .expect("MMDS state should lock"),
                None
            );

            let running_starter = FakeSnapshotLoadStarter::new(FakeSnapshotLoadResult::Success);
            let running_calls = running_starter.calls();
            let mut running = ProcessVmm::with_starter(
                format!("native-v2-network-{transport:?}-running"),
                "0.1.0",
                "bangbang",
                running_starter,
            );
            running.pci_enabled = pci_enabled;
            running
                .handle_action(VmmAction::LoadSnapshot(
                    SnapshotLoadInput::new(
                        paths.state(),
                        SnapshotMemoryBackend::new(paths.memory(), SnapshotMemoryBackendType::File),
                    )
                    .with_network_overrides(vec![SnapshotNetworkOverride::new(
                        iface_id,
                        "running-private-selector",
                    )])
                    .with_resume_vm(true),
                ))
                .unwrap_or_else(|error| {
                    panic!("{transport:?} resumed network load should succeed: {error}")
                });
            assert_eq!(running_calls.load(Ordering::SeqCst), 1);
            assert_eq!(running.instance_info().state, InstanceState::Running);
            assert_eq!(
                running.controller.network_interface_configs()[0].host_dev_name(),
                "running-private-selector"
            );
            assert_eq!(
                fs::read(paths.state()).expect("state bytes should remain readable"),
                state_before
            );
            assert_eq!(
                fs::read(paths.memory()).expect("memory bytes should remain readable"),
                memory_before
            );
            directory.assert_no_staging();
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn native_v2_process_rejects_other_family_and_incomplete_profile_before_construction() {
        let v1_directory = TempSnapshotDirectory::new("native-v2-reject-v1-family");
        let v1_paths = v1_directory.paths();
        let mut v1_source = snapshot_profile_vmm(FakeStarter::success(183));
        v1_source
            .handle_action(VmmAction::InstanceStart)
            .expect("native-v1 fixture should start");
        v1_source
            .handle_action(VmmAction::Pause)
            .expect("native-v1 fixture should pause");
        v1_source
            .publish_native_v1_snapshot(&SnapshotCreateInput::new(
                SnapshotType::Full,
                v1_paths.state(),
                v1_paths.memory(),
            ))
            .expect("native-v1 fixture should publish");
        drop(v1_source);

        let mut destination = ProcessVmm::with_starter(
            "native-v2-hostile-destination",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        );
        let v1_error = destination
            .restore_native_v2_snapshot(&SnapshotLoadInput::new(
                v1_paths.state(),
                SnapshotMemoryBackend::new(v1_paths.memory(), SnapshotMemoryBackendType::File),
            ))
            .expect_err("native-v1 family must fail before process construction");
        assert!(matches!(
            &v1_error,
            NativeV2SnapshotLoadError::UnexpectedFamily(NativeSnapshotArtifactFamily::V1)
        ));
        assert_eq!(destination.instance_info().state, InstanceState::NotStarted);
        assert!(!destination.has_started_session());
        assert!(!destination.terminal_snapshot_load_failure);

        let v2_directory = TempSnapshotDirectory::new("native-v2-reject-incomplete-profile");
        let v2_paths = v2_directory.paths();
        let mut v2_source = paused_native_v2_profile_vmm(FakeStarter::success(184));
        v2_source
            .publish_native_v2_snapshot(&SnapshotCreateInput::new(
                SnapshotType::Full,
                v2_paths.state(),
                v2_paths.memory(),
            ))
            .expect("memory-only native-v2 fixture should publish");
        drop(v2_source);
        let retained_memory = v2_paths.memory().with_file_name("unopened.memory");
        fs::rename(v2_paths.memory(), &retained_memory)
            .expect("incomplete profile memory should move out of reach");

        let v2_error = destination
            .restore_native_snapshot(&SnapshotLoadInput::new(
                v2_paths.state(),
                SnapshotMemoryBackend::new(v2_paths.memory(), SnapshotMemoryBackendType::File),
            ))
            .expect_err("incomplete native-v2 profile must fail before memory access");
        assert!(matches!(
            &v2_error,
            NativeSnapshotLoadError::NativeV2(NativeV2SnapshotLoadError::Decode(_))
        ));
        assert!(
            retained_memory.exists(),
            "preflight must not need the inaccessible memory path"
        );
        let diagnostics = format!("{v1_error:?} {v1_error} {v2_error:?} {v2_error}");
        assert!(!diagnostics.contains("native-v2-reject-v1-family"));
        assert!(!diagnostics.contains("native-v2-reject-incomplete-profile"));
        assert_eq!(destination.instance_info().state, InstanceState::NotStarted);
        assert!(!destination.has_started_session());
        assert!(!destination.terminal_snapshot_load_failure);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn contained_native_v2_process_preparation_uses_retained_pair_after_path_replacement() {
        const STATE_REFERENCE: &str = "bangbang-grant:snapshot-state";
        const MEMORY_REFERENCE: &str = "bangbang-grant:snapshot-memory";

        let directory = TempSnapshotDirectory::new("native-v2-contained-load");
        let paths = directory.paths();
        let input = SnapshotCreateInput::new(SnapshotType::Full, paths.state(), paths.memory());
        let mut source = paused_native_v2_profile_vmm(FakeStarter::success(182));
        source
            .publish_native_v2_snapshot(&input)
            .expect("contained fixture should publish one native-v2 pair");
        drop(source);

        let authority = snapshot_file_grant_authority_for_test(paths.state(), paths.memory());
        let replacement_state = paths.state().with_file_name("replacement.state");
        let replacement_memory = paths.memory().with_file_name("replacement.memory");
        fs::write(&replacement_state, b"replacement state")
            .expect("replacement state should write");
        fs::write(&replacement_memory, b"replacement memory")
            .expect("replacement memory should write");
        fs::rename(&replacement_state, paths.state())
            .expect("replacement state should replace the granted path");
        fs::rename(&replacement_memory, paths.memory())
            .expect("replacement memory should replace the granted path");

        let destination = ProcessVmm::with_starter(
            "native-v2-contained-destination",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        )
        .with_grant_authority(Some(authority));
        let load = SnapshotLoadInput::new(
            STATE_REFERENCE,
            SnapshotMemoryBackend::new(MEMORY_REFERENCE, SnapshotMemoryBackendType::File),
        );
        let loaded = destination
            .prepare_contained_snapshot_v2_load(&load)
            .expect("retained contained descriptors should prepare")
            .expect("explicit grant references should select contained preparation");
        assert_eq!(loaded.family(), NativeSnapshotArtifactFamily::V2);
        assert_eq!(loaded.memory().total_size(), 16 * 1024);
        drop(loaded);

        let error = destination
            .prepare_contained_snapshot_v2_load(&load)
            .expect_err("successful preparation should consume both exact grants");
        assert!(matches!(error, NativeV2SnapshotLoadError::Resource(_)));
        let diagnostics = format!("{error:?} {error}");
        assert!(!diagnostics.contains("snapshot-state"));
        assert!(!diagnostics.contains("snapshot-memory"));
        assert_eq!(
            fs::read(paths.state()).expect("replacement state should remain"),
            b"replacement state"
        );
        assert_eq!(
            fs::read(paths.memory()).expect("replacement memory should remain"),
            b"replacement memory"
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn verify_signed_exact_minor_eleven_process_network_owner_transaction(pci_enabled: bool) {
        use bangbang_hvf::{
            HvfSnapshotV2NetworkMmioProcessConfig, HvfSnapshotV2NetworkPreparedProduct,
            prepare_hvf_snapshot_v2_network_mmio_platform_plan,
            prepare_hvf_snapshot_v2_network_pci_platform_plan,
        };
        use bangbang_runtime::balloon::BalloonMmioLayout;
        use bangbang_runtime::entropy::EntropyMmioLayout;
        use bangbang_runtime::memory_hotplug::VirtioMemMmioLayout;
        use bangbang_runtime::snapshot_memory_v2::load_snapshot_v2_memory_path;

        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel =
            TempFilePath::create_with_bytes("signed-exact-2-11-process-network-kernel", &image);

        let mut controller = VmmController::new("exact-2-11-process-source", "0.1.0", "bangbang");
        controller
            .handle_action(VmmAction::PutMachineConfig(
                MachineConfigInput::new(1, 16).with_track_dirty_pages(true),
            ))
            .expect("network source machine should configure");
        controller
            .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                kernel.path(),
            )))
            .expect("network source boot metadata should configure");
        controller
            .handle_action(VmmAction::PutNetworkInterface(
                NetworkInterfaceConfigInput::new("eth0", "eth0", "vmnet:shared")
                    .with_guest_mac("02:00:00:00:00:01")
                    .with_mtu(1400),
            ))
            .expect("network source interface should configure");

        let configs = controller.network_interface_configs().to_vec();
        let profiles = configs
            .iter()
            .map(NetworkDeviceProfile::from_config)
            .collect::<Vec<_>>();
        let expected_mac = profiles[0]
            .guest_mac()
            .expect("saved vmnet profile should retain its requested MAC");
        let session_config = default_hvf_boot_session_config(SharedSerialOutput::from(
            SharedSerialOutputBuffer::default(),
        ));
        let session_config = if pci_enabled {
            session_config.with_pci_enabled()
        } else {
            session_config
        };
        let mut source = super::OwnedHvfArm64BootSession::new(&controller, session_config)
            .expect("signed exact-2.11 source should prepare");
        let capture_configs = configs
            .iter()
            .zip(&profiles)
            .map(|(config, profile)| {
                super::HvfArm64BootNetworkCaptureConfig::new(
                    config.clone(),
                    *profile,
                    None,
                    None,
                    false,
                )
            })
            .collect::<Vec<_>>();
        let capture_now = Instant::now();
        let guard = source
            .quiesce_limiter_retry_wakeups()
            .expect("network source publishers should quiesce");
        let captured = source
            .capture_ready_network_state_at(&capture_configs, &guard, capture_now)
            .expect("network source should capture");
        let serial = SnapshotV2SerialState::try_from_capture_ready(
            source
                .capture_ready_serial_state(controller.serial_config().clone(), &guard)
                .expect("network source serial should capture"),
        )
        .expect("network source serial should convert");
        drop(guard);
        let interfaces = captured
            .interfaces()
            .iter()
            .map(|captured| match captured.transport() {
                super::HvfArm64BootNetworkTransportCaptureState::Mmio {
                    region,
                    interrupt_line,
                    state,
                } if !pci_enabled => SnapshotV2NetworkInterfaceState::try_from_mmio_capture(
                    captured.config(),
                    SnapshotV2NetworkBackendClass::Vmnet,
                    *region,
                    *interrupt_line,
                    state,
                )
                .expect("portable MMIO network interface should convert"),
                super::HvfArm64BootNetworkTransportCaptureState::Pci {
                    origin,
                    sbdf,
                    bar_range,
                    state,
                } if pci_enabled => {
                    let origin = match origin {
                        super::HvfArm64BootNetworkDeviceOrigin::Startup => {
                            super::StorageDeviceOrigin::Startup
                        }
                        super::HvfArm64BootNetworkDeviceOrigin::Runtime => {
                            super::StorageDeviceOrigin::Runtime
                        }
                    };
                    SnapshotV2NetworkInterfaceState::try_from_pci_capture(
                        captured.config(),
                        SnapshotV2NetworkBackendClass::Vmnet,
                        origin,
                        *sbdf,
                        *bar_range,
                        state,
                    )
                    .expect("portable PCI network interface should convert")
                }
                _ => panic!("network source transport should match the test mode"),
            })
            .collect::<Vec<_>>();
        let network = SnapshotV2NetworkState::try_new(interfaces, None)
            .expect("portable network state should validate");
        let overrides = vec![SnapshotNetworkOverride::new("eth0", "vmnet:shared")];

        source
            .pause_for_snapshot_v2_capture()
            .expect("network source should pause");
        let boot = super::HvfSnapshotV2BootState::try_new(
            super::HvfSnapshotV2NativePath::try_new(kernel.path().as_os_str())
                .expect("network source kernel path should validate"),
            None,
            None,
        )
        .expect("network source boot state should validate");
        let mut memory_output = Cursor::new(Vec::new());
        let network_platform = source
            .capture_snapshot_v2_network_platform_with_cancel(
                super::HvfArm64BootSnapshotV2CaptureInput::new(boot),
                None,
                &mut memory_output,
                |_| false,
            )
            .expect("network source platform should capture");
        let encoded = super::encode_hvf_snapshot_v2_network_state(
            &super::HvfSnapshotV2NetworkState::try_new(
                network_platform.clone(),
                None,
                serial,
                None,
                None,
                Some(network),
            )
            .expect("network-only exact-2.11 product should compose"),
        )
        .expect("network-only exact-2.11 product should encode");
        let platform = network_platform.platform().clone();
        source
            .shutdown()
            .expect("signed exact-2.11 source should shut down");
        drop(source);
        let memory_image = TempFilePath::create_with_bytes(
            "signed-exact-2-11-process-network-memory",
            &memory_output.into_inner(),
        );

        if pci_enabled {
            let make_restore_inputs = || {
                let candidate = NativeV2NetworkSnapshotCandidateState::from_network_state_v2_11(
                    encoded.clone(),
                )
                .expect("exact-2.11 PCI candidate should decode");
                let prepared = match candidate
                    .prepare(&overrides)
                    .expect("exact-2.11 PCI destination topology should prepare")
                {
                    NativeV2NetworkSnapshotPreparation::Prepared(prepared) => prepared,
                    NativeV2NetworkSnapshotPreparation::Compatible(_) => {
                        panic!("PCI network-bearing candidate must not remain compatible")
                    }
                };
                let plan = prepare_process_snapshot_v2_network_restore_plan(
                    prepared,
                    ProcessVmnetAuthority::Direct,
                )
                .expect("exact-2.11 PCI process value plan should prepare");
                let (candidate, resource_plan) = plan.into_parts();
                let (
                    bytes,
                    binding,
                    storage,
                    serial,
                    entropy,
                    balloon,
                    memory_hotplug,
                    topology,
                    manifest,
                ) = candidate.into_parts();
                assert!(storage.is_none());
                assert!(entropy.is_none());
                assert!(balloon.is_none());
                assert!(memory_hotplug.is_none());
                assert_eq!(topology.interfaces().len(), 1);
                let platform_plan = prepare_hvf_snapshot_v2_network_pci_platform_plan(
                    &platform,
                    HvfSnapshotV2NetworkPreparedProduct::serial_network(binding, topology),
                )
                .expect("exact-2.11 PCI platform plan should prepare");
                let structural = decode_snapshot_v2_state_with_compatibility_version(
                    &encoded,
                    NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION,
                )
                .expect("exact-2.11 PCI state should decode structurally");
                let memory = load_snapshot_v2_memory_path(&structural, memory_image.path())
                    .expect("exact-2.11 PCI destination memory should map privately");
                let shell = super::HvfSnapshotV2RestoredSerialShell::new(
                    SerialMmioDevice::from_capture_state_with_shared_output(
                        SharedSerialOutput::from(SharedSerialOutputBuffer::default()),
                        serial.device().clone(),
                    ),
                );
                drop((bytes, serial, manifest));
                (memory, shell, platform_plan, resource_plan)
            };

            for (cancel_stage, expected_disposition) in [
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::ResourcePreparation,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::ResourceTake { index: 0 },
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::ProviderFinish,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::HvfConstruction,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::CompleteRecapture,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::Assembly,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2NetworkPciRestoreStage::GateCommit,
                    super::ProcessSnapshotV2NetworkPciRestoreDisposition::Terminal,
                ),
            ] {
                let (memory, shell, platform_plan, resource_plan) = make_restore_inputs();
                let mut factory = RecordingVmnetPacketIoBackendFactory::default()
                    .with_next_realized_mac(expected_mac)
                    .with_next_effective_mtu(1400);
                let events = factory.events();
                let error = super::restore_process_snapshot_v2_network_pci_with_factory(
                    platform.clone(),
                    super::HvfSnapshotV2NetworkPciMemoryInput::Static(memory),
                    shell,
                    None,
                    platform_plan,
                    resource_plan,
                    "exact-2-11-pci-cancelled-destination",
                    bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                    &mut factory,
                    Instant::now(),
                    |stage| stage == cancel_stage,
                )
                .expect_err("injected PCI process owner cancellation should reject");
                assert_eq!(error.stage, cancel_stage);
                assert_eq!(error.disposition, expected_disposition);
                let diagnostics = format!("{error:?} {error}");
                assert!(diagnostics.contains("<redacted>"));
                assert!(!diagnostics.contains("eth0"));
                assert!(!diagnostics.contains("vmnet:shared"));
                assert!(!diagnostics.contains("exact-2-11-pci-cancelled-destination"));
                let events = recorded_events(&events);
                if matches!(
                    cancel_stage,
                    super::ProcessSnapshotV2NetworkPciRestoreStage::ResourcePreparation
                ) {
                    assert!(events.is_empty());
                } else {
                    assert_eq!(
                        events
                            .iter()
                            .filter(|event| event.starts_with("start:"))
                            .count(),
                        1
                    );
                    assert_eq!(
                        events
                            .iter()
                            .filter(|event| event.starts_with("stop:"))
                            .count(),
                        1
                    );
                }
            }

            let (memory, shell, platform_plan, resource_plan) = make_restore_inputs();
            let mut factory = RecordingVmnetPacketIoBackendFactory::default()
                .with_next_realized_mac(expected_mac)
                .with_next_effective_mtu(1400);
            let events = factory.events();
            let mut owners = super::restore_process_snapshot_v2_network_pci_with_factory(
                platform,
                super::HvfSnapshotV2NetworkPciMemoryInput::Static(memory),
                shell,
                None,
                platform_plan,
                resource_plan,
                "exact-2-11-pci-committed-destination",
                bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                &mut factory,
                Instant::now(),
                |_| false,
            )
            .expect("complete PCI process/HVF owner graph should commit");
            assert_eq!(owners.resources.len(), 1);
            assert!(owners.completion.is_some());
            assert!(owners.hvf.as_ref().is_some_and(
                super::RestoredHvfSnapshotV2NetworkPciOwners::retry_publication_is_committed
            ));
            let diagnostics = format!("{owners:?}");
            assert!(diagnostics.contains("<redacted>"));
            assert!(!diagnostics.contains("eth0"));
            assert!(!diagnostics.contains("vmnet:shared"));
            assert_eq!(
                recorded_events(&events)
                    .iter()
                    .filter(|event| event.starts_with("stop:"))
                    .count(),
                0
            );
            owners
                .shutdown()
                .expect("committed PCI process/HVF owner graph should shut down");
            owners
                .shutdown()
                .expect("repeated PCI process/HVF shutdown should be idempotent");
            assert_eq!(
                recorded_events(&events)
                    .iter()
                    .filter(|event| event.starts_with("stop:"))
                    .count(),
                1
            );
            return;
        }

        let process = HvfSnapshotV2NetworkMmioProcessConfig::new(
            BalloonMmioLayout::new(DEFAULT_BALLOON_MMIO_BASE, DEFAULT_BALLOON_MMIO_REGION_ID),
            super::HvfSnapshotV2StorageMmioProcessConfig::new(
                BlockMmioLayout::new(DEFAULT_BLOCK_MMIO_BASE, DEFAULT_BLOCK_MMIO_REGION_ID),
                PmemMmioLayout::new(DEFAULT_PMEM_MMIO_BASE, DEFAULT_PMEM_MMIO_REGION_ID),
            ),
            NetworkMmioLayout::new(DEFAULT_NETWORK_MMIO_BASE, DEFAULT_NETWORK_MMIO_REGION_ID),
            EntropyMmioLayout::new(DEFAULT_ENTROPY_MMIO_BASE, DEFAULT_ENTROPY_MMIO_REGION_ID),
            VirtioMemMmioLayout::new(
                DEFAULT_MEMORY_HOTPLUG_MMIO_BASE,
                DEFAULT_MEMORY_HOTPLUG_MMIO_REGION_ID,
            ),
        );
        let make_restore_inputs = || {
            let candidate =
                NativeV2NetworkSnapshotCandidateState::from_network_state_v2_11(encoded.clone())
                    .expect("exact-2.11 candidate should decode");
            let prepared = match candidate
                .prepare(&overrides)
                .expect("exact-2.11 destination topology should prepare")
            {
                NativeV2NetworkSnapshotPreparation::Prepared(prepared) => prepared,
                NativeV2NetworkSnapshotPreparation::Compatible(_) => {
                    panic!("network-bearing candidate must not remain compatible")
                }
            };
            let plan = prepare_process_snapshot_v2_network_restore_plan(
                prepared,
                ProcessVmnetAuthority::Direct,
            )
            .expect("exact-2.11 process value plan should prepare");
            let (candidate, resource_plan) = plan.into_parts();
            let (
                bytes,
                binding,
                storage,
                serial,
                entropy,
                balloon,
                memory_hotplug,
                topology,
                manifest,
            ) = candidate.into_parts();
            assert!(storage.is_none());
            assert!(entropy.is_none());
            assert!(balloon.is_none());
            assert!(memory_hotplug.is_none());
            assert_eq!(topology.interfaces().len(), 1);
            let platform_plan = prepare_hvf_snapshot_v2_network_mmio_platform_plan(
                &platform,
                HvfSnapshotV2NetworkPreparedProduct::serial_network(binding, topology),
                process,
            )
            .expect("exact-2.11 MMIO platform plan should prepare");
            let structural = decode_snapshot_v2_state_with_compatibility_version(
                &encoded,
                NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION,
            )
            .expect("exact-2.11 state should decode structurally");
            let memory = load_snapshot_v2_memory_path(&structural, memory_image.path())
                .expect("exact-2.11 destination memory should map privately");
            let shell = super::HvfSnapshotV2RestoredSerialShell::new(
                SerialMmioDevice::from_capture_state_with_shared_output(
                    SharedSerialOutput::from(SharedSerialOutputBuffer::default()),
                    serial.device().clone(),
                ),
            );
            drop((bytes, serial, manifest));
            (memory, shell, platform_plan, resource_plan)
        };

        for (cancel_stage, expected_disposition) in [
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::ResourcePreparation,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::ResourceTake { index: 0 },
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::ProviderFinish,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::HvfConstruction,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::CompleteRecapture,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::Assembly,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2NetworkMmioRestoreStage::GateCommit,
                super::ProcessSnapshotV2NetworkMmioRestoreDisposition::Terminal,
            ),
        ] {
            let (memory, shell, platform_plan, resource_plan) = make_restore_inputs();
            let mut factory = RecordingVmnetPacketIoBackendFactory::default()
                .with_next_realized_mac(expected_mac)
                .with_next_effective_mtu(1400);
            let events = factory.events();
            let error = super::restore_process_snapshot_v2_network_mmio_with_factory(
                platform.clone(),
                super::HvfSnapshotV2NetworkMmioMemoryInput::Static(memory),
                shell,
                None,
                platform_plan,
                resource_plan,
                "exact-2-11-cancelled-destination",
                bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                &mut factory,
                Instant::now(),
                |stage| stage == cancel_stage,
            )
            .expect_err("injected process owner cancellation should reject");
            assert_eq!(error.stage, cancel_stage);
            assert_eq!(error.disposition, expected_disposition);
            let diagnostics = format!("{error:?} {error}");
            assert!(diagnostics.contains("<redacted>"));
            assert!(!diagnostics.contains("eth0"));
            assert!(!diagnostics.contains("vmnet:shared"));
            assert!(!diagnostics.contains("exact-2-11-cancelled-destination"));
            let events = recorded_events(&events);
            if matches!(
                cancel_stage,
                super::ProcessSnapshotV2NetworkMmioRestoreStage::ResourcePreparation
            ) {
                assert!(events.is_empty());
            } else {
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| event.starts_with("start:"))
                        .count(),
                    1
                );
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| event.starts_with("stop:"))
                        .count(),
                    1
                );
            }
        }

        let (memory, shell, platform_plan, resource_plan) = make_restore_inputs();
        let mut factory = RecordingVmnetPacketIoBackendFactory::default()
            .with_next_realized_mac(expected_mac)
            .with_next_effective_mtu(1400);
        let events = factory.events();
        let mut owners = super::restore_process_snapshot_v2_network_mmio_with_factory(
            platform,
            super::HvfSnapshotV2NetworkMmioMemoryInput::Static(memory),
            shell,
            None,
            platform_plan,
            resource_plan,
            "exact-2-11-committed-destination",
            bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
            &mut factory,
            Instant::now(),
            |_| false,
        )
        .expect("complete process/HVF owner graph should commit");
        assert_eq!(owners.resources.len(), 1);
        assert!(owners.completion.is_some());
        assert!(owners.hvf.as_ref().is_some_and(
            super::RestoredHvfSnapshotV2NetworkMmioOwners::retry_publication_is_committed
        ));
        let diagnostics = format!("{owners:?}");
        assert!(diagnostics.contains("<redacted>"));
        assert!(!diagnostics.contains("eth0"));
        assert!(!diagnostics.contains("vmnet:shared"));
        assert_eq!(
            recorded_events(&events)
                .iter()
                .filter(|event| event.starts_with("stop:"))
                .count(),
            0
        );
        owners
            .shutdown()
            .expect("committed process/HVF owner graph should shut down");
        owners
            .shutdown()
            .expect("repeated process/HVF shutdown should be idempotent");
        assert_eq!(
            recorded_events(&events)
                .iter()
                .filter(|event| event.starts_with("stop:"))
                .count(),
            1
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_exact_minor_eleven_process_mmio_owner_transaction_is_atomic_and_retryable() {
        verify_signed_exact_minor_eleven_process_network_owner_transaction(false);
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_exact_minor_eleven_process_pci_owner_transaction_is_atomic_and_retryable() {
        verify_signed_exact_minor_eleven_process_network_owner_transaction(true);
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn verify_signed_exact_minor_twelve_process_vsock_owner_transaction_is_atomic(
        pci_enabled: bool,
    ) {
        use bangbang_runtime::snapshot_memory_v2::load_snapshot_v2_memory_path;
        use bangbang_runtime::vsock::VsockBackendSelector;

        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel =
            TempFilePath::create_with_bytes("signed-exact-2-12-process-vsock-kernel", &image);
        let source_socket = TempFilePath::absent("signed-exact-2-12-source-vsock.sock");
        let destination_socket = TempFilePath::absent("signed-exact-2-12-destination-vsock.sock");

        let mut controller = VmmController::new("exact-2-12-process-source", "0.1.0", "bangbang");
        controller
            .handle_action(VmmAction::PutMachineConfig(
                MachineConfigInput::new(1, 16).with_track_dirty_pages(true),
            ))
            .expect("vsock source machine should configure");
        controller
            .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                kernel.path(),
            )))
            .expect("vsock source boot metadata should configure");
        controller
            .handle_action(VmmAction::PutVsock(VsockConfigInput::new(
                42,
                source_socket.path().to_string_lossy(),
            )))
            .expect("vsock source endpoint should configure");
        let source_config = controller
            .vsock_config()
            .cloned()
            .expect("vsock source config should exist");

        let session_config = default_hvf_boot_session_config(SharedSerialOutput::from(
            SharedSerialOutputBuffer::default(),
        ));
        let session_config = if pci_enabled {
            session_config.with_pci_enabled()
        } else {
            session_config
        };
        let mut source = super::OwnedHvfArm64BootSession::new(&controller, session_config)
            .expect("signed exact-2.12 source should prepare");
        assert!(source_socket.path().exists());
        let source_metrics = source.shared_vsock_device_metrics();
        let guard = source
            .quiesce_limiter_retry_wakeups()
            .expect("vsock source publishers should quiesce");
        let serial = SnapshotV2SerialState::try_from_capture_ready(
            source
                .capture_ready_serial_state(controller.serial_config().clone(), &guard)
                .expect("vsock source serial should capture"),
        )
        .expect("vsock source serial should convert");
        let expected_vsock = source
            .capture_ready_vsock_state(Some(source_config.clone()), &source_metrics, &guard)
            .expect("vsock source should capture")
            .expect("configured vsock source should remain present")
            .try_into_snapshot_v2()
            .expect("vsock source should convert to exact-2.12");
        let expected_destination_vsock = {
            let mut parts = expected_vsock.clone().into_parts();
            parts.backend_selector = VsockBackendSelector::try_from_path(destination_socket.path())
                .expect("vsock destination selector should validate");
            SnapshotV2VsockState::try_from_parts(parts)
                .expect("vsock destination-normalized state should validate")
        };
        drop(guard);

        source
            .pause_for_snapshot_v2_capture()
            .expect("vsock source should pause");
        let boot = super::HvfSnapshotV2BootState::try_new(
            super::HvfSnapshotV2NativePath::try_new(kernel.path().as_os_str())
                .expect("vsock source kernel path should validate"),
            None,
            None,
        )
        .expect("vsock source boot state should validate");
        let mut memory_output = Cursor::new(Vec::new());
        let vsock_platform = source
            .capture_snapshot_v2_vsock_platform_with_cancel(
                super::HvfArm64BootSnapshotV2CaptureInput::new(boot),
                None,
                &mut memory_output,
                |_| false,
            )
            .expect("vsock source platform should capture");
        let platform = vsock_platform.platform().clone();
        let encoded = super::encode_hvf_snapshot_v2_vsock_state(
            &super::HvfSnapshotV2VsockState::try_new(
                vsock_platform,
                None,
                serial,
                None,
                None,
                None,
                Some(expected_vsock.clone()),
            )
            .expect("vsock-only exact-2.12 product should compose"),
        )
        .expect("vsock-only exact-2.12 product should encode");
        source
            .shutdown()
            .expect("signed exact-2.12 source should shut down");
        drop(source);
        assert!(!source_socket.path().exists());
        let memory_image = TempFilePath::create_with_bytes(
            "signed-exact-2-12-process-vsock-memory",
            &memory_output.into_inner(),
        );

        let make_restore_inputs = || {
            let structural = decode_snapshot_v2_state_with_compatibility_version(
                &encoded,
                NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION,
            )
            .expect("exact-2.12 state should decode structurally");
            let memory = load_snapshot_v2_memory_path(&structural, memory_image.path())
                .expect("exact-2.12 destination memory should map privately");
            let candidate =
                NativeV2VsockSnapshotCandidateState::from_vsock_state_v2_12(encoded.clone())
                    .expect("exact-2.12 candidate should decode");
            let transport_kind = if pci_enabled {
                SnapshotV2DeviceTransportKind::Pci
            } else {
                SnapshotV2DeviceTransportKind::Mmio
            };
            let prepared = prepare_process_snapshot_v2_vsock_candidate(
                candidate,
                &memory,
                transport_kind,
                &[],
                Some(&SnapshotVsockOverride::new(destination_socket.path())),
            )
            .expect("exact-2.12 destination vsock should prepare");
            let resource_plan = super::prepare_process_snapshot_v2_vsock_resource_plan(
                prepared,
                ProcessVmnetAuthority::Direct,
            )
            .expect("exact-2.12 process resource plan should prepare");
            (memory, resource_plan)
        };

        if pci_enabled {
            for (cancel_stage, expected_disposition) in [
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::ResourcePreparation,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::ProductPreparation,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::HvfConstruction,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::Product,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::Platform,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Retryable,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::VsockPreparation,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::VsockPublication,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::RetryScheduler,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::RetryDeadline,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::Recapture,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Hvf(
                        super::HvfSnapshotV2VsockPciRestoreStage::Assembly,
                    ),
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::BatchFinish,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::CompleteRecapture,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::Assembly,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
                (
                    super::ProcessSnapshotV2VsockPciRestoreStage::GateCommit,
                    super::ProcessSnapshotV2VsockPciRestoreDisposition::Terminal,
                ),
            ] {
                let (memory, resource_plan) = make_restore_inputs();
                let mut factory = RecordingVmnetPacketIoBackendFactory::default();
                let events = factory.events();
                let error = super::restore_process_snapshot_v2_vsock_pci_with_factory(
                    platform.clone(),
                    memory,
                    resource_plan,
                    None,
                    "exact-2-12-pci-cancelled-destination",
                    bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                    &mut factory,
                    Instant::now(),
                    |stage| stage == cancel_stage,
                )
                .expect_err("injected exact-2.12 PCI owner cancellation should reject");
                assert_eq!(error.stage, cancel_stage);
                assert_eq!(error.disposition, expected_disposition);
                let diagnostics = format!("{error:?} {error}");
                assert!(diagnostics.contains("<redacted>"));
                assert!(
                    !diagnostics.contains(destination_socket.path().to_string_lossy().as_ref())
                );
                assert!(!diagnostics.contains("exact-2-12-pci-cancelled-destination"));
                assert!(!destination_socket.path().exists());
                assert!(recorded_events(&events).is_empty());
            }

            let (memory, resource_plan) = make_restore_inputs();
            let mut factory = RecordingVmnetPacketIoBackendFactory::default();
            let events = factory.events();
            let mut owners = super::restore_process_snapshot_v2_vsock_pci_with_factory(
                platform,
                memory,
                resource_plan,
                None,
                "exact-2-12-pci-committed-destination",
                bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                &mut factory,
                Instant::now(),
                |_| false,
            )
            .expect("complete exact-2.12 PCI process/HVF owner graph should commit");
            assert!(destination_socket.path().exists());
            assert!(owners.active_vsock.is_some());
            assert!(owners.completion.is_some());
            assert!(owners.network_resources.is_empty());
            let hvf = owners
                .hvf
                .as_ref()
                .expect("committed exact-2.12 PCI graph should retain HVF");
            assert!(hvf.retry_publication_is_committed());
            assert_eq!(hvf.expected_vsock(), Some(&expected_destination_vsock));
            let restored_config = hvf
                .vsock_config()
                .expect("committed exact-2.12 PCI graph should retain vsock config");
            assert_eq!(restored_config.guest_cid(), source_config.guest_cid());
            assert_eq!(restored_config.uds_path(), destination_socket.path());
            let destination_metrics = hvf
                .vsock_metrics()
                .expect("committed exact-2.12 PCI graph should retain fresh metrics");
            assert!(
                destination_metrics.shares_state_with(&hvf.session().shared_vsock_device_metrics())
            );
            assert!(!source_metrics.shares_state_with(destination_metrics));
            assert!(destination_metrics.snapshot().is_empty());
            assert!(source_metrics.snapshot().is_empty());
            assert_eq!(controller.vsock_config(), Some(&source_config));
            let diagnostics = format!("{owners:?}");
            assert!(diagnostics.contains("<redacted>"));
            assert!(!diagnostics.contains(destination_socket.path().to_string_lossy().as_ref()));
            assert!(!diagnostics.contains("exact-2-12-pci-committed-destination"));
            assert!(recorded_events(&events).is_empty());

            owners
                .shutdown()
                .expect("committed exact-2.12 PCI process/HVF owner graph should shut down");
            owners
                .shutdown()
                .expect("repeated exact-2.12 PCI process/HVF shutdown should be idempotent");
            assert!(!destination_socket.path().exists());
            return;
        }

        for (cancel_stage, expected_disposition) in [
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::ResourcePreparation,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::ProductPreparation,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::HvfConstruction,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::Product,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::InterruptSetup,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::Platform,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Retryable,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::Vsock,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::RetryScheduler,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::RetryDeadline,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::Recapture,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Hvf(
                    super::HvfSnapshotV2VsockMmioRestoreStage::Assembly,
                ),
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::BatchFinish,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::CompleteRecapture,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::Assembly,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
            (
                super::ProcessSnapshotV2VsockMmioRestoreStage::GateCommit,
                super::ProcessSnapshotV2VsockMmioRestoreDisposition::Terminal,
            ),
        ] {
            let (memory, resource_plan) = make_restore_inputs();
            let mut factory = RecordingVmnetPacketIoBackendFactory::default();
            let events = factory.events();
            let error = super::restore_process_snapshot_v2_vsock_mmio_with_factory(
                platform.clone(),
                memory,
                resource_plan,
                None,
                "exact-2-12-cancelled-destination",
                bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
                &mut factory,
                Instant::now(),
                |stage| stage == cancel_stage,
            )
            .expect_err("injected exact-2.12 owner cancellation should reject");
            assert_eq!(error.stage, cancel_stage);
            assert_eq!(error.disposition, expected_disposition);
            let diagnostics = format!("{error:?} {error}");
            assert!(diagnostics.contains("<redacted>"));
            assert!(!diagnostics.contains(destination_socket.path().to_string_lossy().as_ref()));
            assert!(!diagnostics.contains("exact-2-12-cancelled-destination"));
            assert!(!destination_socket.path().exists());
            assert!(recorded_events(&events).is_empty());
        }

        let (memory, resource_plan) = make_restore_inputs();
        let mut factory = RecordingVmnetPacketIoBackendFactory::default();
        let events = factory.events();
        let mut owners = super::restore_process_snapshot_v2_vsock_mmio_with_factory(
            platform,
            memory,
            resource_plan,
            None,
            "exact-2-12-committed-destination",
            bangbang_runtime::mmds::MMDS_DATA_STORE_LIMIT_BYTES,
            &mut factory,
            Instant::now(),
            |_| false,
        )
        .expect("complete exact-2.12 process/HVF owner graph should commit");
        assert!(destination_socket.path().exists());
        assert!(owners.active_vsock.is_some());
        assert!(owners.completion.is_some());
        assert!(owners.network_resources.is_empty());
        let hvf = owners
            .hvf
            .as_ref()
            .expect("committed exact-2.12 graph should retain HVF");
        assert!(hvf.retry_publication_is_committed());
        assert_eq!(hvf.expected_vsock(), Some(&expected_destination_vsock));
        let restored_config = hvf
            .vsock_config()
            .expect("committed exact-2.12 graph should retain vsock config");
        assert_eq!(restored_config.guest_cid(), source_config.guest_cid());
        assert_eq!(restored_config.uds_path(), destination_socket.path());
        let destination_metrics = hvf
            .vsock_metrics()
            .expect("committed exact-2.12 graph should retain fresh metrics");
        assert!(
            destination_metrics.shares_state_with(&hvf.session().shared_vsock_device_metrics())
        );
        assert!(!source_metrics.shares_state_with(destination_metrics));
        assert!(destination_metrics.snapshot().is_empty());
        assert!(source_metrics.snapshot().is_empty());
        assert_eq!(controller.vsock_config(), Some(&source_config));
        let diagnostics = format!("{owners:?}");
        assert!(diagnostics.contains("<redacted>"));
        assert!(!diagnostics.contains(destination_socket.path().to_string_lossy().as_ref()));
        assert!(!diagnostics.contains("exact-2-12-committed-destination"));
        assert!(recorded_events(&events).is_empty());

        owners
            .shutdown()
            .expect("committed exact-2.12 process/HVF owner graph should shut down");
        owners
            .shutdown()
            .expect("repeated exact-2.12 process/HVF shutdown should be idempotent");
        assert!(!destination_socket.path().exists());
    }

