    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v1_public_dispatch_restores_frozen_file_pair() {
        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel = TempFilePath::create_with_bytes("signed-native-v1-public-kernel", &image);
        let root = TempFilePath::create_with_bytes("signed-native-v1-public-root", &[0; 512]);

        let mut source = ProcessVmm::with_starter(
            "native-v1-public-source",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        );
        source
            .handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(1, 16)))
            .expect("native-v1 source machine should configure");
        source
            .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                kernel.path(),
            )))
            .expect("native-v1 source boot metadata should configure");
        source
            .handle_action(VmmAction::PutDrive(
                DriveConfigInput::new("root", "root", root.path(), true).with_is_read_only(true),
            ))
            .expect("native-v1 source root should configure");
        source
            .handle_action(VmmAction::InstanceStart)
            .expect("real native-v1 source should start");
        source
            .handle_action(VmmAction::Pause)
            .expect("real native-v1 source should pause");

        let directory = TempSnapshotDirectory::new("signed-native-v1-public");
        let paths = directory.paths();
        source
            .publish_native_v1_snapshot(&SnapshotCreateInput::new(
                SnapshotType::Full,
                paths.state(),
                paths.memory(),
            ))
            .expect("frozen native-v1 writer should publish");
        assert_eq!(
            load_native_snapshot_artifacts(&paths)
                .expect("native-v1 compatibility pair should validate")
                .family(),
            NativeSnapshotArtifactFamily::V1
        );
        drop(source);

        let mut destination = ProcessVmm::with_starter(
            "native-v1-public-destination",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        );
        assert_eq!(
            destination.handle_action(VmmAction::LoadSnapshot(SnapshotLoadInput::new(
                paths.state(),
                SnapshotMemoryBackend::new(paths.memory(), SnapshotMemoryBackendType::File,),
            ))),
            Ok(VmmData::Empty)
        );
        assert_eq!(destination.instance_info().state, InstanceState::Paused);
        assert_eq!(destination.drive_configs().len(), 1);
        assert_eq!(destination.drive_configs()[0].drive_id(), "root");
        destination
            .handle_action(VmmAction::Resume)
            .expect("legacy destination should resume through the ordinary lifecycle");
        destination
            .handle_action(VmmAction::Pause)
            .expect("legacy destination should remain controllable");
        directory.assert_no_staging();
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_process_publishes_recaptures_and_resumes_private_pair() {
        use bangbang_hvf::{HvfArm64StableVcpuDisposition, decode_hvf_snapshot_v2_vsock_state};
        use bangbang_runtime::snapshot_format_v2::decode_snapshot_v2_state;

        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;
        const STATE_REFERENCE: &str = "bangbang-grant:snapshot-state";
        const MEMORY_REFERENCE: &str = "bangbang-grant:snapshot-memory";
        const ROOT_REFERENCE: &str = "bangbang-grant:drive-ro";

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel = TempFilePath::create_with_bytes("signed-native-v2-process-kernel", &image);
        let root = TempFilePath::create_with_bytes("signed-native-v2-process-root", &[0_u8; 512]);

        let mut vmm = ProcessVmm::with_starter(
            "native-v2-process",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        )
        .with_grant_authority(Some(root_file_grant_authority_for_test(root.path())));
        vmm.handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(2, 16)))
            .expect("two-vCPU minimal machine should configure");
        vmm.handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
            kernel.path(),
        )))
        .expect("minimal guest image should configure");
        vmm.handle_action(VmmAction::PutDrive(
            DriveConfigInput::new("root", "root", ROOT_REFERENCE, true)
                .with_is_read_only(true)
                .with_io_engine(DriveIoEngine::Sync),
        ))
        .expect("native-v2 root should configure");
        vmm.handle_action(VmmAction::PutBalloon(
            BalloonConfigInput::new(4, true).with_stats_polling_interval_s(5),
        ))
        .expect("native-v2 balloon should configure");
        vmm.handle_action(VmmAction::InstanceStart)
            .expect("real native-v2 process source should start");
        vmm.handle_action(VmmAction::Pause)
            .expect("real native-v2 process source should pause");

        let first_directory = TempSnapshotDirectory::new("signed-native-v2-process-first");
        let first_paths = first_directory.paths();
        let first_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            first_paths.state(),
            first_paths.memory(),
        );
        assert_eq!(
            vmm.handle_action(VmmAction::CreateSnapshot(first_input)),
            Ok(VmmData::Empty)
        );
        let first = load_native_snapshot_artifacts(&first_paths)
            .expect("real process native-v2 pair should load");
        assert_eq!(first.family(), NativeSnapshotArtifactFamily::V2);
        let first_structural = decode_snapshot_v2_state(
            first
                .state()
                .v2_bytes()
                .expect("native-v2 load should retain structural bytes"),
        )
        .expect("real process native-v2 state should decode structurally");
        let first_state = decode_hvf_snapshot_v2_vsock_state(&first_structural)
            .expect("real process native-v2 current state should cross-validate");
        let first_platform = first_state.platform();
        assert_eq!(first_platform.topology().members().len(), 2);
        assert!(
            !first_platform.machine().machine().track_dirty_pages(),
            "Full publication must remain loadable without source dirty tracking",
        );
        assert!(matches!(
            first_platform.topology().members()[0].disposition(),
            HvfArm64StableVcpuDisposition::Runnable
        ));
        assert!(matches!(
            first_platform.topology().members()[1].disposition(),
            HvfArm64StableVcpuDisposition::Offline
        ));
        let first_graph = first_state
            .device_graph()
            .expect("real process native-v2 state should retain storage");
        assert_eq!(first_graph.block_records().len(), 1);
        assert!(first_graph.block_records()[0].is_root());
        assert!(first_graph.pmem_records().is_empty());
        assert_eq!(
            first_graph.transport_kind(),
            SnapshotV2DeviceTransportKind::Mmio
        );
        assert!(
            first_state
                .serial()
                .endpoint_intent()
                .is_default_process_stdio()
        );
        assert!(
            first_state.entropy().is_none(),
            "disabled entropy must remain absent from the current profile"
        );
        let first_balloon = first_state
            .balloon()
            .expect("configured balloon must remain present in the current profile");
        assert_eq!(
            first_balloon.transport().kind(),
            SnapshotV2DeviceTransportKind::Mmio
        );
        assert_eq!(first_balloon.config().stats_polling_interval_s(), 5);
        assert!(
            first_state.memory_hotplug().is_none(),
            "unconfigured virtio-mem must remain absent from the current profile"
        );
        drop(first_state);
        drop(first);
        first_directory.assert_no_staging();

        vmm.handle_action(VmmAction::Resume)
            .expect("published source should resume through the public process gate");
        vmm.handle_action(VmmAction::Pause)
            .expect("resumed source should enter a fresh outer pause");

        let second_directory = TempSnapshotDirectory::new("signed-native-v2-process-second");
        let second_paths = second_directory.paths();
        let second_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            second_paths.state(),
            second_paths.memory(),
        );
        assert_eq!(
            vmm.handle_action(VmmAction::CreateSnapshot(second_input)),
            Ok(VmmData::Empty)
        );
        let second = load_native_snapshot_artifacts(&second_paths)
            .expect("recaptured real process native-v2 pair should load");
        assert_eq!(second.family(), NativeSnapshotArtifactFamily::V2);
        assert_eq!(vmm.instance_info().state, InstanceState::Paused);
        second_directory.assert_no_staging();

        drop(vmm);

        let paused_load = SnapshotLoadInput::new(
            first_paths.state(),
            SnapshotMemoryBackend::new(first_paths.memory(), SnapshotMemoryBackendType::File),
        );
        let paused_restore = contained_restore_authority_for_test(root.path(), false);
        let paused_grants = paused_restore.grants().clone();
        let mut paused_destination = ProcessVmm::with_starter(
            "native-v2-paused-destination",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        )
        .with_grant_authority(Some(paused_grants))
        .with_contained_restore_authority(Some(paused_restore.into_authority()));
        assert_eq!(
            paused_destination.handle_action(VmmAction::LoadSnapshot(paused_load)),
            Ok(VmmData::Empty)
        );
        assert_eq!(
            paused_destination.instance_info().state,
            InstanceState::Paused
        );
        assert_eq!(paused_destination.drive_configs().len(), 1);
        assert_eq!(paused_destination.drive_configs()[0].drive_id(), "root");
        assert_eq!(
            paused_destination
                .controller
                .balloon_config()
                .expect("restored paused destination should publish balloon configuration")
                .stats_polling_interval_s(),
            5
        );
        assert_eq!(
            paused_destination.balloon_statistics_update_interval(),
            None
        );
        assert_eq!(
            paused_destination
                .starter
                .active_serial_output
                .as_ref()
                .expect("restored destination should retain its fresh UART output")
                .metrics(),
            SerialOutputMetrics::default()
        );
        paused_destination
            .handle_action(VmmAction::Resume)
            .expect("restored paused destination should resume");
        assert_eq!(
            paused_destination.balloon_statistics_update_interval(),
            Some(Duration::from_secs(5))
        );
        paused_destination
            .handle_action(VmmAction::Pause)
            .expect("restored destination should pause again");

        let recaptured_directory =
            TempSnapshotDirectory::new("signed-native-v2-restored-recapture");
        let recaptured_paths = recaptured_directory.paths();
        assert_eq!(
            paused_destination.handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                SnapshotType::Full,
                recaptured_paths.state(),
                recaptured_paths.memory(),
            ),)),
            Ok(VmmData::Empty)
        );
        let recaptured = load_native_snapshot_artifacts(&recaptured_paths)
            .expect("restored destination should publish exact-2.12 Full state");
        assert_eq!(
            recaptured
                .state()
                .v2_profile()
                .expect("recaptured destination should retain a closed profile"),
            NativeV2SnapshotArtifactProfile::VsockStateV2_12
        );
        recaptured_directory.assert_no_staging();
        drop(paused_destination);

        let authority = snapshot_root_file_grant_authority_for_test(
            first_paths.state(),
            first_paths.memory(),
            root.path(),
        );
        let resumed_restore =
            contained_restore_authority_with_grants_for_test(authority.clone(), false);
        let replacement_state = first_paths
            .state()
            .with_file_name("contained-replacement.state");
        let replacement_memory = first_paths
            .memory()
            .with_file_name("contained-replacement.memory");
        fs::write(&replacement_state, b"replacement state")
            .expect("contained replacement state should write");
        fs::write(&replacement_memory, b"replacement memory")
            .expect("contained replacement memory should write");
        fs::rename(&replacement_state, first_paths.state())
            .expect("contained replacement state should replace the path");
        fs::rename(&replacement_memory, first_paths.memory())
            .expect("contained replacement memory should replace the path");

        let resumed_load = SnapshotLoadInput::new(
            STATE_REFERENCE,
            SnapshotMemoryBackend::new(MEMORY_REFERENCE, SnapshotMemoryBackendType::File),
        )
        .with_resume_vm(true);
        let mut resumed_destination = ProcessVmm::with_starter(
            "native-v2-resumed-destination",
            "0.1.0",
            "bangbang",
            HvfInstanceStartExecutor::default(),
        )
        .with_grant_authority(Some(authority))
        .with_contained_restore_authority(Some(resumed_restore.into_authority()));
        assert_eq!(
            resumed_destination.handle_action(VmmAction::LoadSnapshot(resumed_load)),
            Ok(VmmData::Empty)
        );
        assert_eq!(
            resumed_destination.instance_info().state,
            InstanceState::Running
        );
        assert_eq!(
            resumed_destination.balloon_statistics_update_interval(),
            Some(Duration::from_secs(5))
        );
        resumed_destination
            .handle_action(VmmAction::Pause)
            .expect("resumed destination should remain controllable");
        drop(resumed_destination);
        assert_eq!(
            fs::read(first_paths.state()).expect("contained replacement state should remain"),
            b"replacement state"
        );
        assert_eq!(
            fs::read(first_paths.memory()).expect("contained replacement memory should remain"),
            b"replacement memory"
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_diff_process_loads_zero_root_and_rebased_products() {
        use bangbang_hvf::decode_hvf_snapshot_v2_diff_state;

        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;
        const STATE_REFERENCE: &str = "bangbang-grant:snapshot-state";
        const MEMORY_REFERENCE: &str = "bangbang-grant:snapshot-memory";
        const ROOT_REFERENCE: &str = "bangbang-grant:drive-ro";
        const DEPRECATION_NOTICE: &str = "This tool is deprecated and will be removed in the future. Please use 'snapshot-editor' instead.\n";

        let rebase_snap = PathBuf::from(
            std::env::var_os("BANGBANG_REBASE_SNAP_PATH")
                .expect("signed native-v2 process group should provide rebase-snap"),
        );
        let snapshot_editor = PathBuf::from(
            std::env::var_os("BANGBANG_SNAPSHOT_EDITOR_PATH")
                .expect("signed native-v2 process group should provide snapshot-editor"),
        );

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel = TempFilePath::create_with_bytes("signed-native-v2-diff-kernel", &image);

        for (case, pci_enabled, tracked, full_first, contained) in [
            ("mmio-zero-root", false, true, false, false),
            ("mmio-untracked-zero-root", false, false, false, false),
            ("pci-rebased", true, false, true, true),
        ] {
            let root = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-diff-{case}-root"),
                &[0_u8; 512],
            );
            let mut source = ProcessVmm::with_starter(
                format!("native-v2-diff-{case}-source"),
                "0.1.0",
                "bangbang",
                HvfInstanceStartExecutor::default(),
            );
            if contained {
                source = source
                    .with_grant_authority(Some(root_file_grant_authority_for_test(root.path())));
            }
            source.pci_enabled = pci_enabled;
            source.starter.pci_enabled = pci_enabled;
            source
                .handle_action(VmmAction::PutMachineConfig(
                    MachineConfigInput::new(1, 16).with_track_dirty_pages(tracked),
                ))
                .unwrap_or_else(|error| panic!("{case} machine should configure: {error}"));
            source
                .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                    kernel.path(),
                )))
                .unwrap_or_else(|error| panic!("{case} boot source should configure: {error}"));
            let root_selector = if contained {
                Path::new(ROOT_REFERENCE)
            } else {
                root.path()
            };
            source
                .handle_action(VmmAction::PutDrive(
                    DriveConfigInput::new("root", "root", root_selector, true)
                        .with_is_read_only(true)
                        .with_io_engine(DriveIoEngine::Sync),
                ))
                .unwrap_or_else(|error| panic!("{case} root should configure: {error}"));
            source
                .handle_action(VmmAction::PutBalloon(BalloonConfigInput::new(4, false)))
                .unwrap_or_else(|error| panic!("{case} balloon should configure: {error}"));
            source
                .handle_action(VmmAction::InstanceStart)
                .unwrap_or_else(|error| panic!("{case} source should start: {error}"));
            source
                .handle_action(VmmAction::Pause)
                .unwrap_or_else(|error| panic!("{case} source should pause: {error}"));

            let full = full_first.then(|| {
                let directory = TempSnapshotDirectory::new(&format!("{case}-full"));
                let paths = directory.paths();
                source
                    .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                        SnapshotType::Full,
                        paths.state(),
                        paths.memory(),
                    )))
                    .unwrap_or_else(|error| panic!("{case} Full should publish: {error}"));
                let loaded =
                    load_native_snapshot_artifacts(&paths).expect("signed Full pair should load");
                assert_eq!(
                    loaded
                        .state()
                        .v2_profile()
                        .expect("signed Full profile should classify"),
                    NativeV2SnapshotArtifactProfile::VsockStateV2_12
                );
                let binding = loaded
                    .state()
                    .v2_memory_binding()
                    .expect("signed Full should retain its binding")
                    .clone();
                directory.assert_no_staging();
                (directory, paths, binding)
            });

            let diff_directory = TempSnapshotDirectory::new(&format!("{case}-diff"));
            let diff_paths = diff_directory.paths();
            source
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Diff,
                    diff_paths.state(),
                    diff_paths.memory(),
                )))
                .unwrap_or_else(|error| panic!("{case} Diff should publish: {error}"));
            let state_bytes =
                fs::read(diff_paths.state()).expect("signed Diff state should remain readable");
            let structural = decode_snapshot_v2_state_with_compatibility_version(
                &state_bytes,
                NATIVE_V2_DIFF_STATE_COMPATIBILITY_VERSION,
            )
            .expect("signed Diff state should decode structurally");
            let decoded = decode_hvf_snapshot_v2_diff_state(&structural)
                .expect("signed Diff state should close semantically");
            assert!(decoded.balloon().is_some());
            assert_eq!(
                decoded
                    .device_graph()
                    .expect("signed Diff should retain its root")
                    .transport_kind(),
                if pci_enabled {
                    SnapshotV2DeviceTransportKind::Pci
                } else {
                    SnapshotV2DeviceTransportKind::Mmio
                }
            );
            let layer = decoded.layer().clone();
            let result_binding = layer.result().clone();
            let selected_bytes = layer
                .data_extents()
                .iter()
                .map(|extent| extent.range().size())
                .sum::<u64>();
            let result_bytes = result_binding
                .extents()
                .iter()
                .map(|extent| extent.range().size())
                .sum::<u64>();
            if tracked {
                assert!(matches!(layer.base(), SnapshotV2DiffBase::Zero));
                assert!(
                    selected_bytes < result_bytes,
                    "tracked boot Diff should select only guest-dirty pages"
                );
            } else {
                assert_eq!(selected_bytes, result_bytes);
                if full_first {
                    assert!(matches!(layer.base(), SnapshotV2DiffBase::Image(_)));
                    assert_eq!(
                        layer
                            .base()
                            .binding()
                            .expect("Full-following Diff should name its predecessor"),
                        &full
                            .as_ref()
                            .expect("Full-following case should retain its base")
                            .2
                    );
                } else {
                    assert!(matches!(layer.base(), SnapshotV2DiffBase::Zero));
                }
            }
            drop(decoded);
            drop(source);

            let memory_path = if let Some((full_directory, full_paths, _)) = &full {
                let deprecated_memory = full_paths
                    .memory()
                    .with_file_name(format!("{case}-deprecated-rebased.memory"));
                let replacement_memory = full_paths
                    .memory()
                    .with_file_name(format!("{case}-replacement-rebased.memory"));
                fs::copy(full_paths.memory(), &deprecated_memory)
                    .expect("captured Full should copy for rebase-snap");
                fs::copy(full_paths.memory(), &replacement_memory)
                    .expect("captured Full should copy for snapshot-editor");
                let diff_before =
                    fs::read(diff_paths.memory()).expect("captured Diff memory should read");

                let deprecated = Command::new(&rebase_snap)
                    .arg("--base-file")
                    .arg(&deprecated_memory)
                    .arg("--diff-file")
                    .arg(diff_paths.memory())
                    .output()
                    .expect("signed rebase-snap should start");
                assert!(
                    deprecated.status.success(),
                    "{case} rebase-snap should succeed: {}",
                    String::from_utf8_lossy(&deprecated.stderr)
                );
                assert_eq!(
                    String::from_utf8(deprecated.stdout)
                        .expect("rebase-snap output should be UTF-8"),
                    DEPRECATION_NOTICE
                );
                assert!(deprecated.stderr.is_empty());

                let replacement = Command::new(&snapshot_editor)
                    .args(["edit-memory", "rebase"])
                    .arg("--memory-path")
                    .arg(&replacement_memory)
                    .arg("--diff-path")
                    .arg(diff_paths.memory())
                    .output()
                    .expect("signed snapshot-editor should start");
                assert!(
                    replacement.status.success(),
                    "{case} snapshot-editor should succeed: {}",
                    String::from_utf8_lossy(&replacement.stderr)
                );
                assert!(replacement.stdout.is_empty());
                assert!(replacement.stderr.is_empty());

                assert_eq!(
                    fs::read(&deprecated_memory).expect("rebase-snap complete result should read"),
                    fs::read(&replacement_memory)
                        .expect("snapshot-editor complete result should read")
                );
                assert_eq!(
                    fs::read(diff_paths.memory()).expect("captured Diff should remain readable"),
                    diff_before
                );
                for tool_memory in [&deprecated_memory, &replacement_memory] {
                    let tool_paths =
                        SnapshotArtifactPaths::new(diff_paths.state(), tool_memory.clone());
                    let loaded = load_native_snapshot_artifacts(&tool_paths)
                        .unwrap_or_else(|error| panic!("{case} tool result should load: {error}"));
                    assert_eq!(
                        loaded
                            .state()
                            .v2_memory_binding()
                            .expect("tool result state should retain its memory binding"),
                        &result_binding
                    );
                }
                full_directory.assert_no_staging();
                replacement_memory
            } else {
                diff_paths.memory().to_path_buf()
            };
            let closed_paths = SnapshotArtifactPaths::new(diff_paths.state(), memory_path.clone());
            load_native_snapshot_artifacts(&closed_paths)
                .unwrap_or_else(|error| panic!("{case} closed Diff pair should load: {error}"));

            let mut load = SnapshotLoadInput::new(
                diff_paths.state(),
                SnapshotMemoryBackend::new(memory_path.clone(), SnapshotMemoryBackendType::File),
            )
            .with_track_dirty_pages(tracked);
            let mut destination = ProcessVmm::with_starter(
                format!("native-v2-diff-{case}-destination"),
                "0.1.0",
                "bangbang",
                HvfInstanceStartExecutor::default(),
            );
            if contained {
                let authority = snapshot_root_file_grant_authority_for_test(
                    diff_paths.state(),
                    &memory_path,
                    root.path(),
                );
                let restore =
                    contained_restore_authority_with_grants_for_test(authority.clone(), false);
                destination = destination
                    .with_grant_authority(Some(authority))
                    .with_contained_restore_authority(Some(restore.into_authority()));
                load = SnapshotLoadInput::new(
                    STATE_REFERENCE,
                    SnapshotMemoryBackend::new(MEMORY_REFERENCE, SnapshotMemoryBackendType::File),
                )
                .with_track_dirty_pages(tracked);
            }
            destination.pci_enabled = pci_enabled;
            destination.starter.pci_enabled = pci_enabled;
            destination
                .handle_action(VmmAction::LoadSnapshot(load))
                .unwrap_or_else(|error| panic!("{case} destination should load: {error}"));
            assert_eq!(destination.instance_info().state, InstanceState::Paused);
            assert_eq!(destination.drive_configs().len(), 1);
            assert!(destination.controller.balloon_config().is_some());

            let recapture_directory = TempSnapshotDirectory::new(&format!("{case}-recapture"));
            let recapture_paths = recapture_directory.paths();
            destination
                .handle_action(VmmAction::CreateSnapshot(SnapshotCreateInput::new(
                    SnapshotType::Diff,
                    recapture_paths.state(),
                    recapture_paths.memory(),
                )))
                .unwrap_or_else(|error| panic!("{case} destination should recapture: {error}"));
            let recaptured = NativeV2DiffSnapshotCandidateState::from_committed_diff_state_v2_13(
                fs::read(recapture_paths.state()).expect("recaptured exact-2.13 state should read"),
            )
            .expect("recaptured exact-2.13 state should close");
            assert_eq!(
                recaptured
                    .layer_binding()
                    .base()
                    .binding()
                    .expect("restored recapture should name its loaded predecessor"),
                &result_binding
            );
            recapture_directory.assert_no_staging();
            diff_directory.assert_no_staging();
            drop(destination);
        }
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_root_process_commits_complete_mmio_and_pci_owners_atomically() {
        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;
        const ROOT_REFERENCE: &str = "bangbang-grant:drive-ro";

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());
        let kernel = TempFilePath::create_with_bytes("signed-native-v2-root-kernel", &image);

        for (case, pci_enabled) in [("mmio", false), ("pci", true)] {
            let root = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-{case}-root"),
                &vec![0_u8; 1024 * 1024],
            );
            let mut source = ProcessVmm::with_starter(
                format!("native-v2-{case}-source"),
                "0.1.0",
                "bangbang",
                HvfInstanceStartExecutor::default(),
            )
            .with_grant_authority(Some(root_file_grant_authority_for_test(root.path())));
            source.pci_enabled = pci_enabled;
            source.starter.pci_enabled = pci_enabled;
            source
                .handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(2, 16)))
                .expect("root source machine should configure");
            source
                .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                    kernel.path(),
                )))
                .expect("root source boot metadata should configure");
            source
                .handle_action(VmmAction::PutDrive(
                    DriveConfigInput::new("rootfs", "rootfs", ROOT_REFERENCE, true)
                        .with_is_read_only(true)
                        .with_io_engine(DriveIoEngine::Sync)
                        .with_partuuid("1111-2222"),
                ))
                .expect("root source drive should configure");
            source
                .handle_action(VmmAction::InstanceStart)
                .expect("root source should start");
            source
                .handle_action(VmmAction::Pause)
                .expect("root source should pause");

            let events = Arc::new(Mutex::new(Vec::new()));
            let (output, memory_bytes) = SharedSnapshotMemoryOutput::new(events);
            let candidate = source
                .capture_native_v2_root_candidate(
                    Box::new(output),
                    NativeV2SnapshotCaptureCancellation::default(),
                )
                .unwrap_or_else(|error| panic!("{case} root candidate should capture: {error}"));
            let candidate_bytes = candidate.bytes().to_vec();
            let expected_graph = candidate.device_graph().clone();
            let memory_image = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-{case}-memory"),
                memory_bytes
                    .lock()
                    .expect("captured root memory should lock")
                    .get_ref(),
            );
            drop(source);

            let load_memory = || {
                let structural = decode_snapshot_v2_state_with_compatibility_version(
                    &candidate_bytes,
                    NATIVE_V2_DEVICE_GRAPH_COMPATIBILITY_VERSION,
                )
                .expect("root candidate state should decode");
                bangbang_runtime::snapshot_memory_v2::load_snapshot_v2_memory_path(
                    &structural,
                    memory_image.path(),
                )
                .expect("root candidate memory should load")
            };
            let input = SnapshotLoadInput::new(
                "private-native-v2-root.state",
                SnapshotMemoryBackend::new(memory_image.path(), SnapshotMemoryBackendType::File),
            );

            if !pci_enabled {
                let failed_authority = root_file_grant_authority_for_test(root.path());
                let failed_observer = failed_authority.clone();
                let failed_restore = contained_restore_authority_with_grants_for_test(
                    failed_authority.clone(),
                    false,
                );
                let mut failed = ProcessVmm::with_starter(
                    "native-v2-mmio-controller-checkpoint",
                    "0.1.0",
                    "bangbang",
                    HvfInstanceStartExecutor::default(),
                )
                .with_grant_authority(Some(failed_authority))
                .with_contained_restore_authority(Some(failed_restore.into_authority()));
                let error = failed
                    .restore_native_v2_root_candidate_once_with_controller_hook(
                        &input,
                        NativeV2SnapshotCandidateState::from_device_graph_v2_4(
                            candidate_bytes.clone(),
                        )
                        .expect("checkpoint candidate should validate"),
                        load_memory(),
                        || {
                            Err(BackendError::InvalidState(
                                "injected pre-controller checkpoint",
                            ))
                        },
                    )
                    .expect_err("controller checkpoint should fail before publication");
                assert!(matches!(
                    &error,
                    NativeV2SnapshotLoadError::ControllerCommit(_)
                ));
                assert!(!error.is_terminal());
                assert!(!failed.has_started_session());
                assert!(failed.starter.active_serial_output.is_none());
                assert_eq!(failed.instance_info().state, InstanceState::NotStarted);
                assert!(failed.drive_configs().is_empty());
                let restored_claim = failed_observer
                    .prepare_drive_backing_claim(Path::new(ROOT_REFERENCE), GrantAccess::ReadOnly)
                    .expect("failed controller checkpoint should restore the root grant")
                    .expect("restored root grant should be claimable");
                restored_claim
                    .abort()
                    .expect("observed checkpoint claim should restore for the retry");
                assert!(
                    !failed
                        .restore_native_v2_root_candidate_once(
                            &input,
                            NativeV2SnapshotCandidateState::from_device_graph_v2_4(
                                candidate_bytes.clone(),
                            )
                            .expect("checkpoint retry candidate should validate"),
                            load_memory(),
                        )
                        .expect("clean controller checkpoint should remain retryable")
                );
                assert_eq!(failed.instance_info().state, InstanceState::Paused);
                assert!(failed.has_started_session());
                assert!(failed.starter.active_serial_output.is_some());
                assert_eq!(failed.drive_configs().len(), 1);
                assert!(
                    failed_observer
                        .prepare_drive_backing_claim(
                            Path::new(ROOT_REFERENCE),
                            GrantAccess::ReadOnly,
                        )
                        .is_err(),
                    "successful retry must consume the restored root claim"
                );
                drop(failed);
            }

            let authority = root_file_grant_authority_for_test(root.path());
            let observer = authority.clone();
            let restore =
                contained_restore_authority_with_grants_for_test(authority.clone(), false);
            let mut destination = ProcessVmm::with_starter(
                format!("native-v2-{case}-destination"),
                "0.1.0",
                "bangbang",
                HvfInstanceStartExecutor::default(),
            )
            .with_grant_authority(Some(authority))
            .with_contained_restore_authority(Some(restore.into_authority()));
            destination.pci_enabled = pci_enabled;
            destination.starter.pci_enabled = pci_enabled;
            assert!(
                !destination
                    .restore_native_v2_root_candidate_once(
                        &input,
                        NativeV2SnapshotCandidateState::from_device_graph_v2_4(
                            candidate_bytes.clone(),
                        )
                        .expect("destination candidate should validate"),
                        load_memory(),
                    )
                    .unwrap_or_else(|error| panic!("{case} root destination should load: {error}"))
            );
            assert_eq!(destination.instance_info().state, InstanceState::Paused);
            assert!(destination.starter.active_serial_output.is_some());
            assert_eq!(destination.drive_configs().len(), 1);
            assert_eq!(destination.drive_configs()[0].drive_id(), "rootfs");
            assert_eq!(
                destination.drive_configs()[0].path_on_host(),
                Some(Path::new(ROOT_REFERENCE))
            );
            assert!(matches!(
                destination.started_session.as_ref(),
                Some(HvfProcessSession::Boot(_))
            ));
            assert!(
                observer
                    .prepare_drive_backing_claim(Path::new(ROOT_REFERENCE), GrantAccess::ReadOnly,)
                    .is_err(),
                "successful controller publication must consume the root claim"
            );

            let recapture_events = Arc::new(Mutex::new(Vec::new()));
            let (recapture_output, _recapture_bytes) =
                SharedSnapshotMemoryOutput::new(recapture_events);
            let recaptured = destination
                .capture_native_v2_root_candidate(
                    Box::new(recapture_output),
                    NativeV2SnapshotCaptureCancellation::default(),
                )
                .unwrap_or_else(|error| {
                    panic!("{case} root destination should recapture: {error}")
                });
            assert_eq!(recaptured.device_graph(), &expected_graph);
            assert_eq!(destination.instance_info().state, InstanceState::Paused);
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn exact_v2_serial_commit_classifies_missing_projection_as_terminal() {
        let is_terminal = |source: super::PreparedHvfSnapshotV2SerialControllerError| {
            super::PrepareHvfSnapshotV2SerialDestinationError::Commit(
                super::PreparedSnapshotV2SerialDestinationCommitError::Controller {
                    source,
                    destination_cleanup: None,
                    completion_abort: None,
                },
            )
            .is_terminal()
        };

        assert!(is_terminal(
            super::PreparedHvfSnapshotV2SerialControllerError::MissingSerialConfig
        ));
        assert!(is_terminal(
            super::PreparedHvfSnapshotV2SerialControllerError::MissingStorageConfigs
        ));
        assert!(!is_terminal(
            super::PreparedHvfSnapshotV2SerialControllerError::Cancelled
        ));
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_storage_destination_stays_private_and_paused_through_commit() {
        use bangbang_runtime::pmem::VIRTIO_PMEM_ALIGNMENT;

        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());

        for (case, pci_enabled) in [("mmio", false), ("pci", true)] {
            let kernel = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-storage-{case}-kernel"),
                &image,
            );
            let root = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-storage-{case}-root"),
                &[0_u8; 4096],
            );
            let pmem = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-storage-{case}-pmem"),
                &vec![
                    0_u8;
                    usize::try_from(VIRTIO_PMEM_ALIGNMENT)
                        .expect("pmem alignment should fit usize")
                ],
            );

            let mut source_controller = VmmController::new(
                format!("native-v2-storage-{case}-source"),
                "0.1.0",
                "bangbang",
            );
            source_controller
                .handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(1, 16)))
                .expect("storage source machine should configure");
            source_controller
                .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                    kernel.path(),
                )))
                .expect("storage source boot metadata should configure");
            source_controller
                .handle_action(VmmAction::PutDrive(
                    DriveConfigInput::new("rootfs", "rootfs", root.path(), true)
                        .with_is_read_only(true)
                        .with_io_engine(DriveIoEngine::Sync),
                ))
                .expect("storage source block root should configure");
            source_controller
                .handle_action(VmmAction::PutPmem(PmemConfigInput::new(
                    "pmem0",
                    pmem.path().to_string_lossy().into_owned(),
                )))
                .expect("storage source pmem should configure");

            let source_serial = SharedSerialOutput::from(SharedSerialOutputBuffer::default());
            let mut source_config = default_hvf_boot_session_config(source_serial);
            if pci_enabled {
                source_config = source_config.with_pci_enabled();
            }
            let mut source_session =
                super::OwnedHvfArm64BootSession::new(&source_controller, source_config)
                    .expect("signed exact-2.6 source should prepare");
            let expected_configs = CaptureReadyStorageConfigs::new(
                source_controller.drive_configs().to_vec(),
                source_controller.pmem_configs().to_vec(),
            );
            let capture_now = Instant::now();
            let capture_guard = source_session
                .quiesce_limiter_retry_wakeups()
                .expect("storage source retry publishers should quiesce");
            let graph = source_session
                .capture_snapshot_v2_storage_device_graph_at(
                    &expected_configs,
                    &capture_guard,
                    capture_now,
                )
                .expect("signed exact-2.6 storage graph should capture");

            let restored_layout =
                GuestMemoryLayout::new(source_session.runtime_resources().layout.ranges().to_vec())
                    .expect("storage destination layout should validate");
            let copy_source_memory = || {
                let mut destination = GuestMemory::allocate(&restored_layout)
                    .expect("storage destination memory should allocate");
                let source = source_session
                    .guest_memory()
                    .expect("storage source memory should remain mapped");
                let mut buffer = vec![0_u8; 64 * 1024];
                for range in restored_layout.ranges() {
                    let mut copied = 0_u64;
                    while copied < range.size() {
                        let count = usize::try_from(
                            (range.size() - copied).min(
                                u64::try_from(buffer.len())
                                    .expect("storage copy buffer length should fit u64"),
                            ),
                        )
                        .expect("storage memory copy length should fit usize");
                        let address = range
                            .start()
                            .checked_add(copied)
                            .expect("storage memory copy address should fit");
                        source
                            .read_slice(&mut buffer[..count], address)
                            .expect("storage source memory should read");
                        destination
                            .write_slice(&buffer[..count], address)
                            .expect("storage destination memory should write");
                        copied += u64::try_from(count).expect("storage copy length should fit u64");
                    }
                }
                destination
            };
            let cancelled_memory = copy_source_memory();
            let committed_memory = copy_source_memory();

            source_session
                .pause_for_snapshot_v2_capture()
                .expect("storage source topology should pause");
            let boot_state = HvfSnapshotV2BootState::try_new(
                HvfSnapshotV2NativePath::try_new(kernel.path().as_os_str())
                    .expect("storage source kernel path should validate"),
                None,
                None,
            )
            .expect("storage source boot state should validate");
            let mut memory_output = Cursor::new(Vec::new());
            let platform = source_session
                .capture_snapshot_v2_storage_platform_with_cancel(
                    HvfArm64BootSnapshotV2CaptureInput::new(boot_state),
                    &mut memory_output,
                    |_| false,
                )
                .expect("signed exact-2.6 storage platform should capture");
            drop(capture_guard);
            source_session
                .shutdown()
                .expect("storage source should shut down");

            let machine = snapshot_destination_machine_config(platform.machine().machine(), false);
            let boot = super::native_v2_boot_source_config(platform.machine().boot())
                .expect("storage destination boot projection should validate");
            let process = bangbang_hvf::HvfSnapshotV2StorageMmioProcessConfig::new(
                BlockMmioLayout::new(DEFAULT_BLOCK_MMIO_BASE, DEFAULT_BLOCK_MMIO_REGION_ID),
                PmemMmioLayout::new(DEFAULT_PMEM_MMIO_BASE, DEFAULT_PMEM_MMIO_REGION_ID),
            );

            let cancelled_bundle =
                super::RequestedSnapshotRestoreResources::prepare_native_v2_storage_restore_bundle(
                    graph.clone(),
                    &cancelled_memory,
                    Instant::now(),
                    None,
                    || false,
                )
                .expect("cancelled storage bundle should prepare");
            let cancelled_serial = SharedSerialOutput::from(SharedSerialOutputBuffer::default());
            let cancelled_shell =
                super::HvfSnapshotV2DefaultProcessShell::new(cancelled_serial.clone());
            let (cancelled_packet_io, cancelled_mmds_metrics) =
                ProcessNetworkPacketIoProvider::from_controller(
                    &source_controller,
                    ProcessVmnetAuthority::Direct,
                )
                .expect("cancelled storage packet I/O should prepare");
            let cancellation = NativeV2SnapshotCaptureCancellation::default();
            cancellation.cancel();
            if pci_enabled {
                let cancelled_plan =
                    bangbang_hvf::prepare_hvf_snapshot_v2_storage_pci_platform_plan(
                        &platform,
                        cancelled_bundle
                            .bundle()
                            .expect("cancelled PCI storage bundle owner should remain present"),
                    )
                    .expect("cancelled PCI storage platform plan should prepare");
                let cancelled = super::prepare_hvf_native_v2_storage_pci_destination(
                    super::PrepareHvfSnapshotV2StoragePciDestinationInput {
                        platform: platform.clone(),
                        memory: cancelled_memory,
                        process_shell: cancelled_shell,
                        packet_io: cancelled_packet_io,
                        mmds_metrics: cancelled_mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        serial_output: cancelled_serial,
                        bundle: cancelled_bundle,
                        plan: cancelled_plan,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation,
                    },
                )
                .expect_err("cancellation should prevent private PCI storage commit");
                assert!(!cancelled.is_terminal());
                assert!(matches!(
                    cancelled,
                    super::PrepareHvfSnapshotV2StorageDestinationError::Commit(_)
                ));
            } else {
                let cancelled_plan =
                    bangbang_hvf::prepare_hvf_snapshot_v2_storage_mmio_platform_plan(
                        &platform,
                        cancelled_bundle
                            .bundle()
                            .expect("cancelled MMIO storage bundle owner should remain present"),
                        process,
                    )
                    .expect("cancelled MMIO storage platform plan should prepare");
                let cancelled = super::prepare_hvf_native_v2_storage_mmio_destination(
                    super::PrepareHvfSnapshotV2StorageMmioDestinationInput {
                        platform: platform.clone(),
                        memory: cancelled_memory,
                        process_shell: cancelled_shell,
                        packet_io: cancelled_packet_io,
                        mmds_metrics: cancelled_mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        serial_output: cancelled_serial,
                        bundle: cancelled_bundle,
                        plan: cancelled_plan,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation,
                    },
                )
                .expect_err("cancellation should prevent private MMIO storage commit");
                assert!(!cancelled.is_terminal());
                assert!(matches!(
                    cancelled,
                    super::PrepareHvfSnapshotV2StorageDestinationError::Commit(_)
                ));
            }

            let committed_bundle =
                super::RequestedSnapshotRestoreResources::prepare_native_v2_storage_restore_bundle(
                    graph,
                    &committed_memory,
                    Instant::now(),
                    None,
                    || false,
                )
                .expect("committed storage bundle should prepare after rollback");
            let committed_serial = SharedSerialOutput::from(SharedSerialOutputBuffer::default());
            let committed_shell =
                super::HvfSnapshotV2DefaultProcessShell::new(committed_serial.clone());
            let (committed_packet_io, committed_mmds_metrics) =
                ProcessNetworkPacketIoProvider::from_controller(
                    &source_controller,
                    ProcessVmnetAuthority::Direct,
                )
                .expect("committed storage packet I/O should prepare");
            let (session, controller_commit, returned_serial) = if pci_enabled {
                let committed_plan =
                    bangbang_hvf::prepare_hvf_snapshot_v2_storage_pci_platform_plan(
                        &platform,
                        committed_bundle
                            .bundle()
                            .expect("committed PCI storage bundle owner should remain present"),
                    )
                    .expect("committed PCI storage platform plan should prepare");
                super::prepare_hvf_native_v2_storage_pci_destination(
                    super::PrepareHvfSnapshotV2StoragePciDestinationInput {
                        platform,
                        memory: committed_memory,
                        process_shell: committed_shell,
                        packet_io: committed_packet_io,
                        mmds_metrics: committed_mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        serial_output: committed_serial,
                        bundle: committed_bundle,
                        plan: committed_plan,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation: NativeV2SnapshotCaptureCancellation::default(),
                    },
                )
                .unwrap_or_else(|error| {
                    panic!("private exact-2.6 PCI storage destination should commit: {error:?}")
                })
            } else {
                let committed_plan =
                    bangbang_hvf::prepare_hvf_snapshot_v2_storage_mmio_platform_plan(
                        &platform,
                        committed_bundle
                            .bundle()
                            .expect("committed MMIO storage bundle owner should remain present"),
                        process,
                    )
                    .expect("committed MMIO storage platform plan should prepare");
                super::prepare_hvf_native_v2_storage_mmio_destination(
                    super::PrepareHvfSnapshotV2StorageMmioDestinationInput {
                        platform,
                        memory: committed_memory,
                        process_shell: committed_shell,
                        packet_io: committed_packet_io,
                        mmds_metrics: committed_mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        serial_output: committed_serial,
                        bundle: committed_bundle,
                        plan: committed_plan,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation: NativeV2SnapshotCaptureCancellation::default(),
                    },
                )
                .unwrap_or_else(|error| {
                    panic!("private exact-2.6 MMIO storage destination should commit: {error:?}")
                })
            };
            assert!(!controller_commit.resume_requested());
            let mut restored_controller = VmmController::new(
                format!("native-v2-storage-{case}-destination"),
                "0.1.0",
                "bangbang",
            );
            assert!(!restored_controller.commit_snapshot_v2_load(controller_commit));
            assert_eq!(restored_controller.machine_config(), machine);
            assert_eq!(restored_controller.boot_source_config(), Some(&boot));
            assert_eq!(
                restored_controller.drive_configs(),
                expected_configs.drives()
            );
            assert_eq!(restored_controller.pmem_configs(), expected_configs.pmem());
            assert_eq!(
                restored_controller.instance_info().state,
                InstanceState::Paused
            );
            assert_eq!(
                returned_serial.metrics(),
                bangbang_runtime::serial::SerialOutputMetrics::default()
            );
            match &session {
                super::HvfProcessSession::Boot(supervisor) => {
                    assert_eq!(supervisor.status(), BootRunLoopWorkerStatus::Paused);
                }
                super::HvfProcessSession::SnapshotV2(_) => {
                    panic!("exact-2.6 storage handoff should use the boot supervisor");
                }
                super::HvfProcessSession::SerialSnapshotV2(_) => {
                    panic!("exact-2.6 storage handoff should not use the serial wrapper");
                }
            }
            drop(session);
        }
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_serial_destination_reconciles_and_recaptures_private_owner() {
        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());

        for (case, pci_enabled) in [("mmio", false), ("pci", true)] {
            let kernel = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-serial-{case}-kernel"),
                &image,
            );
            let sink = TempFilePath::create(&format!("signed-native-v2-serial-{case}-sink"));
            let mut source_controller = VmmController::new(
                format!("native-v2-serial-{case}-source"),
                "0.1.0",
                "bangbang",
            );
            source_controller
                .handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(1, 16)))
                .expect("serial source machine should configure");
            source_controller
                .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                    kernel.path(),
                )))
                .expect("serial source boot metadata should configure");

            let source_serial = SharedSerialOutput::from(SharedSerialOutputBuffer::default());
            let mut source_config = default_hvf_boot_session_config(source_serial);
            if pci_enabled {
                source_config = source_config.with_pci_enabled();
            }
            let mut source_session =
                super::OwnedHvfArm64BootSession::new(&source_controller, source_config)
                    .expect("signed exact-2.7 source should prepare");
            let restored_layout =
                GuestMemoryLayout::new(source_session.runtime_resources().layout.ranges().to_vec())
                    .expect("serial destination layout should validate");
            let copy_source_memory = || {
                let mut destination = GuestMemory::allocate(&restored_layout)
                    .expect("serial destination memory should allocate");
                let source = source_session
                    .guest_memory()
                    .expect("serial source memory should remain mapped");
                let mut buffer = vec![0_u8; 64 * 1024];
                for range in restored_layout.ranges() {
                    let mut copied = 0_u64;
                    while copied < range.size() {
                        let count = usize::try_from(
                            (range.size() - copied).min(
                                u64::try_from(buffer.len())
                                    .expect("serial copy buffer length should fit u64"),
                            ),
                        )
                        .expect("serial memory copy length should fit usize");
                        let address = range
                            .start()
                            .checked_add(copied)
                            .expect("serial memory copy address should fit");
                        source
                            .read_slice(&mut buffer[..count], address)
                            .expect("serial source memory should read");
                        destination
                            .write_slice(&buffer[..count], address)
                            .expect("serial destination memory should write");
                        copied += u64::try_from(count).expect("serial copy length should fit u64");
                    }
                }
                destination
            };
            let cancelled_memory = copy_source_memory();
            let committed_memory = copy_source_memory();

            source_session
                .pause_for_snapshot_v2_capture()
                .expect("serial source topology should pause");
            let capture_boot = || {
                HvfSnapshotV2BootState::try_new(
                    HvfSnapshotV2NativePath::try_new(kernel.path().as_os_str())
                        .expect("serial source kernel path should validate"),
                    None,
                    None,
                )
                .expect("serial source boot state should validate")
            };
            let mut memory_output = Cursor::new(Vec::new());
            let platform = source_session
                .capture_snapshot_v2_serial_platform_with_cancel(
                    HvfArm64BootSnapshotV2CaptureInput::new(capture_boot()),
                    &mut memory_output,
                    |_| false,
                )
                .expect("signed exact-2.7 serial platform should capture");
            source_session
                .shutdown()
                .expect("serial source should shut down");

            let machine = snapshot_destination_machine_config(platform.machine().machine(), false);
            let boot = super::native_v2_boot_source_config(platform.machine().boot())
                .expect("serial destination boot projection should validate");
            let sink_selector = sink
                .path()
                .to_str()
                .expect("serial destination path should be UTF-8");
            let serial_config = SerialConfigInput::new()
                .with_serial_out_path(sink_selector)
                .validate()
                .expect("serial destination output should validate");
            let captured_device = native_v2_serial_full_receive_interrupt_state();
            let serial_state = SnapshotV2SerialState::try_new(
                SnapshotV2SerialEndpointIntent::try_configured_output(sink_selector)
                    .expect("serial destination endpoint should validate"),
                None,
                captured_device.clone(),
            )
            .expect("complete serial destination state should validate");

            let cancelled_bundle =
                crate::snapshot_serial_restore::prepare_native_v2_serial_restore_bundle(
                    None,
                    serial_state.clone(),
                    None,
                    || false,
                )
                .expect("cancelled serial destination bundle should prepare");
            let (cancelled_packet_io, cancelled_mmds_metrics) =
                ProcessNetworkPacketIoProvider::from_controller(
                    &source_controller,
                    ProcessVmnetAuthority::Direct,
                )
                .expect("cancelled serial packet I/O should prepare");
            let cancellation = NativeV2SnapshotCaptureCancellation::default();
            cancellation.cancel();
            let cancelled = super::prepare_hvf_native_v2_serial_destination(
                super::PrepareHvfSnapshotV2SerialDestinationInput {
                    platform: platform.clone(),
                    graph: None,
                    memory: cancelled_memory,
                    pci_enabled,
                    packet_io: cancelled_packet_io,
                    mmds_metrics: cancelled_mmds_metrics,
                    vmnet_authority: ProcessVmnetAuthority::Direct,
                    bundle: cancelled_bundle,
                    machine,
                    boot: boot.clone(),
                    resume_requested: false,
                    cancellation,
                },
            )
            .expect_err("cancellation should destroy the unpublished serial destination");
            assert!(!cancelled.is_terminal());
            assert!(matches!(
                cancelled,
                super::PrepareHvfSnapshotV2SerialDestinationError::Commit(_)
            ));

            let committed_bundle =
                crate::snapshot_serial_restore::prepare_native_v2_serial_restore_bundle(
                    None,
                    serial_state,
                    None,
                    || false,
                )
                .expect("serial destination bundle should prepare after rollback");
            let (committed_packet_io, committed_mmds_metrics) =
                ProcessNetworkPacketIoProvider::from_controller(
                    &source_controller,
                    ProcessVmnetAuthority::Direct,
                )
                .expect("committed serial packet I/O should prepare");
            let (mut destination, controller_commit) =
                super::prepare_hvf_native_v2_serial_destination(
                    super::PrepareHvfSnapshotV2SerialDestinationInput {
                        platform,
                        graph: None,
                        memory: committed_memory,
                        pci_enabled,
                        packet_io: committed_packet_io,
                        mmds_metrics: committed_mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        bundle: committed_bundle,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation: NativeV2SnapshotCaptureCancellation::default(),
                    },
                )
                .unwrap_or_else(|error| {
                    panic!("private exact-2.7 {case} serial destination should commit: {error:?}")
                });

            assert!(!destination.has_storage);
            assert!(!controller_commit.resume_requested());
            let mut restored_controller = VmmController::new(
                format!("native-v2-serial-{case}-destination"),
                "0.1.0",
                "bangbang",
            );
            assert!(!restored_controller.commit_snapshot_v2_load(controller_commit));
            assert_eq!(restored_controller.machine_config(), machine);
            assert_eq!(restored_controller.boot_source_config(), Some(&boot));
            assert_eq!(restored_controller.serial_config(), &serial_config);
            assert_eq!(
                restored_controller.instance_info().state,
                InstanceState::Paused
            );
            match destination
                .session
                .as_deref()
                .expect("serial destination worker should exist")
            {
                super::HvfProcessSession::Boot(supervisor) => {
                    assert_eq!(supervisor.status(), BootRunLoopWorkerStatus::Paused);
                    let restored_pci_enabled = supervisor
                        .run_command(|session| {
                            Ok::<_, BackendError>(session.session.uses_pci_data_devices())
                        })
                        .expect("serial destination PCI owner should be inspectable");
                    assert_eq!(restored_pci_enabled, pci_enabled);
                }
                super::HvfProcessSession::SnapshotV2(_) => {
                    panic!("exact-2.7 serial handoff should use the boot supervisor");
                }
                super::HvfProcessSession::SerialSnapshotV2(_) => {
                    panic!("private exact-2.7 destination should not be recursively wrapped");
                }
            }

            destination
                .resume()
                .expect("serial destination should explicitly resume");
            let supervisor = match destination
                .session
                .as_deref()
                .expect("resumed serial destination worker should exist")
            {
                super::HvfProcessSession::Boot(supervisor) => supervisor,
                super::HvfProcessSession::SnapshotV2(_) => {
                    panic!("exact-2.7 serial handoff should retain the boot supervisor")
                }
                super::HvfProcessSession::SerialSnapshotV2(_) => {
                    panic!("private exact-2.7 destination should not be recursively wrapped")
                }
            };
            supervisor
                .pause()
                .expect("resumed serial destination should pause for recapture");
            let recaptured = supervisor
                .capture_native_v2_serial_candidate(
                    HvfArm64BootSnapshotV2CaptureInput::new(capture_boot()),
                    serial_config.clone(),
                    CaptureReadyStorageConfigs::new(Vec::new(), Vec::new()),
                    if pci_enabled {
                        SnapshotV2DeviceTransportKind::Pci
                    } else {
                        SnapshotV2DeviceTransportKind::Mmio
                    },
                    Box::new(Cursor::new(Vec::new())),
                    NativeV2SnapshotCaptureCancellation::default(),
                )
                .unwrap_or_else(|error| {
                    panic!("private exact-2.7 {case} serial destination should recapture: {error}")
                });
            let structural = decode_snapshot_v2_state_with_compatibility_version(
                &recaptured,
                NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION,
            )
            .expect("recaptured exact-2.7 serial state should decode structurally");
            let recaptured = bangbang_hvf::decode_hvf_snapshot_v2_serial_state(&structural)
                .expect("recaptured exact-2.7 serial state should cross-validate");
            assert!(recaptured.device_graph().is_none());
            assert_eq!(
                recaptured.serial().endpoint_intent(),
                &SnapshotV2SerialEndpointIntent::try_configured_output(sink_selector)
                    .expect("recaptured serial endpoint should validate")
            );
            assert_eq!(recaptured.serial().rate_limiter(), None);
            let recaptured_device = recaptured.serial().device();
            assert_eq!(
                recaptured_device.legacy_state(),
                captured_device.legacy_state()
            );
            assert_eq!(
                recaptured_device.interrupt_identification(),
                captured_device.interrupt_identification()
            );
            assert_eq!(
                recaptured_device.line_status(),
                captured_device.line_status()
            );
            assert_eq!(
                recaptured_device.modem_status(),
                captured_device.modem_status()
            );
            assert_eq!(
                recaptured_device.receive_bytes(),
                captured_device.receive_bytes()
            );
            assert!(!recaptured_device.receive_interrupt_intent_pending());
            assert!(!recaptured_device.input_ready_intent_pending());
            assert_eq!(supervisor.status(), BootRunLoopWorkerStatus::Paused);

            destination
                .shutdown()
                .expect("serial destination should release every private owner");
            assert_eq!(
                fs::read(sink.path()).expect("serial destination sink should remain readable"),
                b""
            );
        }
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    #[ignore = "requires the signed native_v2_process integration group"]
    fn signed_native_v2_serial_storage_destination_preserves_mmio_and_pci_owners() {
        const ARM64_IMAGE_HEADER_SIZE: usize = 64;
        const ARM64_IMAGE_SIZE_OFFSET: usize = 16;
        const ARM64_IMAGE_MAGIC_OFFSET: usize = 56;
        const ARM64_IMAGE_MAGIC: u32 = 0x644d_5241;
        const ARM64_BRANCH_TO_SELF: u32 = 0x1400_0000;

        let mut image = vec![0_u8; ARM64_IMAGE_HEADER_SIZE];
        image[..4].copy_from_slice(&ARM64_BRANCH_TO_SELF.to_le_bytes());
        image[ARM64_IMAGE_SIZE_OFFSET..ARM64_IMAGE_SIZE_OFFSET + 8]
            .copy_from_slice(&(ARM64_IMAGE_HEADER_SIZE as u64).to_le_bytes());
        image[ARM64_IMAGE_MAGIC_OFFSET..ARM64_IMAGE_MAGIC_OFFSET + 4]
            .copy_from_slice(&ARM64_IMAGE_MAGIC.to_le_bytes());

        for (case, pci_enabled) in [("mmio", false), ("pci", true)] {
            let kernel = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-serial-storage-{case}-kernel"),
                &image,
            );
            let root = TempFilePath::create_with_bytes(
                &format!("signed-native-v2-serial-storage-{case}-root"),
                &[0_u8; 4096],
            );
            let sink =
                TempFilePath::create(&format!("signed-native-v2-serial-storage-{case}-sink"));
            let mut source_controller = VmmController::new(
                format!("native-v2-serial-storage-{case}-source"),
                "0.1.0",
                "bangbang",
            );
            source_controller
                .handle_action(VmmAction::PutMachineConfig(MachineConfigInput::new(1, 16)))
                .expect("serial-storage source machine should configure");
            source_controller
                .handle_action(VmmAction::PutBootSource(BootSourceConfigInput::new(
                    kernel.path(),
                )))
                .expect("serial-storage source boot metadata should configure");
            source_controller
                .handle_action(VmmAction::PutDrive(
                    DriveConfigInput::new("rootfs", "rootfs", root.path(), true)
                        .with_is_read_only(true)
                        .with_io_engine(DriveIoEngine::Sync),
                ))
                .expect("serial-storage source root should configure");

            let source_serial = SharedSerialOutput::from(SharedSerialOutputBuffer::default());
            let mut source_config = default_hvf_boot_session_config(source_serial);
            if pci_enabled {
                source_config = source_config.with_pci_enabled();
            }
            let mut source_session =
                super::OwnedHvfArm64BootSession::new(&source_controller, source_config)
                    .expect("signed exact-2.7 serial-storage source should prepare");
            let storage_configs = CaptureReadyStorageConfigs::new(
                source_controller.drive_configs().to_vec(),
                Vec::new(),
            );
            let capture_guard = source_session
                .quiesce_limiter_retry_wakeups()
                .expect("serial-storage retry publishers should quiesce");
            let graph = source_session
                .capture_snapshot_v2_storage_device_graph_at(
                    &storage_configs,
                    &capture_guard,
                    Instant::now(),
                )
                .expect("serial-storage graph should capture");
            let expected_graph = graph.clone();

            let restored_layout =
                GuestMemoryLayout::new(source_session.runtime_resources().layout.ranges().to_vec())
                    .expect("serial-storage destination layout should validate");
            let mut destination_memory = GuestMemory::allocate(&restored_layout)
                .expect("serial-storage destination memory should allocate");
            let source_memory = source_session
                .guest_memory()
                .expect("serial-storage source memory should remain mapped");
            let mut buffer = vec![0_u8; 64 * 1024];
            for range in restored_layout.ranges() {
                let mut copied = 0_u64;
                while copied < range.size() {
                    let count = usize::try_from(
                        (range.size() - copied).min(
                            u64::try_from(buffer.len())
                                .expect("serial-storage copy buffer length should fit u64"),
                        ),
                    )
                    .expect("serial-storage memory copy length should fit usize");
                    let address = range
                        .start()
                        .checked_add(copied)
                        .expect("serial-storage memory copy address should fit");
                    source_memory
                        .read_slice(&mut buffer[..count], address)
                        .expect("serial-storage source memory should read");
                    destination_memory
                        .write_slice(&buffer[..count], address)
                        .expect("serial-storage destination memory should write");
                    copied +=
                        u64::try_from(count).expect("serial-storage copy length should fit u64");
                }
            }

            source_session
                .pause_for_snapshot_v2_capture()
                .expect("serial-storage source topology should pause");
            let capture_boot = || {
                HvfSnapshotV2BootState::try_new(
                    HvfSnapshotV2NativePath::try_new(kernel.path().as_os_str())
                        .expect("serial-storage source kernel path should validate"),
                    None,
                    None,
                )
                .expect("serial-storage source boot state should validate")
            };
            let mut memory_output = Cursor::new(Vec::new());
            let platform = source_session
                .capture_snapshot_v2_serial_platform_with_cancel(
                    HvfArm64BootSnapshotV2CaptureInput::new(capture_boot()),
                    &mut memory_output,
                    |_| false,
                )
                .expect("signed exact-2.7 serial-storage platform should capture");
            drop(capture_guard);
            source_session
                .shutdown()
                .expect("serial-storage source should shut down");

            let machine = snapshot_destination_machine_config(platform.machine().machine(), false);
            let boot = super::native_v2_boot_source_config(platform.machine().boot())
                .expect("serial-storage boot projection should validate");
            let sink_selector = sink
                .path()
                .to_str()
                .expect("serial-storage destination path should be UTF-8");
            let serial_config = SerialConfigInput::new()
                .with_serial_out_path(sink_selector)
                .validate()
                .expect("serial-storage output should validate");
            let captured_device = native_v2_serial_full_receive_interrupt_state();
            let serial_state = SnapshotV2SerialState::try_new(
                SnapshotV2SerialEndpointIntent::try_configured_output(sink_selector)
                    .expect("serial-storage endpoint should validate"),
                None,
                captured_device.clone(),
            )
            .expect("complete serial-storage state should validate");
            let bundle = crate::snapshot_serial_restore::prepare_native_v2_serial_restore_bundle(
                Some(&graph),
                serial_state,
                None,
                || false,
            )
            .expect("serial-storage destination bundle should prepare");
            let (packet_io, mmds_metrics) = ProcessNetworkPacketIoProvider::from_controller(
                &source_controller,
                ProcessVmnetAuthority::Direct,
            )
            .expect("serial-storage packet I/O should prepare");
            let (mut destination, controller_commit) =
                super::prepare_hvf_native_v2_serial_destination(
                    super::PrepareHvfSnapshotV2SerialDestinationInput {
                        platform,
                        graph: Some(graph),
                        memory: destination_memory,
                        pci_enabled,
                        packet_io,
                        mmds_metrics,
                        vmnet_authority: ProcessVmnetAuthority::Direct,
                        bundle,
                        machine,
                        boot: boot.clone(),
                        resume_requested: false,
                        cancellation: NativeV2SnapshotCaptureCancellation::default(),
                    },
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "private exact-2.7 {case} serial-storage destination should commit: {error:?}"
                    )
                });

            assert!(destination.has_storage);
            assert!(!controller_commit.resume_requested());
            let mut restored_controller = VmmController::new(
                format!("native-v2-serial-storage-{case}-destination"),
                "0.1.0",
                "bangbang",
            );
            assert!(!restored_controller.commit_snapshot_v2_load(controller_commit));
            assert_eq!(restored_controller.machine_config(), machine);
            assert_eq!(restored_controller.boot_source_config(), Some(&boot));
            assert_eq!(
                restored_controller.drive_configs(),
                storage_configs.drives()
            );
            assert!(restored_controller.pmem_configs().is_empty());
            assert_eq!(restored_controller.serial_config(), &serial_config);
            assert_eq!(
                restored_controller.instance_info().state,
                InstanceState::Paused
            );

            destination
                .resume()
                .expect("serial-storage destination should explicitly resume");
            let supervisor = match destination
                .session
                .as_deref()
                .expect("serial-storage destination worker should exist")
            {
                super::HvfProcessSession::Boot(supervisor) => supervisor,
                super::HvfProcessSession::SnapshotV2(_) => {
                    panic!("exact-2.7 serial-storage handoff should use the boot supervisor")
                }
                super::HvfProcessSession::SerialSnapshotV2(_) => {
                    panic!("private exact-2.7 destination should not be recursively wrapped")
                }
            };
            supervisor
                .pause()
                .expect("serial-storage destination should pause for recapture");
            let recaptured = supervisor
                .capture_native_v2_serial_candidate(
                    HvfArm64BootSnapshotV2CaptureInput::new(capture_boot()),
                    serial_config.clone(),
                    storage_configs.clone(),
                    if pci_enabled {
                        SnapshotV2DeviceTransportKind::Pci
                    } else {
                        SnapshotV2DeviceTransportKind::Mmio
                    },
                    Box::new(Cursor::new(Vec::new())),
                    NativeV2SnapshotCaptureCancellation::default(),
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "private exact-2.7 {case} serial-storage destination should recapture: {error}"
                    )
                });
            let structural = decode_snapshot_v2_state_with_compatibility_version(
                &recaptured,
                NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION,
            )
            .expect("recaptured serial-storage state should decode structurally");
            let recaptured = bangbang_hvf::decode_hvf_snapshot_v2_serial_state(&structural)
                .expect("recaptured serial-storage state should cross-validate");
            assert_eq!(
                recaptured
                    .device_graph()
                    .expect("recaptured storage graph should remain present"),
                &expected_graph
            );
            assert_eq!(
                recaptured.serial().endpoint_intent(),
                &SnapshotV2SerialEndpointIntent::try_configured_output(sink_selector)
                    .expect("recaptured serial-storage endpoint should validate")
            );
            assert_eq!(recaptured.serial().rate_limiter(), None);
            let recaptured_device = recaptured.serial().device();
            assert_eq!(
                recaptured_device.legacy_state(),
                captured_device.legacy_state()
            );
            assert_eq!(
                recaptured_device.interrupt_identification(),
                captured_device.interrupt_identification()
            );
            assert_eq!(
                recaptured_device.line_status(),
                captured_device.line_status()
            );
            assert_eq!(
                recaptured_device.modem_status(),
                captured_device.modem_status()
            );
            assert_eq!(
                recaptured_device.receive_bytes(),
                captured_device.receive_bytes()
            );
            assert!(!recaptured_device.receive_interrupt_intent_pending());
            assert!(!recaptured_device.input_ready_intent_pending());
            assert_eq!(supervisor.status(), BootRunLoopWorkerStatus::Paused);

            destination
                .shutdown()
                .expect("serial-storage destination should release every private owner");
            assert_eq!(
                fs::read(sink.path()).expect("serial-storage sink should remain readable"),
                b""
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn internal_native_v2_process_preflight_and_collision_skip_content_capture() {
        let running_directory = TempSnapshotDirectory::new("native-v2-process-running");
        let running_paths = running_directory.paths();
        let running_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            running_paths.state(),
            running_paths.memory(),
        );
        let mut running = configured_vmm(FakeStarter::success(172));
        running
            .handle_action(VmmAction::InstanceStart)
            .expect("native-v2 source should start");
        assert!(matches!(
            running.publish_native_v2_snapshot(&running_input),
            Err(NativeV2SnapshotPublicationError::Preflight(
                VmmActionError::UnsupportedState { .. }
            ))
        ));
        let running_session = running
            .started_session
            .as_ref()
            .expect("running preflight should retain the source");
        assert_eq!(running_session.native_snapshot_publication_count, 0);
        assert_eq!(running_session.native_snapshot_producer_count, 0);
        assert!(!running_paths.state().exists());
        assert!(!running_paths.memory().exists());
        running_directory.assert_no_staging();

        let diff_directory = TempSnapshotDirectory::new("native-v2-process-diff");
        let diff_paths = diff_directory.paths();
        let diff_input =
            SnapshotCreateInput::new(SnapshotType::Diff, diff_paths.state(), diff_paths.memory());
        let mut diff = paused_native_v2_profile_vmm(FakeStarter::success(173));
        assert!(matches!(
            diff.publish_native_v2_snapshot(&diff_input),
            Err(NativeV2SnapshotPublicationError::Preflight(
                VmmActionError::SnapshotUnsupported
            ))
        ));
        assert_eq!(
            diff.started_session
                .as_ref()
                .expect("Diff rejection should retain the source")
                .native_snapshot_publication_count,
            0
        );
        diff_directory.assert_no_staging();

        let drive_directory = TempSnapshotDirectory::new("native-v2-process-drive");
        let drive_paths = drive_directory.paths();
        let drive_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            drive_paths.state(),
            drive_paths.memory(),
        );
        let mut drive = configured_vmm(FakeStarter::success(174));
        drive
            .handle_action(VmmAction::InstanceStart)
            .expect("empty-drive source should start");
        drive
            .handle_action(VmmAction::Pause)
            .expect("empty-drive source should pause");
        drive
            .publish_native_v2_snapshot(&drive_input)
            .expect("serial-only source should publish exact-2.12 Full state");
        assert_eq!(
            drive
                .started_session
                .as_ref()
                .expect("serial-only publication should retain the source")
                .native_snapshot_publication_count,
            1
        );
        assert_eq!(
            drive.starter.snapshot_storage_preflight_calls, 1,
            "serial-only publication should preflight the empty storage owner set"
        );
        let (candidate, _) = load_native_snapshot_artifacts(&drive_paths)
            .expect("serial-only pair should load")
            .into_current_v2_candidate()
            .expect("serial-only pair should close as exact-2.12 Full");
        assert!(candidate.device_graph().is_none());
        drive_directory.assert_no_staging();

        let mut vhost = configured_vmm(FakeStarter::success(186));
        vhost
            .handle_action(VmmAction::PutDrive(
                DriveConfigInput::new_without_path_on_host("root", "root", true)
                    .with_socket("/private/native-v2-vhost.sock"),
            ))
            .expect("vhost-user source should configure");
        assert!(matches!(
            vhost.native_v2_multi_block_candidate_product_profile(),
            Err(NativeV2MultiBlockCandidateProfileError::DriveProfile(_))
        ));

        let mut pmem = configured_vmm(FakeStarter::success(187));
        pmem.handle_action(VmmAction::PutDrive(DriveConfigInput::new(
            "root",
            "root",
            "/tmp/pmem-rootfs",
            true,
        )))
        .expect("pmem source root should configure");
        pmem.handle_action(VmmAction::PutPmem(PmemConfigInput::new(
            "pmem0",
            "/private/native-v2-pmem",
        )))
        .expect("pmem source should configure");
        assert!(matches!(
            pmem.native_v2_multi_block_candidate_product_profile(),
            Err(NativeV2MultiBlockCandidateProfileError::OptionalDevices)
        ));

        let optional_directory = TempSnapshotDirectory::new("native-v2-process-optional");
        let optional_paths = optional_directory.paths();
        let mut optional = configured_vmm(FakeStarter::success(188));
        optional
            .handle_action(VmmAction::PutDrive(DriveConfigInput::new(
                "root",
                "root",
                "/tmp/optional-rootfs",
                true,
            )))
            .expect("optional-device source root should configure");
        optional
            .handle_action(VmmAction::PutBalloon(BalloonConfigInput::new(64, false)))
            .expect("optional balloon should configure");
        optional
            .handle_action(VmmAction::InstanceStart)
            .expect("optional-device source should start");
        optional
            .handle_action(VmmAction::Pause)
            .expect("optional-device source should pause");
        optional
            .publish_native_v2_snapshot(&SnapshotCreateInput::new(
                SnapshotType::Full,
                optional_paths.state(),
                optional_paths.memory(),
            ))
            .expect("balloon source should publish exact-2.12 Full state");
        assert_eq!(
            optional.starter.snapshot_storage_preflight_calls, 1,
            "balloon publication should preflight the storage owner set"
        );
        let (candidate, _) = load_native_snapshot_artifacts(&optional_paths)
            .expect("balloon publication should load")
            .into_current_v2_candidate()
            .expect("balloon publication should close as exact-2.12 Full");
        assert!(candidate.balloon().is_some());
        optional_directory.assert_no_staging();

        let serial_directory = TempSnapshotDirectory::new("native-v2-process-serial");
        let serial_paths = serial_directory.paths();
        let serial_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            serial_paths.state(),
            serial_paths.memory(),
        );
        let mut serial = snapshot_profile_vmm(FakeStarter::success(175));
        let serial_sink = TempFilePath::create("native-v2-process-serial-output");
        serial
            .handle_action(VmmAction::PutSerial(
                SerialConfigInput::new()
                    .with_serial_out_path(serial_sink.path().to_string_lossy())
                    .with_rate_limiter(SerialRateLimiterConfig::new(1, None, 1_000)),
            ))
            .expect("custom serial config should store");
        serial
            .handle_action(VmmAction::InstanceStart)
            .expect("custom serial source should start");
        serial
            .handle_action(VmmAction::Pause)
            .expect("custom serial source should pause");
        serial
            .publish_native_v2_snapshot(&serial_input)
            .expect("configured serial state should publish in exact-2.12 Full");
        assert_eq!(
            serial
                .started_session
                .as_ref()
                .expect("serial publication should retain the source")
                .native_snapshot_publication_count,
            1
        );
        assert_eq!(
            serial.starter.snapshot_storage_preflight_calls, 1,
            "configured serial publication should preflight every capture owner"
        );
        let (candidate, _) = load_native_snapshot_artifacts(&serial_paths)
            .expect("configured serial snapshot should load")
            .into_current_v2_candidate()
            .expect("configured serial snapshot should close as exact-2.12 Full");
        assert_eq!(
            candidate.serial().rate_limiter(),
            Some(SerialRateLimiterConfig::new(1, None, 1_000))
        );
        assert_eq!(
            candidate.serial().endpoint_intent().configured_selector(),
            Some(
                serial_sink
                    .path()
                    .to_str()
                    .expect("serial sink path should be UTF-8")
            )
        );
        serial_directory.assert_no_staging();

        let live_serial_directory = TempSnapshotDirectory::new("native-v2-process-live-serial");
        let live_serial_paths = live_serial_directory.paths();
        let mut live_serial = paused_native_v2_profile_vmm(FakeStarter::success(189));
        live_serial.starter.snapshot_serial_preflight_canonical = false;
        live_serial
            .publish_native_v2_snapshot(&SnapshotCreateInput::new(
                SnapshotType::Full,
                live_serial_paths.state(),
                live_serial_paths.memory(),
            ))
            .expect("live serial capture should no longer be rejected as noncanonical");
        assert_eq!(live_serial.starter.snapshot_serial_preflight_calls, 1);
        let live_serial_session = live_serial
            .started_session
            .as_ref()
            .expect("live serial publication should retain the source");
        assert_eq!(live_serial_session.native_snapshot_publication_count, 1);
        assert_eq!(live_serial_session.native_snapshot_producer_count, 1);
        assert!(live_serial_paths.state().exists());
        assert!(live_serial_paths.memory().exists());
        live_serial_directory.assert_no_staging();

        let unavailable_directory = TempSnapshotDirectory::new("native-v2-process-no-session");
        let unavailable_paths = unavailable_directory.paths();
        let unavailable_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            unavailable_paths.state(),
            unavailable_paths.memory(),
        );
        let mut unavailable = paused_native_v2_profile_vmm(FakeStarter::success(177));
        unavailable.started_session = None;
        assert!(matches!(
            unavailable.publish_native_v2_snapshot(&unavailable_input),
            Err(NativeV2SnapshotPublicationError::SessionUnavailable)
        ));
        unavailable_directory.assert_no_staging();

        let collision_directory = TempSnapshotDirectory::new("native-v2-process-collision");
        let collision_paths = collision_directory.paths();
        fs::write(collision_paths.state(), b"winner").expect("existing final should create");
        let collision_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            collision_paths.state(),
            collision_paths.memory(),
        );
        let mut collision = paused_native_v2_profile_vmm(FakeStarter::success(178));
        assert!(matches!(
            collision.publish_native_v2_snapshot(&collision_input),
            Err(NativeV2SnapshotPublicationError::Transaction(_))
        ));
        let collision_session = collision
            .started_session
            .as_ref()
            .expect("collision should retain the source");
        assert_eq!(collision_session.native_snapshot_publication_count, 1);
        assert_eq!(collision_session.native_snapshot_producer_count, 0);
        assert_eq!(
            fs::read(collision_paths.state()).expect("winner should remain"),
            b"winner"
        );
        assert!(!collision_paths.memory().exists());
        collision_directory.assert_no_staging();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn internal_native_v1_publication_commits_composite_pair_without_controller_mutation() {
        let directory = TempSnapshotDirectory::new("process-success");
        let paths = directory.paths();
        let input = SnapshotCreateInput::new(SnapshotType::Full, paths.state(), paths.memory());
        let mut vmm = snapshot_profile_vmm(FakeStarter::success(19));
        vmm.handle_action(VmmAction::InstanceStart)
            .expect("startup should succeed");
        vmm.handle_action(VmmAction::Pause)
            .expect("source should pause");
        let machine_before = vmm.machine_config();
        let drive_before = vmm.drive_configs()[0].clone();

        let durability = vmm
            .publish_native_v1_snapshot(&input)
            .expect("internal native-v1 publication should succeed");

        assert_eq!(durability, SnapshotCommitDurability::Durable);
        assert_eq!(vmm.instance_info().state, InstanceState::Paused);
        assert_eq!(vmm.machine_config(), machine_before);
        assert_eq!(vmm.drive_configs(), [drive_before]);
        let session = vmm
            .started_session
            .as_ref()
            .expect("source session should remain retained");
        assert_eq!(session.native_snapshot_publication_count, 1);
        assert_eq!(session.native_snapshot_producer_count, 1);
        assert_eq!(session.snapshot_create_barrier_count, 0);

        let artifacts = load_snapshot_artifacts(&paths).expect("committed pair should load");
        assert_eq!(artifacts.record().kind(), SnapshotCommitKind::Composite);
        assert_eq!(
            artifacts.record().composite_state(),
            Some(b"fake-process-native-v1-state".as_slice())
        );
        directory.assert_no_staging();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn internal_native_v1_preflight_and_path_collision_skip_content_capture() {
        let running_directory = TempSnapshotDirectory::new("process-running");
        let running_paths = running_directory.paths();
        let running_input = SnapshotCreateInput::new(
            SnapshotType::Full,
            running_paths.state(),
            running_paths.memory(),
        );
        let mut running = snapshot_profile_vmm(FakeStarter::success(20));
        running
            .handle_action(VmmAction::InstanceStart)
            .expect("startup should succeed");
        assert!(matches!(
            running.publish_native_v1_snapshot(&running_input),
            Err(NativeV1SnapshotPublicationError::Preflight(
                VmmActionError::UnsupportedState { .. }
            ))
        ));
        let running_session = running
            .started_session
            .as_ref()
            .expect("running session should remain retained");
        assert_eq!(running_session.native_snapshot_publication_count, 0);
        assert_eq!(running_session.native_snapshot_producer_count, 0);

        let collision_directory = TempSnapshotDirectory::new("process-collision");
        let collision = collision_directory.path.join("same.snap");
        let collision_input = SnapshotCreateInput::new(SnapshotType::Full, &collision, &collision);
        let mut paused = snapshot_profile_vmm(FakeStarter::success(21));
        paused
            .handle_action(VmmAction::InstanceStart)
            .expect("startup should succeed");
        paused
            .handle_action(VmmAction::Pause)
            .expect("source should pause");

        let error = paused
            .publish_native_v1_snapshot(&collision_input)
            .expect_err("aliased finals should reject before content capture");
        assert!(matches!(
            error,
            NativeV1SnapshotPublicationError::Transaction(_)
        ));
        let paused_session = paused
            .started_session
            .as_ref()
            .expect("paused session should remain retained");
        assert_eq!(paused_session.native_snapshot_publication_count, 1);
        assert_eq!(paused_session.native_snapshot_producer_count, 0);
        assert_eq!(paused.instance_info().state, InstanceState::Paused);
        assert!(!collision.exists());
        collision_directory.assert_no_staging();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn public_snapshot_create_publishes_native_v2_pair_without_legacy_barrier() {
        let directory = TempSnapshotDirectory::new("public-create-success");
        let paths = directory.paths();
        let input = SnapshotCreateInput::new(SnapshotType::Full, paths.state(), paths.memory());
        let barrier_error = BackendError::Hypervisor("legacy-barrier-must-not-run".to_owned());
        let mut vmm = configured_vmm(FakeStarter::success_with_session(
            FakeSession::with_snapshot_create_barrier_result(22, barrier_error),
        ));
        vmm.handle_action(VmmAction::PutDrive(
            DriveConfigInput::new("root", "root", "/tmp/rootfs", true)
                .with_is_read_only(true)
                .with_io_engine(DriveIoEngine::Sync),
        ))
        .expect("native-v2 root should configure");
        vmm.handle_action(VmmAction::InstanceStart)
            .expect("startup should succeed");
        vmm.handle_action(VmmAction::Pause)
            .expect("source should pause");

        assert_eq!(
            vmm.handle_action(VmmAction::CreateSnapshot(input)),
            Ok(VmmData::Empty)
        );
        let session = vmm
            .started_session
            .as_ref()
            .expect("source session should remain retained");
        assert_eq!(session.snapshot_create_barrier_count, 0);
        assert_eq!(session.native_snapshot_publication_count, 1);
        assert_eq!(session.native_snapshot_producer_count, 1);
        let artifacts =
            load_native_snapshot_artifacts(&paths).expect("public pair should validate");
        assert_eq!(artifacts.family(), NativeSnapshotArtifactFamily::V2);
        directory.assert_no_staging();
    }

    #[test]
    fn native_v1_publication_errors_redact_capture_details_and_reject_kind_one() {
        let producer = NativeV1SnapshotPublicationProducerError::Capture(
            NativeV1SnapshotCaptureError::Supervisor {
                source: BackendError::Hypervisor("private-capture-sentinel".to_string()),
            },
        );
        let diagnostics = format!("{producer:?} {producer}");
        assert!(!diagnostics.contains("private-capture-sentinel"));

        let range = GuestMemoryRange::new(GuestAddress::new(0x8000_0000), 16 * 1024)
            .expect("kind-one fixture range should validate");
        let layout =
            GuestMemoryLayout::new(vec![range]).expect("kind-one fixture layout should validate");
        let memory = GuestMemory::allocate(&layout).expect("kind-one fixture should allocate");
        let mut bytes = Cursor::new(Vec::new());
        let binding = write_snapshot_memory_image(&memory, &mut bytes)
            .expect("kind-one fixture should encode");
        assert!(matches!(
            require_native_v1_composite_record(SnapshotCommitRecord::new(binding)),
            Err(NativeV1SnapshotPublicationProducerError::NonCompositeCommit)
        ));
    }

